window.__SUM[15]={"LR005389":{"pair":"A2M -> HSPA5","headline":"Purified GRP78 binds activated alpha2-macroglobulin with a reported Kd of about 150 pM, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Purified Grp 78 binds alpha(2)M* with high affinity; a monoclonal antibody against Grp 78 abolished alpha(2)M*-induced signal transduction [PMID:12194978]. Direction and agonist/antagonist role: not reported beyond this.","molecular_requirements":"The binding is to the receptor-recognized activated form alpha(2)M*, not native A2M [PMID:12194978]. LRP co-precipitated with the Grp 78 antibody and was not necessary for the signalling by RNA interference (abstract truncated) [PMID:12194978].","affinity_potency":[{"value":"Kd approximately 150 pM","assay":"equilibrium binding, purified Grp 78 to alpha(2)M*","system":"purified protein; Grp 78 from 1-LN human prostate cancer cells","cite":"PMID:12194978"}],"species_and_systems":"Binding partners purified from human 1-LN prostate cancer cells and murine macrophages; mouse pair is ortholog-inferred [PMID:12194978].","localisation_and_range":"Grp 78 is shown on the cell surface of 1-LN cells by flow cytometry; A2M is flagged secreted [PMID:12194978] [flag].","caveats":"One paper, abstract only. A BioGRID record cites the same paper (Reconstituted Complex) [DB:BioGRID]. Two other judged rows were abstract-insufficient.","key_references":[{"PMID":"12194978","why":"Kd of purified Grp 78 for alpha(2)M* and signalling block"}],"covers":["LR002063","LR005389"]},"LR000001":{"pair":"A2M -> LRP1","headline":"A2M is the classic LRP1 ligand: structural, ligand-blot and receptor purification evidence, with one weak NMR Kd.","interaction_type":"direct binding","direction_and_effect":"Placental alpha2-macroglobulin receptor chains are the alpha and beta subunits of LRP, so LRP is suggested to be the receptor for alpha 2M-proteinase complexes [PMID:1702392]. Alpha(2)M* binds LRP heavy chains by ligand blotting [PMID:12194978]. A curator annotation marks the effect as stimulatory (annotation, not from the abstracts).","molecular_requirements":"The NMR study used complement-like repeat CR3 of LRP against the A2M receptor binding domain, so a single repeat is enough for weak binding [PMID:10652313]. Receptor-recognized alpha(2)M* is the binding form [PMID:12194978]. Silencing LRP did not stop alpha(2)M*-induced signalling via Grp 78 [PMID:12194978].","affinity_potency":[{"value":"Kd approximately 140 microM","assay":"NMR, LRP CR3 with A2M receptor binding domain","system":"isolated domains","cite":"PMID:10652313"}],"species_and_systems":"Human proteins in NMR and purification studies; species unspecified for the placental receptor paper [PMID:10652313, PMID:1702392]. Mouse pair is ortholog-inferred.","localisation_and_range":"A2M is flagged secreted [flag]; LRP described as a scavenger receptor [PMID:12194978].","caveats":"All papers read as abstracts only. The 140 microM Kd is for a single repeat and is called relatively weak [PMID:10652313]. The 1990 paper rests on sequence identity, not a binding measurement [PMID:1702392]. BioGRID lists a co-crystal structure record [DB:BioGRID].","key_references":[{"PMID":"1702392","why":"Identifies LRP as the alpha2-macroglobulin receptor"},{"PMID":"10652313","why":"NMR evidence for CR3 binding to A2M receptor binding domain"},{"PMID":"12194978","why":"Ligand blot of alpha(2)M* on LRP"}],"covers":["LR000001","LR003551"]},"LR010879":{"pair":"ABCA1 -> SHANK1","headline":"No papers; only a single IntAct holdup-assay record, and the pair is not judged a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species human; no experiment described in a paper in our evidence.","localisation_and_range":"ABCA1 is flagged as receptor and transmembrane [flag]; SHANK1 carries no receptor flag [flag].","caveats":"Rests on one IntAct record described as direct interaction by holdup assay [DB:IntAct]. Curator judgment on the one judged row was 'different entity', and no paper was judged.","key_references":[],"covers":["LR010879"]},"LR000010":{"pair":"ADAM15 -> ITGB1","headline":"Integrin beta1 is implicated as partner of alpha9 and alpha5 in two abstract-only ADAM binding papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]. Metargidin binds MOLT-4 cells in part through alpha5beta1 [PMID:9914169].","molecular_requirements":"Evidence is for alpha9beta1 and alpha5beta1 heterodimers, so the matching alpha chain is required; beta1 alone is not shown [PMID:10944520, PMID:9914169].","affinity_potency":[],"species_and_systems":"Recombinant disintegrin domain and ADAM15-Fc chimera on human cell lines [PMID:9914169]; species not reported for PMID:10944520.","localisation_and_range":"ADAM15 flagged not secreted [flag].","caveats":"Both abstract only; chain-only evidence for ITGB1. One judged row is still pending.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-15 disintegrin domain"},{"PMID":"9914169","why":"alpha5beta1 contribution to ADAM15 binding"}],"covers":["LR000010","LR003560"]},"LR005398":{"pair":"ADAM23 -> ITGAV","headline":"ADAM23 disintegrin domain binds integrin alphavbeta3 and negatively modulates its activation; two abstract-only papers, human.","interaction_type":"direct binding","direction_and_effect":"ADAM23 disintegrin-like domain promotes cell adhesion via alphavbeta3 by an RGD-independent mechanism [PMID:10749942]. ADAM23 knockdown enhanced alphavbeta3 activation by at least 2- to 4-fold, indicating a negative modulator (curator label: antagonist) [PMID:19549921].","molecular_requirements":"Binding is mediated by a short sequence in the disintegrin loop lacking an RGD motif; alphav pairs with beta3 [PMID:10749942].","affinity_potency":[],"species_and_systems":"Human neural and astrocytoma cells, transfected HeLa [PMID:10749942]; MDA-MB-435 cells and immunodeficient mice [PMID:19549921].","localisation_and_range":"ADAM23 flagged secreted and receptor [flag]; the studies used the cell-bound and recombinant domain.","caveats":"Both abstract only. The two papers describe different effects (adhesion-promoting versus negative modulation of activation).","key_references":[{"PMID":"10749942","why":"ADAM23 disintegrin binds alphavbeta3, RGD-independent"},{"PMID":"19549921","why":"ADAM23 negatively modulates alphavbeta3 activation"}],"covers":["LR002072","LR005398"]},"LR008188":{"pair":"ADAM9 -> ITGAV:ITGB5","headline":"ADAM9 disintegrin domain mediates alphaVbeta5-dependent adhesion; functional evidence from one abstract-only paper plus a BioGRID record.","interaction_type":"functional only","direction_and_effect":"Myeloma cell adhesion to the recombinant ADAM9 (MDC-9) disintegrin domain was completely blocked by anti-alpha(v)beta(5) and by no other anti-subunit antibody; RGD peptides had no effect, so binding is RGD-independent [PMID:11162558].","molecular_requirements":"Binding was divalent-cation dependent (Mn2+ and Ca2+) [PMID:11162558]. Heterodimer alphaVbeta5 is the implicated unit.","affinity_potency":[],"species_and_systems":"Human; myeloma cells adhering to immobilised recombinant disintegrin domain; lymphoblastoid cells did not bind and did not express alpha(v)beta(5) [PMID:11162558].","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Inference rests on antibody inhibition read from the abstract only [PMID:11162558]; direct binding to purified integrin is not shown. BioGRID lists an ITGB5-ADAM9 Affinity Capture-Western record [DB:BioGRID] (PMID:16373656). Affinity not reported.","key_references":[{"PMID":"11162558","why":"antibody block of adhesion to ADAM9 disintegrin domain by anti-alphaVbeta5"},{"PMID":"16373656","why":"BioGRID Affinity Capture-Western record (not read by curators)"}],"covers":["LR008188"]},"LR009682":{"pair":"AFDN -> F11R","headline":"Database-only protein interaction between AFDN and F11R; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted complex and affinity capture-Western records for F11R with MLLT4 (AFDN) [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; F11R flagged receptor and transmembrane [flag]. Five papers were abstract_insufficient.","caveats":"No confirming papers; judged papers were different_entity (1) or abstract_insufficient (5). Support is database-only (reconstituted complex and Western capture, not a ligand-receptor assay).","key_references":[],"covers":["LR009682"]},"LR003589":{"pair":"AGRN -> LRP4","headline":"LRP4 is identified as a receptor for agrin that activates MuSK; well supported by a landmark paper and structure/pathway records.","interaction_type":"direct binding","direction_and_effect":"Lrp4 is reported to be a receptor for Agrin, to form a complex with MuSK and to mediate MuSK activation by Agrin [PMID:18848351]. Effect is agonist/stimulatory. Reactome lists an AGRN:LRP4:MUSK complex [DB:Reactome].","molecular_requirements":"Lrp4 forms a complex with MuSK, and MuSK activation by agrin runs through Lrp4 [PMID:18848351]. A PDB structure contains chains of agrin and LRP4 [DB:PDB 8S9P].","affinity_potency":[],"species_and_systems":"The paper's excerpts describe BaF3 cells expressing Lrp4 binding to substrate-attached Agrin [PMID:18848351]; the curator tags both species as human, which the excerpt does not confirm. Mouse entry is not ortholog-inferred; human is.","localisation_and_range":"Agrin is an extracellular matrix protein presented to muscle cells [PMID:18848351].","caveats":"Paper read as abstract plus excerpts; the binding assay is cell adhesion to agrin, with no affinity reported in our evidence.","key_references":[{"PMID":"18848351","why":"Identifies Lrp4 as an agrin receptor that complexes with MuSK"}],"covers":["LR000039","LR003589"]},"LR003598":{"pair":"AGT -> MAS1","headline":"Mas is a functional receptor for angiotensin-(1-7) in mouse knockout and transfected-cell data; the ligand is a processed AGT peptide.","interaction_type":"direct binding","direction_and_effect":"Ang-(1-7) acts as an agonist at Mas: Mas deletion abolished Ang-(1-7) binding to mouse kidney, the antidiuretic action and aortic relaxation; Ang-(1-7) bound Mas-transfected cells and elicited arachidonic acid release [PMID:12829792]. Reactome lists an AGT(25-31):MAS1 complex [DB:Reactome R-HSA-9944535].","molecular_requirements":"Not reported in our evidence beyond Mas itself.","affinity_potency":[],"species_and_systems":"Mouse knockout tissues and Mas-transfected cells; curator records human ligand, mouse receptor. Human and mouse pairs are both ortholog-inferred [PMID:12829792].","localisation_and_range":"Ligand flagged secreted, so likely endocrine or paracrine [flag].","caveats":"Single paper, abstract only. The ligand is Ang-(1-7), not full-length AGT or Ang II. Pair rests on one paper plus one Reactome record. No affinity reported.","key_references":[{"PMID":"12829792","why":"Mas knockout abolishes Ang-(1-7) binding and responses"}],"covers":["LR000048","LR003598"]},"LR007099":{"pair":"APOA1 -> AMN:CUBN","headline":"Asserted by Reactome and UniProt only; no curator-verified paper for the AMN:CUBN complex.","interaction_type":"database-asserted only","direction_and_effect":"Reactome has a binding reaction in which apoA-I binds CUBN:AMN and an apoA-I:CUBN:AMN complex at the plasma membrane [DB:Reactome]. UniProt states that CUBN binds APOA1 [DB:UniProt]. Effect is not reported in our evidence.","molecular_requirements":"Both AMN and CUBN are listed as members of the receptor complex [flag]; whether CUBN alone is enough is not reported here (see the separate APOA1 -> CUBN dossier).","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"Receptor complex carries transmembrane and receptor flags [flag]; the Reactome complex is at the plasma membrane [DB:Reactome].","caveats":"Two papers were judged abstract_insufficient, so support comes from database records alone.","key_references":[],"covers":["LR007099"]},"LR009718":{"pair":"APOC4 -> VLDLR","headline":"No paper evidence; the only database record concerns VLDL binding VLDLR, not APOC4.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species in our evidence.","localisation_and_range":"Receptor is flagged transmembrane [flag]; ligand localisation not flagged.","caveats":"The one judged paper was classed different_entity (not about this pair). Reactome records describe 'VLDLR binds VLDL' (R-HSA-8854462), which does not name APOC4 [DB:Reactome]. No support for this pair is shown.","key_references":[],"covers":["LR009718"]},"LR005479":{"pair":"APP -> NOTCH1","headline":"Co-immunoprecipitation only; secondary finding in an abstract-read paper focused on Notch2.","interaction_type":"direct binding","direction_and_effect":"Notch1 co-immunoprecipitated with APP, suggesting cross-talk between APP and Notch family members [PMID:16118793]. Effect and direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 cells expressing APP751 and rat primary neurons for the screen [PMID:16118793]; mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged as transmembrane [flag]; APP and Notch2 colocalised on the plasma membrane in COS cells [PMID:16118793].","caveats":"Abstract only; the Notch1 result is secondary to Notch2. BioGRID lists Notch1-APP affinity capture-Western [DB:BioGRID].","key_references":[{"PMID":"16118793","why":"APP-Notch interaction by co-IP"}],"covers":["LR002164","LR005479"]},"LR000100":{"pair":"BDNF -> NGFR","headline":"proBDNF, not mature BDNF, acts on NGFR (p75NTR) with sortilin; low-affinity binding of BDNF to NGFR is also reported.","interaction_type":"direct binding","direction_and_effect":"Cells transfected with the low-affinity NGF receptor gene bind BDNF, whereas untransfected cells do not, so NGFR is a low-affinity BDNF receptor [PMID:2157470]. The precursor proBDNF is an apoptotic ligand acting at subnanomolar concentrations in sympathetic neurons coexpressing sortilin and p75NTR [PMID:15930396]; mature BDNF induces TrkB phosphorylation but proBDNF does not [PMID:15930396]. UniProt describes a receptor with SORCS2 that binds precursor forms with high affinity and mature NGF and BDNF with much lower affinity [DB:UniProt].","molecular_requirements":"The proBDNF apoptotic effect needs both p75NTR and sortilin on the cell surface; preformed soluble sortilin-proBDNF complexes failed to induce apoptosis [PMID:15930396]. UniProt describes a SORCS2 heterodimer [DB:UniProt].","affinity_potency":[],"species_and_systems":"Both papers were read as abstracts only; the abstracts do not name the species or the transfected cells [PMID:2157470][PMID:15930396]. The dossier lists a human pair with mouse also listed (ortholog-inferred human).","localisation_and_range":"BDNF has a secreted flag and NGFR a transmembrane flag [flag]; proBDNF is secreted by cultured neurons [PMID:15930396].","caveats":"Gene-level BDNF -> NGFR combines two processing states: precursor (pro-apoptotic via p75NTR/sortilin) and mature BDNF (TrkB signalling, low-affinity NGFR binding). The 1990 paper reports low affinity only and no numbers. Both papers are abstract-only. GtoPdb record lacks type and affinity [DB:GtoPdb].","key_references":[{"PMID":"2157470","why":"NGFR-transfected cells bind BDNF (low affinity)"},{"PMID":"15930396","why":"proBDNF induces apoptosis via p75NTR plus sortilin"}],"covers":["LR000100","LR003649"]},"LR005488":{"pair":"Bglap2 -> Gprc6a","headline":"Mouse pair inferred from a human-cell study showing ucOC competes with SHBG at GPRC6A; evidence is indirect.","interaction_type":"direct binding","direction_and_effect":"Undercarboxylated osteocalcin displaced SHBG from GPRC6A-transfected HEK-293 cells at 100-fold molar excess, and ucOC-induced Erk1/2 phosphorylation was blunted by excess SHBG [PMID:27673554]. UniProt lists osteocalcin among GPRC6A activators [DB:UniProt].","molecular_requirements":"Mutation constructs indicate a common binding site for ucOC and SHBG [PMID:27673554].","affinity_potency":[],"species_and_systems":"Experiments used human embryonic kidney-293 cells with human GPRC6A; the mouse pair is ortholog-inferred, with no mouse experiment in our evidence [PMID:27673554].","localisation_and_range":"Osteocalcin has a secreted flag [flag].","caveats":"No mouse data. Evidence is indirect (competition with SHBG), abstract-only, with no affinity values.","key_references":[{"PMID":"27673554","why":"human GPRC6A binding competition between ucOC and SHBG"}],"covers":["LR005488"]},"LR010798":{"pair":"BMP10 -> ACVR1","headline":"Conditional functional evidence: BMP10 signals via ALK2 (ACVR1) in myeloma cells only when FKBP12 is blocked by FK506; otherwise it antagonises ALK2 ligands.","interaction_type":"conflicting","direction_and_effect":"BMP10 activated SMAD1/5/8 via ALK2 and BMPR2 when combined with FK506 [PMID:36717825]; SMAD activation by BMP10 with FK506 was blunted in ALK2 knockout cells [PMID:36717825]. Without FK506, even high BMP10 did not induce apoptosis and antagonised BMP6- and BMP9-induced apoptosis, likely by competing for type II receptors [PMID:36717825]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Requires FKBP12 removal (FK506) and BMPR2 for full activity [PMID:36717825].","affinity_potency":[],"species_and_systems":"Human multiple myeloma cell lines (INA-6 and others), full text read [PMID:36717825].","localisation_and_range":"BMP10 has a secreted flag [flag].","caveats":"Activation under normal conditions was not shown; the effect is a FK506-induced shift in specificity. Other papers judged were review-only or insufficient. No affinity reported.","key_references":[{"PMID":"36717825","why":"BMP10 signals via ALK2 and BMPR2 only with FK506"}],"covers":["LR010798"]},"LR006784":{"pair":"BMP4 -> ACVRL1","headline":"Weak support: ACVRL1 genotype changes the response of iPSC-derived cells to BMP4-driven differentiation; no binding shown.","interaction_type":"functional only","direction_and_effect":"In a CRISPR heterozygous ACVRL1 knockout iPS line, BMP4-induced endothelial differentiation gave differential TGF-beta/BMP gene expression versus wild type; curators record an agonist effect [PMID:37371070]. GtoPdb lists BMP4 -> ACVRL1 as Agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPS cells and embryoid-body-derived endothelial cells (curator-recorded human) [PMID:37371070].","localisation_and_range":"BMP4 is flagged secreted [flag].","caveats":"BMP4 was only the differentiation stimulus; the effect on the 151 TGF-beta/BMP genes cannot be attributed to a direct BMP4-ACVRL1 interaction. Abstract plus excerpts only.","key_references":[{"PMID":"37371070","why":"ACVRL1 genotype modulates BMP4-driven differentiation response"}],"covers":["LR006784"]},"LR003679":{"pair":"BMP4 -> BMPR2","headline":"BMP4 binds BMPR2 in transfected COS cells, less efficiently than BMP7 and only with type I receptors; abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"BMP-4 bound BMPR-II in transfected COS-1 cells, less efficiently than OP-1/BMP-7 [PMID:7644468]. BRK-3 (BMPR2) specifically binds BMP-4 in COS cells [PMID:7673243]. BioGRID lists reconstituted-complex and affinity-capture records [DB:BioGRID 277022]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Type I receptor needed: BMPR-II binds ligands weakly alone, facilitated by type I receptors [PMID:7644468]; cross-linking was undetectable without BRK-1 or BRK-2 [PMID:7673243]. A super-high-affinity subpopulation formed only with BRK-2+BRK-3 [PMID:7673243].","affinity_potency":[],"species_and_systems":"COS-1 / COS transfectants, human skin fibroblast-derived cDNA [PMID:7644468; PMID:7673243]; curators record human.","localisation_and_range":"BMP4 flagged secreted; BMPR2 receptor [flag].","caveats":"Both papers abstract only; no affinity values. Binding is weak alone, so BMPR2 acts as a type II partner to a type I receptor.","key_references":[{"PMID":"7673243","why":"BMPR2 (BRK-3) binds BMP-4, forms type I/II complexes"},{"PMID":"7644468","why":"BMPR-II cloning; BMP-4 binds less efficiently than BMP-7"}],"covers":["LR000130","LR003679"]},"LR005497":{"pair":"BMP5 -> RGMB","headline":"BMP5 binds RGMB in SPR with Kd 33 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"RGMB is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. RGMB bound BMP5 less tightly than HJV (17 nM) [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 33 nM","assay":"SPR","system":"RGMB vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. RGMB is flagged not secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR002183","LR005497"]},"LR003688":{"pair":"BMP7 -> ACVR1","headline":"Direct binding of BMP7 (OP-1) to ALK-2/ACVR1 shown in 1994, supported by functional papers and database records.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP-7) bound ALK-2 efficiently [PMID:8006002]. In endogenous signalling, BMP7's major type I receptor was ALK2, and ALK2 mediated BMP7 but not activin signalling, with Smad1/5 phosphorylation [PMID:9748228]. Curated effect is agonist; GtoPdb lists BMP7 as agonist at ACVR1 [DB:GtoPdb]. Intact ACVR1-R206H (an FOP mutant) responded to Bmp7 and Activin A [PMID:32897189].","molecular_requirements":"ALK-2 is reported as a type I receptor shared by activin and OP-1 but not by BMP-4; binding was enhanced by a co-transfected type II receptor [PMID:8006002]. BMP7 and activin share type II receptors ActRII/ActRIIB but recruit distinct type I receptors [PMID:9748228]. UniProt describes ACVR1 as type I partner with type II ACVR2A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Binding in transfected COS cells and various non-transfected lines, with cell-type dependent profiles [PMID:8006002]. Signalling in P19 cells [PMID:9748228]. The 2020 paper used zebrafish embryos with mouse ACVR1 and an FOP mutant receptor [PMID:32897189]. Curators recorded human experiment species for most rows, and a mouse receptor in PMID:11282024; human and mouse pairs are both listed, neither ortholog-inferred.","localisation_and_range":"BMP7 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Most papers were read as abstracts only. PMID:11282024 states ALK-2 preference as background; its own data concern downstream Smad specificity [PMID:11282024]. PMID:32897189 concerns a mutant receptor, not wild-type binding. No affinity value reported.","key_references":[{"PMID":"8006002","why":"Direct binding of OP-1/BMP-7 to ALK-2"},{"PMID":"9748228","why":"ALK2 is the major BMP7 type I receptor; distinct from activin's ALK4"},{"PMID":"32897189","why":"FOP-mutant ACVR1 responds to Bmp7 in zebrafish"}],"covers":["LR000139","LR003688"]},"LR008458":{"pair":"CALCB -> RAMP2","headline":"Weak support for beta-CGRP at RAMP2; the one confirmed paper focuses on RAMP3 and does not establish a RAMP2 role.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists full agonist records for CALCB-RAMP2 [DB:GtoPdb]. The one confirmed paper compared CALCB, ADM and ADM2 in rat mesenteric artery smooth muscle cells; all induced cAMP, but the RAMP2 assignment is not established [PMID:26423127].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 7.3 to 7.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat mesenteric artery smooth muscle cells with RAMP knockdown [PMID:26423127]; the curator table says human.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"The paper was read as abstract only and its focus is RAMP3-mediated ADM action. Evidence for RAMP2 specifically is thin.","key_references":[{"PMID":"26423127","why":"CALCB, ADM, ADM2 cAMP responses with RAMP knockdown"}],"covers":["LR008458"]},"LR008467":{"pair":"CALM2 -> PDE1A","headline":"CALM2 activates PDE1A according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM2 as an activator of PDE1A (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008467"]},"LR003769":{"pair":"CCL5 -> CCR5","headline":"Very well supported: CCL5 (RANTES) is a high-affinity CCR5 ligand and agonist, with binding, mutagenesis, structure and database support.","interaction_type":"direct binding","direction_and_effect":"Cells expressing CCR5 bind RANTES with high affinity and generate inositol phosphates [PMID:8663314]. RANTES, MIP-1 alpha and vMIP-II bound CCR5 at high affinity with partial cross-competition [PMID:11700073]. MCP-2 cross-competed with RANTES and showed cross-desensitization in Ca2+ flux [PMID:9790730]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RANTES Phe12 and Ile15 and P2 are needed for CCR5 binding, and Y3 and D6 for activation [PMID:9289016]. Acidic residues in the CCR5 distal N-terminus and ECL2 are needed for binding [PMID:11700073]. Glycosaminoglycan-bearing syndecan-1/-4 and CD44 co-precipitate with RANTES, and glycosaminidase treatment reduces CCR5 binding [PMID:14637022]. Structures with CCL5 and CCR5 chains exist [DB:PDB 5UIW, DB:PDB 6FGP, DB:PDB 7F1R, DB:PDB 7O7F].","affinity_potency":[{"value":"pKi 9.2 to 9.7","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptors and ligands in transfected cells and macrophages [PMID:8663314, PMID:14637022]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag]. RANTES attaches to cell-surface proteoglycans [PMID:14637022].","caveats":"Papers were read as abstracts only. No direct RANTES Kd or IC50 appears in our evidence. IntAct NMR and BioGRID records also exist [DB:IntAct, DB:BioGRID]. PMID:10318947 and PMID:10477718 are mainly about TAK-779 and other chemokines.","key_references":[{"PMID":"8663314","why":"CCR5 cloning; RANTES high-affinity binding and signalling"},{"PMID":"11700073","why":"RANTES binding and CCR5 residues required"},{"PMID":"9289016","why":"RANTES residues for CCR5 binding and activation"}],"covers":["LR000259","LR003769"]},"LR003778":{"pair":"CCL7 -> CCR2","headline":"MCP-3 (CCL7) binds human CCR2B with Ki 7 nM and is a CCR2 agonist; supported by binding, a chemotaxis comparator and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"125I-MCP-3 bound CC CKR2B (Ki 7 nM); MCP-1 and MCP-3 were equipotent agonists, EC50 10 nM for [Ca2+]i changes [PMID:8530354]. CCL7 also acted as a CCR2 chemoattractant comparator in L1.2-CCR2 cells [PMID:12554737]. GtoPdb: full agonist, pIC50 8.4 to 8.7 [DB:GtoPdb].","molecular_requirements":"CCR2B binding was competed only by MCP-3 and MCP-1 among CC chemokines tested [PMID:8530354]. No co-receptor needs reported.","affinity_potency":[{"value":"Ki 7 nM","assay":"125I-MCP-3 direct binding","system":"CC CKR2B transfectants (human)","cite":"PMID:8530354"},{"value":"EC50 10 nM","assay":"[Ca2+]i change","system":"CCR2B-transfected cells (human)","cite":"PMID:8530354"},{"value":"pIC50 8.4 to 8.7","assay":"GtoPdb binding range","system":"human CCR2","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in transfected cells [PMID:8530354][PMID:12554737]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR2 flagged transmembrane receptor [flag].","caveats":"Both papers read as abstract only. The second paper only uses CCL7 as a benchmark, with no CCL7 affinity. The EC50 10 nM is stated jointly for MCP-1 and MCP-3.","key_references":[{"PMID":"8530354","why":"Direct MCP-3 binding to CCR2B, Ki 7 nM, agonism"},{"PMID":"12554737","why":"CCL7 as comparator CCR2 chemoattractant"}],"covers":["LR000268","LR003778"]},"LR003787":{"pair":"CCL8 -> CCR5","headline":"CCL8 (MCP-2) binds CCR5 with high affinity and acts as an agonist; three independent binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"MCP-2 competed for [125I]-MIP-1beta binding on CCR5-expressing cells (IC50 0.22 nmol/L, the most potent of the CC chemokines tested) [PMID:10477718]. It competitively inhibited MIP-1beta binding, induced chemotaxis with potency comparable to MIP-1beta and caused dose-dependent CCR5 internalization [PMID:9468473]. It is a true agonist, cross-desensitizing with RANTES in Ca2+ flux [PMID:9790730]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR5 alone in transfectants was sufficient; on CD3-activated T cells most MCP-2 responses were blocked by anti-CCR5 mAb 2D7 [PMID:9790730]. MCP-2 also blocked HIV-1 entry in CCR5/CD4-expressing cells [PMID:9468473].","affinity_potency":[{"value":"IC50 0.22 nmol/L","assay":"[125I]-MIP-1beta competition binding","system":"stable CCR5-expressing cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and human CCR5 in HEK293 or other stable cell lines, monocytes and activated T cells [PMID:9468473][PMID:9790730]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag].","caveats":"All three papers were read as abstracts only. MCP-2 also binds CCR1 and CCR2b [PMID:9790730], so CCR5 is one of several receptors. Other numbers on the dossier curator rows are estimates not stated in the abstract and are not reported here.","key_references":[{"PMID":"10477718","why":"Competition binding IC50 for MCP-2 at CCR5"},{"PMID":"9468473","why":"MCP-2 binds, signals and internalizes CCR5; inhibits HIV-1"},{"PMID":"9790730","why":"MCP-2 is a true CCR5 agonist, main receptor on activated T cells"}],"covers":["LR000277","LR003787"]},"LR005569":{"pair":"CCN1 -> LRP1","headline":"CCN1 co-immunoprecipitates with LRP1 in human fibroblasts and LRP1 is needed for CCN1-driven ROS and apoptosis with TNFalpha; one paper.","interaction_type":"direct binding","direction_and_effect":"CCN1 interacts with LRP1 in a protein complex, and binding to LRP1 is critical for CCN1-induced ROS generation and apoptotic synergism with TNFalpha [PMID:22363611]. Anti-CCN1 antibodies pulled down the 515 kDa LRP1 subunit from primary human skin fibroblasts, and receptor-associated protein (RAP) abolished this co-immunoprecipitation [PMID:22363611].","molecular_requirements":"LRP1 acts alongside integrins alpha(v)beta(5), alpha(6)beta(1) and syndecan 4 as part of a multi-receptor setup [PMID:22363611]. The 515 kDa LRP1 chain was the one detected.","affinity_potency":[],"species_and_systems":"Primary human skin fibroblasts, human CCN1; siRNA knockdown of LRP1. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Co-immunoprecipitation shows a complex, which may be indirect, no purified-protein binding or affinity is reported. Single paper; full text excerpts used.","key_references":[{"PMID":"22363611","why":"CCN1-LRP1 co-IP and LRP1 requirement for ROS and apoptosis"}],"covers":["LR002268","LR005569"]},"LR001699":{"pair":"CCN2 -> IGF2R","headline":"CCN2 binds M6P/IGF2R with high affinity in corneal fibroblasts and IGF2R is needed for CTGF-driven proliferation; abstract-level.","interaction_type":"direct binding","direction_and_effect":"CTGF binds the M6P/IGF-2-R, and knockout fibroblasts did not proliferate at all in response to CTGF, indicating an agonist-type signalling receptor role [PMID:22511630].","molecular_requirements":"A 280 kDa cross-linked 125I-CTGF complex was immunoprecipitated by antibodies to CTGF or to M6P/IGF-2-R [PMID:22511630]. Radiolabeled CTGF binding was displaced by CTGF but not related growth factors [PMID:22511630].","affinity_potency":[],"species_and_systems":"Radiolabeled recombinant human CTGF on human corneal fibroblasts; M6P/IGF-2-R knockout fibroblasts (species not specified in the abstract) [PMID:22511630]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Scatchard analysis showed high- and low-affinity sites, with best-fit favouring a single high-affinity site; no Kd value is given in our evidence [PMID:22511630]. IGF2R is also a clearance receptor, so binding may not imply classical signalling; the authors report proliferation dependence.","key_references":[{"PMID":"22511630","why":"Binding and knockout functional dependence of CTGF on M6P/IGF2R"}],"covers":["LR001699","LR005068"]},"LR006757":{"pair":"Cd200 -> Cd200r4","headline":"Binding to Cd200r4 by FACS; the second paper concerns the related CD200RLa and reports very weak affinity.","interaction_type":"direct binding","direction_and_effect":"FITC-labelled CD200Fc bound COS7 cells transfected with each CD200R isoform [PMID:15187158]. mAbs against CD200 R1/R4 altered IL-2/IL-4 production and suppressed CTL responses comparably to CD200Fc [PMID:15187158].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd >500 microM","assay":"SPR-type bead assay, monomeric proteins, mouse CD200 with CD200RLa (named CD200R4 in the text)","system":"recombinant proteins, 37 C","cite":"PMID:19283782"}],"species_and_systems":"Mouse pair; COS7 transfectants [PMID:15187158]; recombinant mouse proteins [PMID:19283782].","localisation_and_range":"Cd200r4 carries no secreted or transmembrane flag [flag]; otherwise not reported in our evidence.","caveats":"Affinity is extremely weak (Kd >500 microM) and equated by the paper to CD200RLa, so the relation of CD200RLa to Cd200r4 rests on the paper's own naming; both papers abstract-level reads. The 19283782 passage also says dimeric CD200-Fc failed to detect CD200RLa on cells, which sits uneasily with the FACS result for R4 [PMID:19283782].","key_references":[{"PMID":"15187158","why":"FACS binding of CD200Fc to all CD200R isoforms"},{"PMID":"19283782","why":"Very weak CD200-CD200RLa (CD200R4) affinity"}],"covers":["LR006757"]},"LR007954":{"pair":"CD40LG -> ITGA2B:ITGB3","headline":"Soluble CD40L binds the alphaIIbbeta3 complex; supported by two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"rsCD40L bound purified alphaIIbbeta3 and activated platelets, induced platelet spreading and promoted aggregation under high shear [PMID:11875495]. CD154 affinity for alphaIIbbeta3 is about 4-fold higher than for alpha5beta1 [PMID:22461623].","molecular_requirements":"The KGD integrin-recognition sequence is required; rsCD40L lacking it did not restore thrombosis in vivo [PMID:11875495]. CD154 residues for alphaIIbbeta3 binding differ from those for alpha5beta1 [PMID:22461623].","affinity_potency":[],"species_and_systems":"Purified integrin, human and mouse platelets, in vivo mouse thrombosis [PMID:11875495]; U937 cells [PMID:22461623]. Human pair only.","localisation_and_range":"CD40LG flagged secreted [flag]; soluble ligand acting on platelets.","caveats":"Abstracts only; no Kd reported. UniProt records ITGAV:ITGB3 (not alphaIIbbeta3) as a CD40LG receptor [DB:UniProt].","key_references":[{"PMID":"11875495","why":"rsCD40L binds alphaIIbbeta3, KGD-dependent"},{"PMID":"22461623","why":"Relative affinity of CD154 for alphaIIbbeta3"}],"covers":["LR007954"]},"LR005587":{"pair":"CD40LG -> ITGA4","headline":"Soluble CD40L activates alpha4beta1 integrin in cell-free and cell-surface assays; one paper, alpha4 chain-level evidence only.","interaction_type":"direct binding","direction_and_effect":"Soluble CD40L bound and activated soluble and cell-surface alphavbeta3, alpha5beta1 and alpha4beta1; soluble CD40L activated soluble integrins in cell-free conditions, so inside-out signalling is not required [PMID:33571526].","molecular_requirements":"Evidence is for the alpha4beta1 heterodimer, not ITGA4 alone; the paper tests an allosteric site 2 beyond the classical trimeric-interface site [PMID:33571526].","affinity_potency":[],"species_and_systems":"Soluble integrins and CHO cells (full text read) [PMID:33571526]; species of cells not detailed in our excerpts; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; the paper notes sCD40L is released by proteolytic cleavage, allowing action at distant sites [PMID:33571526].","caveats":"Single paper; no affinity reported; chain-only attribution (ITGB1 partner not in this pair).","key_references":[{"PMID":"33571526","why":"CD40L activates alpha4beta1 and other integrins"}],"covers":["LR002288","LR005587"]},"LR003796":{"pair":"CD40LG -> ITGB2","headline":"CD40L binding to the beta2 integrin Mac-1 rests on one abstract-level binding paper; ITGB2 is a chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"Flow cytometry, radioactive binding assays and immunoprecipitation showed CD40L interacting with Mac-1, with Mac-1-dependent adhesion, migration and myeloperoxidase release in vitro; CD40-deficient mice were not protected from atherosclerosis, and Mac-1 inhibition reduced lesions [PMID:17372166].","molecular_requirements":"The evidence is for the Mac-1 (alphaM:beta2) heterodimer, not ITGB2 alone [PMID:17372166].","affinity_potency":[],"species_and_systems":"Curators record human for both partners; the abstract also uses mouse models [PMID:17372166]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag].","caveats":"One abstract-only paper shown; a second confirmed paper is not displayed, two abstracts were insufficient and one is pending. No affinity reported.","key_references":[{"PMID":"17372166","why":"CD40L-Mac-1 binding and CD40-independent inflammation"}],"covers":["LR000286","LR003796"]},"LR005596":{"pair":"CD72 -> CD6","headline":"Soluble CD72 was reported to bind CD6 on activated human CD4+ T cells in a single 2024 study; no other evidence is in our dossier.","interaction_type":"direct binding","direction_and_effect":"Soluble CD72 (sCD72) pulled down CD6 from activated CD4+ T cells by mass spectrometry and co-immunoprecipitation, and the authors describe it as a possible ligand-receptor interaction [PMID:39026665]. sCD72 raised IL-17A and IFN-gamma in activated CD4+ T cells and increased their proliferation, possibly through SLP-76-AKT-mTOR signalling [PMID:39026665]. This is a stimulatory effect on the T cell.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD4+ T cells, with a recombinant sCD72 made of amino acids 117 to 359 secreted by HEK-293T cells [PMID:39026665].","localisation_and_range":"The soluble extracellular form acts [PMID:39026665]; the full-length CD72 flag says transmembrane and CD6 flag says secreted and transmembrane [flag].","caveats":"Single paper; the curator read the abstract but full text is listed as available. The authors call CD6 a potential receptor and the interaction possible. The pull-down used a cross-linker, so direct contact is not shown separately. No database records and no affinity in our evidence. The mouse pair is ortholog-inferred.","key_references":[{"PMID":"39026665","why":"Identifies and validates the sCD72-CD6 interaction and its T-cell effects"}],"covers":["LR002297","LR005596"]},"LR006838":{"pair":"CDH1 -> ITGAE:ITGB7","headline":"E-cadherin binds the alphaE:beta7 complex directly; one paper, abstract only, plus databases.","interaction_type":"direct binding","direction_and_effect":"E-cadherin-Fc binds recombinant alphaEbeta7 and alphaEbeta7 from IELs; the paper calls E-cadherin a direct counter-receptor [PMID:9425167]. UniProt describes ITGAE/ITGB7 as a receptor for E-cadherin [DB:UniProt].","molecular_requirements":"Complex alphaE:beta7 as entered; binding is selective over P-cadherin [PMID:9425167].","affinity_potency":[],"species_and_systems":"Human proteins and IELs [PMID:9425167]; BioGRID co-purification [DB:BioGRID]; Reactome complex [DB:Reactome].","localisation_and_range":"Membrane-bound; adhesion.","caveats":"Abstract only; classed Adhesion-Adhesion.","key_references":[{"PMID":"9425167","why":"Direct E-cadherin-alphaEbeta7 binding"}],"covers":["LR006838"]},"LR011698":{"pair":"CGA:CGB1 -> LHCGR","headline":"Heterodimer CGB1 with CGA on LHCGR is supported only by database records, mostly for CGA; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-LHCGR as a full agonist; pKd range 9.899999618530273 to 11.800000190734863 [DB:GtoPdb]. Reactome records LH receptor:LH complexes [DB:Reactome]. Cryo-EM structures of chorionic gonadotropin-LHCGR-Gs exist [DB:PDB 7FIG] [DB:PDB 7FII].","molecular_requirements":"Ligand is a CGA:CGB1 heterodimer; the records name CGA and LH or CG, not this specific beta gene; no CGB1 record shown.","affinity_potency":[],"species_and_systems":"Human; species of experiments not reported in our evidence.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Two pending rows, no curated paper. Database records are not specific to CGB1. BioGRID lists LHCGR-CGA affinity capture-western [DB:BioGRID].","key_references":[],"covers":["LR011698"]},"LR009367":{"pair":"CNTNAP1 -> RTN4","headline":"Nogo-A is reported to interact in trans with axonal Caspr, with a specificity control; abstract-level paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"Nogo-A, an oligodendroglial protein, interacts in trans with axonal Caspr at paranodes [PMID:14592966]. CHO cells expressing Caspr plus F3 bound Nogo-66 peptide and GST-Nogo-66 substrates, but cells expressing F3 alone did not [PMID:14592966].","molecular_requirements":"Caspr plus F3 was required in the assay; binding persisted after PI-PLC removal of GPI-linked F3, which the authors take to suggest direct Nogo-66-Caspr binding [PMID:14592966].","affinity_potency":[],"species_and_systems":"Rat (curator label); CHO cell binding, co-immunoprecipitation and rat and mouse pathology models [PMID:14592966].","localisation_and_range":"CNTNAP1 is annotated non-secreted; the paper describes a trans interaction across the paranodal junction [flag][PMID:14592966].","caveats":"Abstract-only; the abstract's wording is that binding 'suggests' a direct interaction. The pair is stored reversed relative to the biological direction, and no interaction class is assigned. BioGRID lists affinity-capture Western records for the same paper [DB:BioGRID][PMID:14592966].","key_references":[{"PMID":"14592966","why":"Nogo-A and Caspr-F3 interaction at paranodes"}],"covers":["LR009367"]},"LR005659":{"pair":"COL13A1 -> ITGB1","headline":"ITGB1 support comes via the a11b1 heterodimer; the b1 chain alone was not tested.","interaction_type":"direct binding","direction_and_effect":"Integrin a11b1 binds collagen XIII (SPR, pull-down, cell adhesion) [PMID:33306155].","molecular_requirements":"ITGB1 acts as the partner of a11; the a11-I domain recognises the motifs, and b1-only binding is not reported in our evidence [PMID:33306155].","affinity_potency":[],"species_and_systems":"C2C12 cells expressing human a11b1; mouse genetic crosses. The mouse pair is ortholog-inferred [PMID:33306155].","localisation_and_range":"COL13A1 is annotated non-secreted and transmembrane [flag].","caveats":"Chain-level assignment: the evidence concerns the a11b1 heterodimer, not ITGB1 alone [PMID:33306155].","key_references":[{"PMID":"33306155","why":"a11b1 as collagen XIII receptor"}],"covers":["LR002380","LR005659"]},"LR006883":{"pair":"COL18A1 -> ITGA11:ITGB1","headline":"Database-asserted only: BioGRID and IntAct record COL18A1-ITGB1 binding; no curator-confirmed paper for this specific integrin.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Databases record binding to ITGB1 only, not to the specific alpha chain, so the alpha subunit requirement is unresolved [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct lists a pull down [DB:IntAct, PMID:17615292]. Species not reported in our evidence.","localisation_and_range":"Ligand flagged as secreted; receptor is a transmembrane complex [flag].","caveats":"No papers were judged confirmed: curator read counts are review_only and different_entity only. The pair rests on database records alone, and these name ITGB1 and not the alpha chain.","key_references":[],"covers":["LR006883"]},"LR005668":{"pair":"COL2A1 -> DDR2","headline":"Collagen II directly binds and activates DDR2 via the discoidin domain, shown in two independent biochemical papers; mouse pair is projected.","interaction_type":"direct binding","direction_and_effect":"Collagen II is a much better ligand for DDR2 than for DDR1 and strongly stimulated DDR2 autophosphorylation, requiring triple-helical collagen [PMID:15544808]. Effect: agonist (receptor activation).","molecular_requirements":"Binding is mediated by the DDR2 discoidin domain and needs triple-helical collagen; the D2 period of collagen II is essential, D3 and D4 dispensable [PMID:15544808]. An NMR/transferred cross-saturation study mapped the collagen-binding site on the DDR2 discoidin domain [PMID:17703188].","affinity_potency":[],"species_and_systems":"Human DDRs, recombinant collagen II variants [PMID:15544808]; mouse pair is ortholog-inferred from human evidence.","localisation_and_range":"COL2A1 is flagged secreted, DDR2 is a cell-surface receptor kinase; contact with matrix collagen (inferred from flags and abstracts).","caveats":"Abstract read only for both. A third paper, PMID:9659900, was judged pair_absent: it never tested collagen II against DDRs (full text), so it is a missing test rather than a negative result. The SPR sentence from PMID:17703188 was a browser read still awaiting spot-check.","key_references":[{"PMID":"15544808","why":"Collagen II D2 period binds and activates DDR2"},{"PMID":"17703188","why":"DDR2 discoidin domain structure and collagen-binding site"}],"covers":["LR002389","LR005668"]},"LR005686":{"pair":"COL4A3 -> ITGB3","headline":"COL4A3 NC1 binds alphaVbeta3 in two abstract-only papers; ITGB3 is the beta chain of that integrin.","interaction_type":"direct binding","direction_and_effect":"alpha3NC1 is bound by alpha(v)beta(3) and alpha(v)beta(5), predominantly via the RGD site [PMID:14610079]; alpha(v)beta(3) was identified as a receptor for the alpha3(IV) chain on tumour cells [PMID:10493512]. UniProt lists an ITGB3 interaction [DB:UniProt].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer [PMID:10493512]; the domain tested is NC1 or a peptide [PMID:14610079].","affinity_potency":[],"species_and_systems":"Recombinant human domain in HEK293 [PMID:14610079]; tumour cells, species unspecified [PMID:10493512].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Both abstract only; non-RGD peptides about 10-fold less potent than native protein [PMID:14610079]. One other paper abstract_insufficient.","key_references":[{"PMID":"14610079","why":"RGD site of alpha3NC1 binds alphaVbeta3"},{"PMID":"10493512","why":"alpha(v)beta(3) and CD47 as alpha3(IV) receptors"}],"covers":["LR002407","LR005686"]},"LR003868":{"pair":"COL8A1 -> ITGA1","headline":"Antibody-blocking evidence that alpha1 integrin contributes to smooth muscle cell attachment to type VIII collagen; functional only.","interaction_type":"functional only","direction_and_effect":"Antibodies against alpha1 or alpha2 integrins reduced attachment of SMCs to type VIII collagen by 29% and 77%, respectively; anti-beta1 antibodies prevented attachment and migration [PMID:10666376]. Type VIII collagen signaled through integrins to stimulate MMP production [PMID:10666376].","molecular_requirements":"Beta1 integrin is implicated by antibody blocking; alpha1 and alpha2 were tested together as a pair of antibodies, so the effect of this chain alone is not separable in the evidence [PMID:10666376].","affinity_potency":[{"value":"29% and 77%","assay":"reduction of SMC attachment to type VIII collagen by anti-alpha1 or anti-alpha2 integrin antibodies, respectively","system":"smooth muscle cells","cite":"PMID:10666376"}],"species_and_systems":"Experiments used smooth muscle cells, with neointimal SMCs grown from rat [PMID:10666376]; the human and mouse pairs are ortholog-inferred from this evidence.","localisation_and_range":"Ligand flagged secreted [flag]; the paper describes matrix-deposited type VIII collagen [PMID:10666376].","caveats":"Abstract only; antibody blocking is indirect and does not show direct binding. A second confirmed paper exists but is not shown; one review-only and one abstract-insufficient row.","key_references":[{"PMID":"10666376","why":"Antibody blocking implicates alpha1/alpha2/beta1 integrins in SMC attachment to type VIII collagen"}],"covers":["LR000362","LR003868"]},"LR003877":{"pair":"CORT -> SSTR5","headline":"Cortistatin binds SSTR5 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.33","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst5 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.5-10.2","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR5 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID]; a PDB structure 8X8L has chains for both proteins [DB:PDB 8X8L].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000371","LR003877"]},"LR008953":{"pair":"CSF2 -> IL3RA","headline":"No verified evidence for a direct GM-CSF to IL3RA interaction; only structure/pathway records of the betac chain.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; no curated paper supports GM-CSF acting through IL3RA.","molecular_requirements":"IntAct and PDB 4NKQ record a GM-CSF chain with a P32927 chain (the shared beta chain, not IL3RA, per accession) [DB:IntAct] [DB:PDB 4NKQ].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged row is outcome different_entity, meaning the evidence concerned another entity. Database records point to the common beta chain rather than IL3RA, so this pair looks like a mapping artefact.","key_references":[],"covers":["LR008953"]},"LR006793":{"pair":"CSF3 -> CSF1R","headline":"No evidence that G-CSF acts on CSF1R; two verified negatives and only a GtoPdb entry without type or action.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. Two papers were judged pair_absent [PMID:42425206] [PMID:41492941].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; the two absent-pair papers were a tumour neutrophil study and a sickle cell transfusion study [PMID:42425206] [PMID:41492941].","localisation_and_range":"Not reported in our evidence.","caveats":"The only database record is GtoPdb CSF3-CSF1R with Type=None and Action=None [DB:GtoPdb]. Two further rows were different_entity and one abstract_insufficient. Treat as unsupported.","key_references":[],"covers":["LR006793"]},"LR003886":{"pair":"CTF1 -> IL6ST","headline":"CTF1 signals through gp130 (IL6ST) with LIFR; support is functional blockade in canine cells plus database records.","interaction_type":"functional only","direction_and_effect":"Exogenous CT-1 stimulated thymidine and proline incorporation in cardiac fibroblasts; blockade of gp130 or LIF receptor inhibited CT-1-stimulated growth, so CT-1 is an agonist [PMID:11834704]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"The receptor is the gp130/LIFR complex; gp130 alone is not shown sufficient in our evidence [PMID:11834704]. Reactome lists an OSM, LIF, CTF1 receptor complex binding gp130 [DB:Reactome R-HSA-6783524].","affinity_potency":[],"species_and_systems":"Cultured adult canine cardiac fibroblasts, not human or mouse; the human and mouse pairs are ortholog-inferred [PMID:11834704].","localisation_and_range":"CTF1 flagged secreted; IL6ST flagged transmembrane [flag]; secreted cytokine acting on cell-surface receptor.","caveats":"Evidence is receptor blockade, not binding; abstract only; the receptor identity is background in the study. IL6ST alone inherits complex-level evidence.","key_references":[{"PMID":"11834704","why":"CT-1 growth effect blocked by gp130 or LIFR blockade in canine fibroblasts"}],"covers":["LR000380","LR003886"]},"LR003895":{"pair":"CTHRC1 -> FZD5","headline":"CTHRC1 co-precipitates with Fzd5 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 and Wnt3a co-precipitated with Fzd5, and Cthrc1 enhanced Wnt3a-Fzd5 binding; Cthrc1 also co-precipitated with Fzd3 and Fzd6 and no binding to Smo [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000389","LR003895"]},"LR005749":{"pair":"DAG1 -> NRXN1","headline":"Alpha-dystroglycan binds neurexin-1alpha directly with defined domains; binding requires LARGE glycans; one paper.","interaction_type":"direct binding","direction_and_effect":"alphaDAG binding at LNS2 prevents neuroligin binding at LNS6 (steric hindrance), and its binding is mutually exclusive with neurexophilin-1 [PMID:25157101].","molecular_requirements":"alphaDAG binds both LNS2 and LNS6 of Nrxn1alpha independent of splice inserts SS#2/SS#4, mostly via LARGE-dependent glycans on the mucin region; unglycosylated alphaDAG does not bind. Mutating the laminin-binding Thr-315/Thr-317 region did not reduce complex formation [PMID:25157101].","affinity_potency":[],"species_and_systems":"LARGE-modified recombinant alphaDAG pulled down alpha-neurexin from mouse brain lysate [PMID:25157101]. Curator record lists human; both human and mouse pairs are ortholog-projected.","localisation_and_range":"Neurexin-1 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag]. Trans-synaptic contact is implied by the paper's synapse context [PMID:25157101].","caveats":"Abstract plus excerpts only. Reactome lists a Dystroglycan:NRXN1 complex [DB:Reactome R-HSA-2426312]. Effect is blocking of neuroligin, not signalling.","key_references":[{"PMID":"25157101","why":"Domain mapping, LARGE glycan dependence, neuroligin exclusion"}],"covers":["LR002475","LR005749"]},"LR007918":{"pair":"DKK2 -> KREMEN2:LRP6","headline":"Functional evidence that Kremen2 with LRP6 converts Dkk2 into an inhibitor; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Dkk2 activates LRP6 signalling in human 293 fibroblasts; co-transfection of krm2 blocks this and enhances inhibition of Wnt/Frizzled signaling [PMID:12527209].","molecular_requirements":"Both Kremen2 and LRP6 are involved in the readout; Krm2 binds the second cysteine-rich domain of Dkks [PMID:12527209]. IntAct holds a bio-layer interferometry record for DKK2-Krm2 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts and Xenopus embryos [PMID:12527209].","localisation_and_range":"DKK2 flagged secreted; the complex flagged transmembrane [flag].","caveats":"Abstract only; no direct evidence of a ternary DKK2-KREMEN2-LRP6 complex is stated.","key_references":[{"PMID":"12527209","why":"Krm2 switches Dkk2 from LRP6 activator to inhibitor"}],"covers":["LR007918"]},"LR005758":{"pair":"DKK3 -> KREMEN2","headline":"DKK3 interacts with Krm2 in one 2010 paper using biochemical and functional assays; single-paper support.","interaction_type":"direct binding","direction_and_effect":"Dkk3 interacts with Krm1 and Krm2, contrary to earlier studies; Krm2 abolished Dkk3-mediated potentiation of Wnt signalling [PMID:20370576]. Curator direction is agonist for the Dkk3 pro-Wnt effect.","molecular_requirements":"Dkk3 did not interact with, or alter expression of, LRP6, so LRP6 is not needed for this binding; blocking glycosylation did not change the Dkk3-Krm interaction [PMID:20370576].","affinity_potency":[],"species_and_systems":"Human proteins per the curator record; the mouse pair is listed and the human pair is ortholog-inferred [PMID:20370576]. Specific cell system not recorded.","localisation_and_range":"Membrane-bound Kremen receptor; DKK3 flagged secreted [flag]. Range not otherwise reported.","caveats":"One paper only, no database record. Affinity not reported in our evidence. Earlier studies reported no such interaction, per this paper [PMID:20370576].","key_references":[{"PMID":"20370576","why":"Dkk3 interacts with Krm1 and Krm2, not LRP6"}],"covers":["LR002490","LR005758"]},"LR001789":{"pair":"DSC2 -> DSG3","headline":"DSC2 -> DSG3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001789","LR005145"]},"LR009169":{"pair":"DSCAM -> DCC","headline":"No curated paper confirms it; support rests on Reactome and UniProt statements of a DSCAM:DCC interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; Reactome lists a DSCAM:DCC complex at the plasma membrane [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human records only [DB:Reactome]; no experimental system in our evidence.","localisation_and_range":"Reactome places the complex at the plasma membrane [DB:Reactome]; flags mark both as transmembrane receptors [flag].","caveats":"One paper was judged and found insufficient from its abstract, so no curator-verified evidence exists. UniProt notes DCC interaction for DSCAM and 'by similarity' for the reciprocal entry [DB:UniProt].","key_references":[],"covers":["LR009169"]},"LR008386":{"pair":"DSCAML1 -> PTPRM","headline":"DSCAML1 binds PTPRM by SPR in a high-throughput human IgSF interactome study; single paper.","interaction_type":"direct binding","direction_and_effect":"The study reports binding of DSCAM-CT and DSCAML1-CT to PTPRT and PTPRM by SPR [PMID:32822567]. Signalling direction or effect is not reported in our evidence.","molecular_requirements":"Only the C-terminal ectodomain region (DSCAML1-CT) was tested as analyte against PTPRs as ligands; subunit or co-receptor requirements not reported in our evidence [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins; SPR at 2-fold dilutions from 16 to 2,048 nM, following an ELISA-based pooled screen [PMID:32822567].","localisation_and_range":"Not reported by the paper beyond ectodomain-level binding. Entity flags mark the receptor as a receptor [flag]; no flags for the ligand.","caveats":"Sensorgram binding only; no Kd is given in our excerpts. Pairs from the same SPR panel (e.g. PTPRK) were untested for lack of protein. The sentence covers both DSCAM and DSCAML1 and both PTPRT and PTPRM, so this row inherits a shared statement [PMID:32822567].","key_references":[{"PMID":"32822567","why":"Human IgSF cell-surface interactome with SPR validation of DSCAM/DSCAML1 with PTPRT/PTPRM"}],"covers":["LR008386"]},"LR005767":{"pair":"Dsg1a -> Dsc1","headline":"Dsg1a -> Dsc1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"Heterophilic trans binding between the two desmosomal cadherins: every Dsg passed over a Dsc surface, or vice versa, gave binding responses described as strong heterophilic interaction [PMID:27298358]. No directionality beyond the curator's agonist-style label is reported; the pair is best read as symmetric adhesion between cadherins on adjacent cells.","molecular_requirements":"Ectodomain-only recombinant proteins were used for SPR and bead aggregation [PMID:27298358]; no further subunits or co-receptors reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), range over all pairwise human Dsg/Dsc ectodomain combinations, not specific to this pair","system":"recombinant human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: mouse (ortholog-projected). The mouse pair is projected from human evidence; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"The SPR quote was read via browser and is flagged by curators as unverifiable pending spot-check; our dossier gives only the pooled KD range, not a value for this pair. The paper's abstract was the only text in the dossier. Database records also exist (UniProt), which are not independent of the evidence above. [DB:UniProt] UniProt also lists a cytoplasmic-region interaction between these two proteins [DB:UniProt]; that is a different interface from the ectodomain binding above.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR005767"]},"LR001798":{"pair":"DSPP -> ITGB6","headline":"DSP domain of DSPP binds integrin beta6 in a protein-library screen with functional blockade; one paper.","interaction_type":"direct binding","direction_and_effect":"DSP (a DSPP-derived fragment) was identified as a ligand of integrin beta6 by bait screening; the 36-residue DSP aa183-219 fragment binds and activates ERK1/2 and P38, blocked by anti-integrin beta6 antibody and siRNA [PMID:27430624].","molecular_requirements":"The processed DSP domain, not full-length DSPP, acts, in an RGD-independent manner [PMID:27430624]. Partner alpha chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse dental mesenchymal cells (mDPC6T) per the full-text excerpts; the human pair is ortholog-inferred and the mouse pair is the direct one.","localisation_and_range":"DSPP is flagged as secreted [flag]; DSPP is processed to DSP, DGP and DPP [PMID:27430624].","caveats":"Binding rests on a library screen; no affinity reported in our evidence. Evidence from a single paper.","key_references":[{"PMID":"27430624","why":"DSP aa183-219 binds integrin beta6 and signals"}],"covers":["LR001798","LR005154"]},"LR003949":{"pair":"EDA -> EDAR","headline":"EDA (A1 isoform) binds and activates EDAR; binding and co-precipitation shown, abstracts only.","interaction_type":"direct binding","direction_and_effect":"EDA-A1 binds only EDAR [PMID:11039935]; EDAR co-precipitated ectodysplasin, confirming a ligand-receptor pair [PMID:11309369].","molecular_requirements":"Ligand must be furin-cleaved to release soluble ectodysplasin; EDA patient missense mutations affect the recognition sequence [PMID:11309369].","affinity_potency":[],"species_and_systems":"Human; mouse pair is ortholog-inferred.","localisation_and_range":"Released by proteolytic shedding as a soluble ligand [PMID:11309369]; adjacent expression in developing human skin.","caveats":"PMID:11039935 shows EDA-A1 binds only EDAR and EDA-A2 only XEDAR, so isoform matters. Abstracts only; affinity not reported in our evidence.","key_references":[{"PMID":"11309369","why":"EDAR co-precipitates ectodysplasin"},{"PMID":"11039935","why":"EDA-A1 binds only EDAR"}],"covers":["LR000458","LR003949"]},"LR005776":{"pair":"EDIL3 -> ITGB2","headline":"Del-1 antagonises LFA-1 (ITGB2 with ITGAL), and may bind Mac-1; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Del-1 acts as an LFA-1 antagonist; human Del-1 inhibited LFA-1-dependent transendothelial migration of human neutrophils, and Del-1-Fc was ineffective in Itgal-/- mice [PMID:22447028]. Recombinant EDIL3 inhibited osteoclastogenesis of mouse MDSCs via binding to Mac-1 but not LFA-1 [PMID:31110935].","molecular_requirements":"ITGB2 is shared by LFA-1 and Mac-1; the two papers implicate different alpha partners and give opposing LFA-1 results.","affinity_potency":[],"species_and_systems":"Human neutrophils, mouse periodontitis [PMID:22447028]; mouse MDSCs [PMID:31110935].","localisation_and_range":"Not reported in our evidence.","caveats":"The papers conflict on LFA-1: PMID:31110935 reports binding to Mac-1 but not LFA-1. No binding affinity reported. PMID:31110935 abstract only.","key_references":[{"PMID":"22447028","why":"Del-1 antagonises LFA-1 in neutrophils and periodontitis"},{"PMID":"31110935","why":"EDIL3 binds Mac-1 in MDSC osteoclastogenesis"}],"covers":["LR002508","LR005776"]},"LR009484":{"pair":"EDIL3 -> ITGB5","headline":"Only a database co-immunoprecipitation record supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"IntAct records an association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54721681].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; system not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No curator-verified paper; one review_only judgement. Support is a single database record.","key_references":[],"covers":["LR009484"]},"LR003958":{"pair":"EFNA1 -> EPHA1","headline":"Ephrin-A1 is the preferred ligand of EphA1 in binding and cell assays, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"Soluble recombinant and native mouse EphA1 show preferential binding to ephrin A1 [PMID:11519828]; ephrin-A1 stimulates T-lymphocyte migration with PI3K associating with EphA1 [PMID:17634955]; ephrin-A1 stimulation triggers EphA1 interaction with integrin-linked kinase, and EphA1 activation inhibits cell spreading and migration via RhoA-ROCK [PMID:19118217].","molecular_requirements":"Downstream ILK interaction uses the EphA1 C-terminal SAM domain and depends on ephrin-A1 stimulation but not EphA1 kinase activity [PMID:19118217].","affinity_potency":[],"species_and_systems":"Mouse EphA1 [PMID:11519828]; human cells [PMID:17634955][PMID:19118217]. Both human and mouse pairs listed non-inferred.","localisation_and_range":"EFNA1 and EPHA1 are annotated both receptor and transmembrane; EFNA1 also annotated secreted [flag], which conflicts with a membrane-bound juxtacrine ligand. Contact-dependent signalling is not stated in the papers shown.","caveats":"A mass-spectrometry pull-down with ephrin-A1 Fc yielded only 2 unique EphA1 spectra versus 423 for EphA2, so EphA1 capture was weak [PMID:22568954]. Another paper reads B61 binding affinity as decreasing across receptors; the EphA1 value is not in our excerpt [PMID:8755474]. Most papers read as abstracts only.","key_references":[{"PMID":"11519828","why":"mouse EphA1 binds ephrin A1"},{"PMID":"19118217","why":"ephrin-A1 stimulation of EphA1, ILK coupling"},{"PMID":"17634955","why":"ephrin-A1 migration signal in T cells"}],"covers":["LR000467","LR003958"]},"LR003976":{"pair":"EFNA3 -> EPHA3","headline":"Ephrin-A3 binds EphA3, among its best EphA partners; a cis-inhibitory mode is also described.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954]. Coexpressed (cis) ephrin-A3 inhibits EphA2 and EphA3 binding ephrins in trans and activation; an EphA3 mutation found in lung cancer enhances cis interaction with ephrin-A3 [PMID:24348920].","molecular_requirements":"Not reported beyond the pair itself.","affinity_potency":[],"species_and_systems":"ELISA, species unspecified [PMID:22568954]; human cancer cells [PMID:24348920]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag]; the cis mechanism is described as same-cell association [PMID:24348920].","caveats":"Evidence on effect conflicts in direction: trans binding versus cis inhibition of activation. The 22568954 result was a browser read with an unverifiable quote. A BioGRID reconstituted-complex record exists [DB:BioGRID].","key_references":[{"PMID":"22568954","why":"ELISA binding ranking"},{"PMID":"24348920","why":"Cis ephrin-A3 inhibits EphA3 trans-activation"}],"covers":["LR000485","LR003976"]},"LR003985":{"pair":"EFNA4 -> EPHA4","headline":"Ephrin-A4 binds EphA4 in rat striatum and by ELISA; IntAct has ELISA and SPR records.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 selectively bind EphA4 but not EphA7 in rat striatal tissue [PMID:10366629]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat postnatal striatum [PMID:10366629]; ELISA, species unspecified [PMID:22568954]. Human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA4 flagged membrane-bound [flag].","caveats":"10366629 was an abstract-only read; 22568954 a browser read with an unverifiable quote. IntAct lists ELISA and surface plasmon resonance records [DB:IntAct] (no values in our evidence).","key_references":[{"PMID":"10366629","why":"Ephrin-A4 binds EphA4 in rat striatum"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"}],"covers":["LR000494","LR003985"]},"LR003994":{"pair":"EFNA5 -> EPHA5","headline":"Ephrin-A5 is named as an EphA5 ligand in adult mouse hippocampus; weak paper support, database records add some.","interaction_type":"functional only","direction_and_effect":"EphA5 and ephrin-A ligands (2 and 5) are expressed in adult mouse hippocampus; receptor- and ligand-binding-site immunoadhesins were used to target EphA function [PMID:10531456]. UniProt says EFNA5-EPHA5 interaction mediates islet cell communication regulating glucose-stimulated insulin secretion [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult mouse hippocampus [PMID:10531456]; the human pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"The confirmed paper shows co-expression and immunoadhesin effects, not direct binding; abstract-only read. IntAct lists affinity chromatography and coimmunoprecipitation records [DB:IntAct].","key_references":[{"PMID":"10531456","why":"EphA5 and ephrin-A2/A5 in adult hippocampus with immunoadhesins"}],"covers":["LR000503","LR003994"]},"LR005794":{"pair":"EGFL7 -> ITGB3","headline":"Same evidence as the ITGAV row: T cells adhere to EGFL7 via alphavbeta3 integrin; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Human and mouse activated T cells adhere to EGFL7 through integrin alphavbeta3 [PMID:29483510]. EGFL7 knockout worsens EAE and recombinant EGFL7 improves it [PMID:29483510].","molecular_requirements":"ITGB3 acts as part of the alphaVbeta3 heterodimer; ITGAV is also needed [PMID:29483510].","affinity_potency":[],"species_and_systems":"Human and mouse T cells and EAE mice [PMID:29483510].","localisation_and_range":"EGFL7 is secreted by annotation [flag]; described as ECM-bound [PMID:29483510].","caveats":"One paper, abstract only; no direct binding or affinity data in our evidence.","key_references":[{"PMID":"29483510","why":"T cell adhesion to EGFL7 via alphavbeta3"}],"covers":["LR002526","LR005794"]},"LR005839":{"pair":"EPHA7 -> EFNA5","headline":"Binding by ELISA and mouse in vivo apoptosis data support EphA7/ephrin-A5 interaction; both papers confirmed from abstracts or a browser read.","interaction_type":"direct binding","direction_and_effect":"In mouse embryos, ephrin-A5-Fc expression correlated with apoptosis of EphA7-expressing cells, and ephrin-A5 null mutation gave the converse phenotype; the curator labels this agonist-like signalling [PMID:22976838]. Ephrin-A5 Fc bound with high apparent affinity to most EphA receptors in ELISA, but the quoted sentence does not single out EphA7 [PMID:22568954].","molecular_requirements":"The apoptosis phenotype was reported with cell-cell contact between EphA-expressing and ephrin-A-expressing cells [PMID:22976838]. Other subunit requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse embryos in vivo [PMID:22976838]. ELISA with Fc fusion proteins, species unspecified [PMID:22568954].","localisation_and_range":"Membrane-anchored; the abstract proposes signalling via cell-cell contact [PMID:22976838]. Annotation flags mark EPHA7 as secreted and transmembrane and EFNA5 as transmembrane [flag].","caveats":"Abstract-only reading of [PMID:22976838]; [PMID:22568954] quote was browser-read and is marked unverifiable pending spot-check. The EphA7 sentence in the mouse paper reflects a mixed Eph/ephrin-A context, including ephrin-A2 double-deficient embryos. Apparent KD values are in a figure not in our evidence. BioGRID [DB:BioGRID 280893] and IntAct comigration [DB:IntAct Q15375-P52803] records also exist.","key_references":[{"PMID":"22976838","why":"Mouse in vivo gain- and loss-of-function: ephrin-A5 induces apoptosis of EphA7-expressing cells."},{"PMID":"22568954","why":"ELISA binding of ephrin-A5 Fc to EphA receptors."}],"covers":["LR002571","LR005839"]},"LR005848":{"pair":"EPHB1 -> EFNB3","headline":"UniProt-only claim that EFNB3 is a cognate ligand for EPHB1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EPHB1 entry) states cognate/functional ephrin ligands include EFNB1, EFNB2 and EFNB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only one UniProt sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002580","LR005848"]},"LR005857":{"pair":"EPHB2 -> EPHB2","headline":"EphB2 self-association evidence is structural database records; the one paper concerns EphB2-ephrinB1 repulsion, not homotypic binding.","interaction_type":"conflicting","direction_and_effect":"In cell-culture and simulation work, EphB2-, kinase-inactive EphB2- and ephrinB1-expressing cells show strong heterotypic and weak homotypic repulsion [PMID:28747399]. This paper therefore reports weak homotypic EphB2-EphB2 repulsion rather than a ligand-receptor signal.","molecular_requirements":"N-cadherin suppresses homotypic repulsion and enables homotypic cohesion in this system [PMID:28747399]. Kinase activity was not required for segregation (kinase-inactive EphB2 also segregated) [PMID:28747399].","affinity_potency":[],"species_and_systems":"Cell culture assays plus computer simulations; the curator records human for both partners [PMID:28747399].","localisation_and_range":"Membrane-bound receptor on both sides [flag]; the paper describes contact-mediated repulsion between cells [PMID:28747399].","caveats":"Full text was available but the paper does not test a ligand-receptor role for EphB2 with itself. BioGRID lists a co-crystal structure [DB:BioGRID 301995, PMID 9933164] and a biochemical activity record [DB:BioGRID 677324], which show EphB2 self-association but not a ligand-receptor mechanism.","key_references":[{"PMID":"28747399","why":"Weak homotypic versus strong heterotypic repulsion in EphB2 and ephrinB1 cells."}],"covers":["LR002589","LR005857"]},"LR010969":{"pair":"EXOC3-AS1 -> TRAF2","headline":"No verified evidence; only two-hybrid database records for a non-coding RNA gene symbol with TRAF2.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; IntAct two-hybrid records only [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"Two review_only rows and no verified paper. The ligand is an antisense RNA gene symbol, so the records may reflect a naming overlap.","key_references":[],"covers":["LR010969"]},"LR005875":{"pair":"F8 -> ASGR1","headline":"Factor VIII binds the asialoglycoprotein receptor with Kd about 2 nM by SPR; the paper concerns the receptor, not ASGR1 specifically.","interaction_type":"direct binding","direction_and_effect":"Factor VIII bound ASGPR dose-dependently with high affinity; in mice, FVIII residence time was prolonged (abstract truncated) [PMID:15946216]. This is a clearance receptor interaction.","molecular_requirements":"Only the FVIII heavy chain showed high-affinity binding, driven by B-domain elements; binding needed calcium, was inhibited by D-galactose and lost after deglycosylation [PMID:15946216]. ASGPR is described as the ASGR1/ASGR2 heterodimer in curator notes, so ASGR2 may also be required.","affinity_potency":[{"value":"Kd approximately 2 nM","assay":"surface plasmon resonance","system":"FVIII with ASGPR (purified, abstract only)","cite":"PMID:15946216"}],"species_and_systems":"SPR with purified proteins plus mouse clearance experiments [PMID:15946216]; species of proteins not reported in our evidence.","localisation_and_range":"ASGR1 is annotated as secreted [flag], though the receptor is described as an endocytic lectin [PMID:15946216].","caveats":"Abstract-only. The paper tested ASGPR as a whole, not ASGR1 alone. Binding depends on glycosylation, so recombinant or deglycosylated FVIII may differ.","key_references":[{"PMID":"15946216","why":"SPR binding of FVIII to ASGPR, Kd about 2 nM"}],"covers":["LR002608","LR005875"]},"LR008980":{"pair":"FGA -> CDH5","headline":"No curated paper supports this pair; only a BioGRID reconstituted-complex record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"CDH5 is flagged receptor and transmembrane; FGA secreted [flag].","caveats":"The single judged row was marked different_entity, meaning that paper concerned another entity. BioGRID lists a Reconstituted Complex record [DB:BioGRID]. Nothing else supports this pair.","key_references":[],"covers":["LR008980"]},"LR007198":{"pair":"FGF1 -> ITGAV:ITGB3","headline":"Direct FGF1 binding to the integrin alphavbeta3 complex with Kd about 1 microm; supports full FGF signalling.","interaction_type":"direct binding","direction_and_effect":"FGF1 directly bound soluble and cell-surface alphavbeta3, blocked by mAb 7E3 and cyclic RGDfV [PMID:18441324]. The integrin-binding-defective R50E mutant retained heparin and FGFR binding but was defective in proliferation, migration and chemotaxis [PMID:18441324]. UniProt: binding is essential for FGF1 signaling [DB:UniProt].","molecular_requirements":"Receptor is the ITGAV:ITGB3 complex; the beta3 CYDMKTTC specificity loop is involved, and the FGF1 integrin site overlaps its heparin site but not its FGFR site [PMID:18441324]. A ternary complex with FGFR1 is recorded [DB:UniProt].","affinity_potency":[{"value":"KD about 1 microm","assay":"direct binding to soluble and cell-surface alphavbeta3","system":"human FGF1, human integrin","cite":"PMID:18441324"}],"species_and_systems":"Human FGF1 and integrin alphavbeta3, soluble and cell-surface, with proliferation and migration assays [PMID:18441324].","localisation_and_range":"FGF1 is flagged secreted; the complex is flagged transmembrane [flag].","caveats":"Abstract only; single primary paper. Weak binding to several beta1 integrins [PMID:18441324].","key_references":[{"PMID":"18441324","why":"FGF1 directly binds integrin alphavbeta3"}],"covers":["LR007198"]},"LR005893":{"pair":"FGF1 -> SDC2","headline":"FGF1 and SDC2 rest on one IntAct co-immunoprecipitation record; curated papers were insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"Only an IntAct record from an anti-tag coimmunoprecipitation is available [DB:IntAct]; the experimental species are not reported in our evidence. The mouse pair is projected from human.","localisation_and_range":"SDC2 is flagged as a transmembrane receptor and FGF1 as secreted [flag].","caveats":"No curator-verified paper: two papers were judged abstract-insufficient. Support is a database assertion only [DB:IntAct]. Syndecan is a heparan sulfate proteoglycan, but our evidence does not say whether binding is direct or through heparan sulfate.","key_references":[{"PMID":"28514442","why":"source publication of the IntAct record (not curator-verified)"}],"covers":["LR002627","LR005893"]},"LR005929":{"pair":"FN1 -> DPP4","headline":"Fibronectin binding sites for DPPIV were mapped to FNIII repeats 13-15 in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"DPPIV bound fibronectin type III repeats 13, 14 and 15 via the consensus motif T(I/L)TGLX(P/R)G(T/V)X, confirmed by motif swapping; peptides from FNIII14 blocked DPPIV/poly-FN adhesion and impeded pulmonary metastasis [PMID:12716896]. Adhesion-type interaction.","molecular_requirements":"Polymeric fibronectin on cell surfaces binds lung endothelial DPPIV [PMID:12716896].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; the metastasis experiment is in vivo, species not stated in our evidence; mouse pair is orthology-inferred [PMID:12716896].","localisation_and_range":"DPPIV flagged transmembrane, FN1 secreted [flag]; poly-FN decorates cell surfaces [PMID:12716896].","caveats":"One paper, abstract only; no affinity values.","key_references":[{"PMID":"12716896","why":"maps DPPIV binding motif in fibronectin type III repeats"}],"covers":["LR002663","LR005929"]},"LR005938":{"pair":"GDF1 -> ACVR2A","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ActRIIA (ACVR2A); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002673","LR005938"]},"LR005947":{"pair":"GDF15 -> RET","headline":"RET acts as coreceptor for GFRAL in GDF15 signalling; direct GDF15-RET binding is not shown.","interaction_type":"functional only","direction_and_effect":"GFRAL requires association with the coreceptor RET to elicit intracellular signalling in response to GDF15 [PMID:28846099].","molecular_requirements":"RET depends on GFRAL as the GDF15-binding chain [PMID:28846099]; UniProt describes a 2:2:2 GDF15, GFRAL and RET ternary complex [DB:UniProt]; PDB 6Q2J and IntAct electron microscopy list Q99988 with P07949 [DB:PDB 6Q2J][DB:IntAct].","affinity_potency":[],"species_and_systems":"Human reagents per curator; mouse pair ortholog-inferred. Abstract-level evidence [PMID:28846099].","localisation_and_range":"GDF15 flagged secreted [flag]; GFRAL expression limited to hindbrain neurons [PMID:28846099].","caveats":"RET is a coreceptor; use the GFRAL-RET complex in scoring rather than RET alone. Only one abstract-read paper. Affinity not reported.","key_references":[{"PMID":"28846099","why":"GFRAL requires RET for GDF15 signalling"}],"covers":["LR002682","LR005947"]},"LR008269":{"pair":"GDF3 -> ACVR1B:ACVR2A","headline":"Complex pair with no curator-verified paper; rests on GtoPdb and UniProt records for individual subunits.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as agonist of both subunits (ACVR1B and ACVR2A) as separate records [DB:GtoPdb]. UniProt says GDF3 acts through a receptor complex of ACVR1B and the co-receptor CRIPTO [DB:UniProt].","molecular_requirements":"UniProt names CRIPTO as a co-receptor, which is not part of this complex entry [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the database evidence is not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor complex is flagged transmembrane [flag].","caveats":"No papers; only review-level sources were judged. The type I plus type II pairing is not shown as a unit in our evidence.","key_references":[],"covers":["LR008269"]},"LR002689":{"pair":"GDF7 -> ACVR2B","headline":"GDF7 binds ACVR2B directly (KD 1.0 nM for rhBMP12); one paper plus a GtoPdb record.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ACVR2B with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. GtoPdb lists an agonist record [DB:GtoPdb]. Functional support specific to ACVR2B is not reported in our evidence.","molecular_requirements":"Type II receptor; a type I partner is not tested in this dossier's evidence. Not reported in our evidence.","affinity_potency":[{"value":"KD 1.0 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs ACVR2B ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells [PMID:21702718]. ACVR2B affinity was similar to type I receptor affinity [PMID:21702718]. rhBMP12 is mapped to GDF7 via alternate names. Only one paper in the dossier.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."}],"covers":["LR002689","LR005954"]},"LR008557":{"pair":"GNAS -> AVPR2","headline":"Database-asserted only: one BioGRID FRET record; curated papers were insufficient or about other entities.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a FRET assay [PMID:15782186]; species and cell system not reported in our evidence.","localisation_and_range":"AVPR2 is annotated as a transmembrane receptor [flag]; GNAS is intracellular, so contact is cytoplasmic.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Judged rows: 'different_entity' (4) and 'abstract_insufficient' (3).","key_references":[],"covers":["LR008557"]},"LR002698":{"pair":"GPC3 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC3 evidence is class-level.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Evidence is for 'glypican' as a class. GPC3 was among glypicans detected in the LRRTM4-Fc sample, but the abstract does not name it and direct cell-free binding was shown for GPC4 only [PMID:23911103]. GPC3 is annotated non-secreted [flag] while others are secreted: annotation inconsistent.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002698","LR005963"]},"LR005965":{"pair":"GPC4 -> PTPRS","headline":"Database-asserted only: BioGRID lists reconstituted complex, co-localisation and affinity-capture records from one paper; no curated paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID cites one study [PMID:25624497]; species and cells not reported in our evidence. Pair is ortholog-inferred for human and mouse.","localisation_and_range":"Both partners are annotated secreted and transmembrane-capable [flag].","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Two curated judgements were 'abstract_insufficient'. All four BioGRID records come from one paper.","key_references":[{"PMID":"25624497","why":"Source of the BioGRID records; not curated by us"}],"covers":["LR002700","LR005965"]},"LR007972":{"pair":"GPHA2:GPHB5 -> TSHR","headline":"Thyrostimulin (GPHA2:GPHB5 heterodimer) activates TSHR; supported by one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"The recombinant heterodimer activated human TSH receptors but not LH and FSH receptors, stimulated cAMP production and thymidine incorporation in cultured thyroid cells, and raised serum thyroxine in TSH-suppressed rats [PMID:12045258]. Agonist action.","molecular_requirements":"Both subunits are annotated as the ligand: the A2/B5 heterodimer is the active hormone. Heterodimerisation was shown by yeast two-hybrid and immunological analyses in transfected cells [PMID:12045258]. Whether either subunit alone acts on TSHR is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in transfected cells and cultured thyroid cells; in vivo effect in rats [PMID:12045258].","localisation_and_range":"Both subunits are flagged as secreted [flag]; the paper suggests a paracrine mechanism in anterior pituitary [PMID:12045258].","caveats":"One paper, read as abstract only. Receptor binding is described as 'high affinity' in a radioligand assay, but no number is given in our evidence. Reactome and UniProt records cite the same paper [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"12045258","why":"Identifies the A2/B5 heterodimer as a TSHR agonist, with binding and cAMP data"}],"covers":["LR007972"]},"LR005974":{"pair":"GREM1 -> FGFR1","headline":"Gremlin1 is reported as an FGFR1 ligand that activates MAPK signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Gremlin1 binds FGFR1 and activates downstream MAPK signalling; this promotes lineage plasticity and castration resistance in prostate cancer [PMID:35624341]. Agonist. An anti-Gremlin1 antibody acted synergistically with androgen deprivation therapy [PMID:35624341].","molecular_requirements":"Gremlin1 interacts with FGFR1 differently from the canonical ligand FGF1, according to docking and mutagenesis [PMID:35624341]. No co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human prostate cancer models; curators list human/human [PMID:35624341]. Mouse pair is ortholog-inferred.","localisation_and_range":"GREM1 is flagged as secreted; FGFR1 as transmembrane [flag].","caveats":"One paper, abstract only; binding method and affinity not described in our evidence. Gremlin1 is also a BMP antagonist, but BMP effects are not reported here.","key_references":[{"PMID":"35624341","why":"Identifies Gremlin1 as an FGFR1 ligand activating MAPK"}],"covers":["LR002709","LR005974"]},"LR005983":{"pair":"HMGB1 -> ITGAV","headline":"HMGB1 binds soluble integrin alphavbeta3 (not alphavbeta5) and blocks efferocytosis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"HMGB1 bound soluble alphavbeta3, suppressed the MFG-E8-alphavbeta3 interaction, decreased macrophage engulfment of apoptotic cells and inhibited ERK phosphorylation and Rac-1 activation [PMID:20826760]. This is an antagonistic, blocking effect.","molecular_requirements":"ITGAV acts as part of the alphavbeta3 heterodimer. No binding to soluble alphavbeta5 was seen, so the beta3 partner matters [PMID:20826760].","affinity_potency":[],"species_and_systems":"Macrophages with apoptotic neutrophils or thymocytes and soluble integrins; species not stated in the abstract. Curated as human; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; the integrin is membrane-bound on macrophages [PMID:20826760].","caveats":"One abstract-only paper; no affinity. Evidence is for the alphavbeta3 complex, not ITGAV alone.","key_references":[{"PMID":"20826760","why":"HMGB1 binds alphavbeta3 and blocks efferocytosis"}],"covers":["LR002735","LR005983"]},"LR005992":{"pair":"HP -> CD22","headline":"Haptoglobin was identified as a sialic-acid-dependent binder of CD22 in a 1995 affinity-adsorption study.","interaction_type":"direct binding","direction_and_effect":"Soluble CD22Rg adsorbed three plasma polypeptides eluted with alpha2-6-sialyllactose, whose N-terminal sequences were IgM and haptoglobin subunits [PMID:7706301]. CD22 is a B-cell receptor recognising sialic acid [PMID:7706301].","molecular_requirements":"Binding is sialic-acid dependent (alpha2-6 linkage); sialidase and periodate treatment abolished the CD22 interactions described for IgM [PMID:7706301]. Haptoglobin-specific controls are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human plasma and endothelial cells, chimeric CD22Rg protein [PMID:7706301]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted; CD22 is flagged as a transmembrane receptor [flag].","caveats":"Abstract-only reading; the binding is lectin-glycan recognition rather than a classic protein-protein contact, and most of the follow-up in the paper concerns IgM. No affinity reported.","key_references":[{"PMID":"7706301","why":"CD22Rg affinity adsorption identifies haptoglobin and IgM subunits"}],"covers":["LR002744","LR005992"]},"LR000799":{"pair":"ICAM4 -> ITGAV","headline":"alphaV-family integrins, notably alphaVbeta3, interact with ICAM-4; evidence is cell-based with abstract-only reading.","interaction_type":"direct binding","direction_and_effect":"Cell-surface ICAM-4 interacts with cell-surface alphaVbeta3 [PMID:15355350]. Adhesion of alpha4beta1-negative cells to ICAM-4-Fc is mediated by RGD-inhibitable alphaV integrins (notably alphaVbeta1 and alphaVbeta5), by antibody inhibition [PMID:11435317].","molecular_requirements":"The alphaVbeta3 contact site uses residues on both faces of D1 and the C'-E loop of D2, distinct from but overlapping the alphaIIbbeta3 site [PMID:15355350]. Partner beta chain varies (beta1, beta3, beta5) across studies.","affinity_potency":[],"species_and_systems":"Human ICAM-4 in [PMID:15355350]; the curated species for [PMID:11435317] is mouse here, although the abstract does not state it.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. UniProt notes ITGA2B:ITGB3 as an erythrocyte ICAM4 receptor [DB:UniProt].","caveats":"Both papers abstract only. [PMID:11435317] rests on peptide and antibody inhibition. A further judged row was abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"alphaVbeta3 contact site on ICAM-4"},{"PMID":"11435317","why":"alphaV-family integrins mediate adhesion to ICAM-4-Fc"}],"covers":["LR000799","LR004253"]},"LR007279":{"pair":"IFNA8 -> IFNAR1:IFNAR2","headline":"IFNA8 binds the IFNAR1:IFNAR2 receptor; support is a class-wide binding study on the individual chains plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"Both chains are named: for alpha-IFNs IFNAR2 binds tightly (0.4-5 nM) and IFNAR1 weakly (0.5-5 \u03bcM) [PMID:21856167]. Binding was measured on isolated chains, not on the assembled heterodimer.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"},{"value":"0.5-5 \u03bcM","assay":"affinity determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The receptor is flagged transmembrane [flag].","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR007279"]},"LR008593":{"pair":"IFNL1 -> IFNLR1:IL10RB","headline":"IFN-lambda1 signals through IFNLR1:IL10RB; one abstract-level binding paper plus structures.","interaction_type":"direct binding","direction_and_effect":"IFN-lambda1 (IL-29) interacts with a heterodimeric class II receptor of IL-10Rbeta and IL-28Ralpha; GtoPdb lists Agonist for IFNL1-IFNLR1 and IFNL1-IL10RB [PMID:12469119, DB:GtoPdb].","molecular_requirements":"Both chains form the receptor (IL-10Rbeta and IL-28Ralpha, i.e. IFNLR1) [PMID:12469119]. Reactome has IFNL1 binding IL10RB:TYK2 and IFNLR1:JAK1 [DB:Reactome]. PDB 3OG4 and 3OG6 hold structures [DB:PDB 3OG4].","affinity_potency":[],"species_and_systems":"Human, human cells [PMID:12469119].","localisation_and_range":"IFNL1 is flagged secreted and non-transmembrane; the complex is flagged transmembrane [flag].","caveats":"Abstract-only read. The curators' note calls this a duplicate subunit ordering of a pair already confirmed as IL10RB:IFNLR1.","key_references":[{"PMID":"12469119","why":"defines the IL-10Rbeta/IL-28Ralpha receptor for IL-29"}],"covers":["LR008593"]},"LR007288":{"pair":"IFNW1 -> IFNAR1:IFNAR2","headline":"IFN-omega signals through the IFNAR1:IFNAR2 complex; direct binding and structural support from abstracts.","interaction_type":"direct binding","direction_and_effect":"IFN-omega is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. It competes with IFN-alpha A for the shared alpha/beta receptor in human cells [PMID:1834641].","molecular_requirements":"The receptor is a complex of IFNAR-1 and IFNAR-2: IFNAR-2 binds all type I IFNs alone but with lower affinity and different specificity, and IFNAR-1 has low intrinsic binding but strongly affects the affinity and specificity of the complex [PMID:11278538]. PDB 3SE4 holds a human IFN-omega ternary complex [DB:PDB 3SE4].","affinity_potency":[],"species_and_systems":"Human IFN and cells [PMID:1834641]; the IFNAR-1 mutagenesis in 11278538 used the bovine receptor.","localisation_and_range":"IFNW1 is flagged secreted and non-transmembrane; the complex is flagged transmembrane [flag].","caveats":"Abstract-only reads. The mechanistic paper uses bovine IFNAR-1, and the 1991 paper cannot separate the two chains.","key_references":[{"PMID":"11278538","why":"both chains contribute to affinity and specificity"},{"PMID":"1834641","why":"IFN-omega binds the alpha/beta receptor"}],"covers":["LR007288"]},"LR008296":{"pair":"IGFBPL1 -> DCC","headline":"A full-text interactome screen saw DCC binding IGFBPL1, confirmed by SPR; no affinity quoted.","interaction_type":"direct binding","direction_and_effect":"DCC bound IGFBPL1 in the ELISA screen, and SPR also showed binding [PMID:32822567]. Direction and effect are not reported in our evidence.","molecular_requirements":"No subunit information in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins, ELISA screen then SPR (analytes 2 to 2,048 nM) [PMID:32822567].","localisation_and_range":"DCC is annotated as a transmembrane receptor [flag]; IGFBPL1 has no localisation flag.","caveats":"A single high-throughput study; no affinity value in the excerpts; no functional follow-up in our evidence.","key_references":[{"PMID":"32822567","why":"Cell-surface interactome screen with SPR validation of DCC-IGFBPL1"}],"covers":["LR008296"]},"LR002779":{"pair":"IGHE -> FCER1A","headline":"Crystal structure at 3.5 A shows human IgE-Fc bound to the Fc epsilon RI alpha chain, supported by PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"IgE binds its high-affinity receptor; UniProt says IgE stimulates the FCER1A:MS4A2:FCGR1A receptor complex on mast cells, basophils and eosinophils, leading to mediator release [DB:UniProt][PMID:10917520].","molecular_requirements":"One receptor binds one dimeric IgE-Fc asymmetrically through two sites, each involving one C epsilon3 domain [PMID:10917520]. The full receptor complex includes MS4A2 and FCGR1A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IgE-Fc with the human Fc epsilonRI alpha extracellular domains, crystal structure [PMID:10917520]; PDB entries include 1F6A [DB:PDB 1F6A].","localisation_and_range":"IGHE is annotated as secreted [flag]; the receptor chain is on the surface of effector cells per UniProt [DB:UniProt].","caveats":"Abstract-only read, truncated in the dossier. Other receptor subunits were not part of the structure described in the abstract. No affinity reported.","key_references":[{"PMID":"10917520","why":"Crystal structure of human IgE-Fc with Fc epsilonRI alpha"}],"covers":["LR002779","LR006025"]},"LR007297":{"pair":"IL17A:IL17F -> IL17RA:IL17RC","headline":"The IL-17A/F heterodimer is asserted to signal through IL-17RA:IL-17RC by databases and structures; no curated paper is verified for this exact pair.","interaction_type":"database-asserted only","direction_and_effect":"Agonist: GtoPdb lists agonist interactions for IL17A and IL17F with IL17RA and IL17RC [DB:GtoPdb]. UniProt says IL17A signals via an IL17RA-IL17RC heterodimeric complex [DB:UniProt].","molecular_requirements":"Both chains are required for signalling per UniProt and Reactome complex records [DB:UniProt, DB:Reactome]. UniProt notes that the receptor chains cannot distinguish IL17A and IL17F, and IL17A-IL17F favours IL17RA-IL17RC complexes [DB:UniProt]. PDB 6HG4 and 6HG9 are IL-17RC with IL-17F [DB:PDB 6HG4].","affinity_potency":[],"species_and_systems":"Mostly recombinant protein records; species of the cell experiments is not reported in our evidence [DB:IntAct].","localisation_and_range":"Ligand annotated as secreted and non-transmembrane; receptor annotated as transmembrane [flag]. Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"No curated paper is shown for this pair; one paper was judged abstract_insufficient. No structure shown is of the heterodimer bound to both chains.","key_references":[],"covers":["LR007297"]},"LR002788":{"pair":"IL17F -> IL17RC","headline":"IL-17F binds IL-17RC, the main IL-17F receptor chain per UniProt; support is one abstract-only SPR paper plus structures.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17F activity was inhibited by soluble IL-17RC [PMID:18684971]. UniProt calls IL17RC the cognate receptor for IL17F and notes IL17F homodimer binding triggers TRAF6 and NF-kappa-B signalling [DB:UniProt]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL17RC acts in a heterodimer with IL17RA, though UniProt notes it can act as cognate receptor for IL17F [DB:UniProt, PMID:18684971]. PDB 6HG4 and 6HG9 are human IL-17RC ECD with IL-17F [DB:PDB 6HG4].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17F annotated as secreted [flag]; IL-17RC as a receptor [flag].","caveats":"Single paper read as abstract only; no affinity values given in the abstract.","key_references":[{"PMID":"18684971","why":"SPR shows comparable binding of IL-17F to IL-17RC; soluble IL-17RC blocks IL-17F"}],"covers":["LR002788","LR006031"]},"LR000889":{"pair":"IL20 -> IL22RA1","headline":"IL-20 signals through the type II IL-20R complex (IL22RA1 plus IL20RB); binding and signalling shown in transfected cells, read from abstracts only.","interaction_type":"direct binding","direction_and_effect":"IL-20 and mda-7 bind the IL-22R/IL-20Rbeta complex, causing STAT3 phosphorylation [PMID:11564763]; IL-20 and IL-24 both signal through IL-22R/IL-20RB in reporter, proliferation and STAT assays [PMID:12351624]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"IL22RA1 acts as part of a heterodimer with IL20RB (type II IL-20R) [PMID:11564763]. Evidence is for the complex, not IL22RA1 alone. Reactome records IL20:IL22RA1:JAK1:IL20RB [DB:Reactome R-HSA-9009224].","affinity_potency":[],"species_and_systems":"Transfected receptor complexes in cell lines; species of cells not stated in the abstracts. Mouse pair is projected from human evidence.","localisation_and_range":"IL-20 is flagged secreted [flag]; receptor is membrane-bound by inference only.","caveats":"Both papers read as abstracts only. Binding is to the two-chain complex, so a single IL22RA1 row inherits complex-level evidence. IntAct lists an SPR record for the pair [DB:IntAct].","key_references":[{"PMID":"11564763","why":"binding of IL-20 to type II complex with STAT3 activation"},{"PMID":"12351624","why":"reporter/proliferation/STAT assays with IL22RA1/IL20RB"}],"covers":["LR000889","LR004319"]},"LR000898":{"pair":"IL24 -> IL20RB","headline":"IL20RB is the shared second chain for IL-24 in both receptor complexes; evidence is complex-level, abstract only.","interaction_type":"functional only","direction_and_effect":"IL-24 signals through IL-20RA/IL-20RB and IL-22R/IL-20RB in reporter, proliferation and STAT assays [PMID:12351624]; IL-24 binds both heterodimers [PMID:11706020]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL20RB is a common chain paired with either IL20RA or IL22RA1 [PMID:20061404]. IL20RB alone binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptors in transfected cells [PMID:11706020]; IL-24 transgenic mice [PMID:20061404].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"Single-chain row inherits complex-level evidence; all papers abstract-only. A structure with chains of IL24 and IL20RB exists [DB:PDB 6DF3].","key_references":[{"PMID":"11706020","why":"IL-24 binds two heterodimers sharing IL-20R2"},{"PMID":"12351624","why":"IL-24 signalling through IL-20RB-containing complexes"},{"PMID":"20061404","why":"soluble IL-20R2 blocks IL-24"}],"covers":["LR000898","LR004328"]},"LR002797":{"pair":"IL25 -> IL17RA","headline":"IL25 -> IL17RA rests only on database records; no verified paper supports it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL25-IL17RA as an agonist [DB:GtoPdb]. UniProt says IL-25 acts through a receptor composed of IL17RA and IL17RB, by similarity [DB:UniProt].","molecular_requirements":"Receptor is a two-chain assembly of IL17RA and IL17RB [DB:UniProt]; IL17RA alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagging not given beyond secretion absence; not reported in our evidence.","caveats":"No papers judged; two rows were different_entity. UniProt statement is by similarity.","key_references":[],"covers":["LR002797","LR006040"]},"LR008782":{"pair":"IL36G -> IL36RN","headline":"Ligand-ligand pair supported only by PDB structures of IL-36Ra; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"No signalling direction reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; X-ray structures only [DB:PDB 4P0J].","localisation_and_range":"Both partners annotated secreted [flag].","caveats":"PDB records are titled loop-swapped IL-36Ra structures [DB:PDB 4P0J][DB:PDB 4P0K], which look like engineered chimeras rather than a real complex. One review-only row.","key_references":[],"covers":["LR008782"]},"LR007927":{"pair":"INHA:INHBA -> ACVR1B:ACVR2A","headline":"Inhibin-A (INHA:INHBA) to ACVR1B:ACVR2A: database support, mostly via activin A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA and INHBA with ACVR2A as agonist [DB:GtoPdb]. UniProt notes activin A can form a non-signalling complex with ACVR1 and a type II receptor, rendering receptors unavailable to BMPs [DB:UniProt]. Inhibin-A effect is not directly evidenced in our evidence.","molecular_requirements":"Type II chain ACVR2A binds activin A/inhibin per databases; UniProt says it binds inhibin-A/INHA-INHBA [DB:UniProt]. PDB 7U5P shows ACVR2A ligand-binding region with activin A [DB:PDB 7U5P]. Type I chain ACVR1B is not specifically evidenced.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence. X-ray structure PDB 7U5P (35643319) [DB:PDB 7U5P]; BioGRID has INHA and INHBA with ACVR2A [DB:BioGRID 275207][DB:BioGRID 2513581].","localisation_and_range":"Ligand heterodimer flagged secreted [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. The PDB structure is activin A (INHBA) with the receptor, not the INHA:INHBA heterodimer; evidence concerns INHBA rather than the inhibin heterodimer.","key_references":[],"covers":["LR007927"]},"LR007936":{"pair":"INHA:INHBB -> ACVR1C:ACVR2B","headline":"Inhibin A:activin B to ACVR1C:ACVR2B rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records INHBB-ACVR2B (Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I plus type II pair (ACVR1C:ACVR2B). UniProt notes INHBB-related signalling through ACVR1C with type II receptors such as ACVR2A or BMPR2 where relevant [DB:UniProt]; whether this specific heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007936"]},"LR010789":{"pair":"ITGAM:ITGB2 -> ICAM1","headline":"Mac-1 (ITGAM:ITGB2) binding to ICAM1 is supported by database records only; no paper judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says the ITGAM:ITGB2/MAC-1 complex is a signalling receptor for ICAM1 [DB:UniProt]. BioGRID lists reconstituted complexes [DB:BioGRID].","molecular_requirements":"Both chains in the complex; BioGRID has ITGAM-ICAM1 and ITGB2-ICAM1 entries [DB:BioGRID].","affinity_potency":[],"species_and_systems":"No experimental paper judged for this pair; species is human per the record.","localisation_and_range":"Both partners carry receptor flags and VCAM1 is flagged transmembrane [flag]; contact-mediated adhesion is implied by the plasma membrane complexes listed [DB:Reactome].","caveats":"Three pending papers not judged. The shown Reactome examples describe the ITGAL complex, not ITGAM [DB:Reactome].","key_references":[],"covers":["LR010789"]},"LR008575":{"pair":"ITGAX:ITGB2 -> ICAM1","headline":"No curated paper supports ITGAX:ITGB2 with ICAM1; only database records exist.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"BioGRID lists reconstituted complexes involving ITGB2 and ICAM1 [DB:BioGRID]; none is shown for ITGAX specifically.","affinity_potency":[],"species_and_systems":"Human; no paper-based system.","localisation_and_range":"Both are membrane proteins [flag].","caveats":"Three papers judged abstract_insufficient, so none confirm this pair. Database examples mainly concern ITGB2, not ITGAX.","key_references":[],"covers":["LR008575"]},"LR004399":{"pair":"LAMA1 -> ITGA6","headline":"Functional evidence that laminin supports alpha6beta4-dependent cell adhesion under flow; abstract-only and heterotrimer-level.","interaction_type":"functional only","direction_and_effect":"Laminin supported attachment and rolling of alpha6beta4-positive cells under shear, and an anti-alpha6 antibody blocked attachment and detached adherent cells [PMID:7699012].","molecular_requirements":"The receptor in this paper is the alpha6beta4 heterodimer; laminin fragment E8 supported attachment while fibronectin did not [PMID:7699012].","affinity_potency":[],"species_and_systems":"Cell lines expressing alpha6beta4 in a laminar-flow assay; species not stated [PMID:7699012].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand supporting dynamic cell adhesion [PMID:7699012].","caveats":"Abstract only; the ligand is the laminin heterotrimer, not LAMA1 alone, and the receptor is alpha6beta4, not ITGA6 alone. Two other confirmed rows and two review-only rows are not shown.","key_references":[{"PMID":"7699012","why":"Alpha6beta4-mediated adhesion to laminin under flow"}],"covers":["LR000978","LR004399"]},"LR000979":{"pair":"LAMA1 -> ITGA7","headline":"Recombinant alpha7 integrin binds laminin-111 with Kd 0.97 nM; confirmed by one full-text and one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha7beta1 binds laminin-111 in solid-phase assay [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-1 that mediates myoblast migration on it [PMID:11278916]. Record labelled Stimulatory [flag].","molecular_requirements":"The alpha7X2beta1 splice variant bound laminin-111; the alpha7X1beta1 variant only partially saturated (ND(+)) for laminin-111 [PMID:16413178]. The receptor was a heterodimer with beta1 [PMID:16413178].","affinity_potency":[{"value":"Kd 0.97 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha7X2beta1 ectodomain with laminin-111","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human transfected myoblasts and HEK293 cells on laminin [PMID:11278916].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. The second paper states receptor identity as background and is abstract-only [PMID:11278916].","key_references":[{"PMID":"16413178","why":"Kd 0.97 nM for alpha7X2beta1 and laminin-111"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin-1"}],"covers":["LR000979","LR004400"]},"LR000997":{"pair":"LAMA5 -> ITGB1","headline":"Laminin alpha5 (as laminin-511/521, -10/11) engages integrin beta1 pairings, shown by binding and antibody blockade; chain-level only.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand [PMID:15677332]. Anti-beta1 antibodies blocked adhesion of mouse FDCP-mix cells to alpha5-laminins [PMID:10194432] and of A549 cells to laminin-10/11 [PMID:9624186]. Annotated stimulatory.","molecular_requirements":"ITGB1 acts in alpha/beta heterodimers (alpha3beta1 and alpha6beta1 in these papers); the alpha partner determines specificity and ITGB1 alone was not tested [PMID:16413178][PMID:10194432]. Laminin is the assembled heterotrimer.","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins and human A549 cells [PMID:16413178][PMID:9624186]; mouse cells [PMID:10194432]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The Kd belongs to the alpha3beta1 heterodimer, not ITGB1 alone. Three of the four confirming papers are abstract-only reads, two being antibody-blocking adhesion assays.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"9624186","why":"Anti-beta1/alpha3 blocked adhesion to laminin-10/11"}],"covers":["LR000997","LR004416"]},"LR001000":{"pair":"LAMB1 -> ITGA6","headline":"Laminin beta1-containing laminins engage integrin alpha6 (alpha6beta1, alpha6beta4) in adhesion assays; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"Human platelet adhesion to purified platelet laminin was largely inhibited by antibodies to beta1 and alpha6 integrin chains [PMID:10585296]. Laminin supported alpha6beta4-positive cell attachment under shear stress, and an anti-alpha6 antibody inhibited it [PMID:7699012]. Annotated stimulatory.","molecular_requirements":"The alpha6 chain pairs with beta1 or beta4 in these papers; the ligand is the whole laminin heterotrimer, so LAMB1 is inferred [PMID:7699012]. A PDB entry has chains P07942 and P23229 [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Human platelets [PMID:10585296]; cell species not reported in our evidence for the flow assay [PMID:7699012]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA6 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers are abstract-only, antibody-blocking or adhesion readouts without a direct binding measurement. Another paper was review_only.","key_references":[{"PMID":"10585296","why":"Platelet adhesion to laminin blocked by anti-alpha6/beta1"},{"PMID":"7699012","why":"alpha6beta4 adhesion to laminin under flow"}],"covers":["LR001000","LR004419"]},"LR010699":{"pair":"LAMB1 -> ITGA9:ITGB1","headline":"Complex row for laminin beta1 and integrin alpha9beta1; only PDB and similarity-based UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P05556 [DB:PDB 7CEC]; UniProt notes ITGB1 interacts with LAMB1 (by similarity) [DB:UniProt].","molecular_requirements":"Receptor is the ITGA9:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA9:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The only judged paper was review_only, so no primary evidence is available. UniProt note is by similarity and does not test ITGA9.","key_references":[],"covers":["LR010699"]},"LR002869":{"pair":"LAMB2 -> ITGB1","headline":"LAMB2 (in laminin-511/521) binds integrin beta1 (as alpha3beta1) at low nM Kd; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, bound recombinant integrin ectodomain in solid-phase saturation binding [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"The beta1 chain was tested as part of an alpha-beta heterodimer (the 3.4 nM value is in the alpha3beta1 column of the table), not alone; the ligand is the whole heterotrimer [PMID:16413178]. PDB 7CEC lists chains of P11047 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain and with an alpha-beta heterodimer, so a beta1-chain-specific contribution is not separated.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"}],"covers":["LR002869","LR006103"]},"LR009493":{"pair":"LAMB3 -> ITGA2","headline":"LAMB3 with ITGA2 rests on a Reactome record (alpha2beta1 binds laminin-332) only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626]; annotated effect is Stimulatory [flag]. Direction is laminin to integrin.","molecular_requirements":"Laminin-332 is the ligand and alpha2beta1 the binder in the Reactome record; whether ITGA2 alone suffices is not reported.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. One further paper was review_only and three were abstract_insufficient.","key_references":[],"covers":["LR009493"]},"LR002878":{"pair":"LEFTY2 -> ACVR2A","headline":"Lefty2 is proposed to antagonise Nodal by competing for ActRIIA; evidence is one abstract-only inference, not binding.","interaction_type":"functional only","direction_and_effect":"Antagonist: processed Lefty proteins inhibited Nodal signalling, and the inhibition was rescued by excess ActRIIA or ActRIIB, which the authors take to suggest competitive binding to the shared receptor [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can serve as the type II receptor for Nodal, with ALK4 as type I; both smaller and larger processed Lefty forms inhibited. Other requirements not reported in our evidence [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal-cap assay, mouse genetic interaction (lefty2 with ActRIIB), and chick embryos; curator lists mouse ligand and Xenopus receptor. The human pair is ortholog-inferred [PMID:11952836].","localisation_and_range":"Lefty2 is flagged as secreted and ACVR2A as transmembrane [flag]; range of action not otherwise reported in our evidence. GFP-Lefty2 diffused faster than GFP-Nodal in chick embryos [PMID:11952836].","caveats":"Hedged: the rescue is an epistasis argument and direct Lefty2 binding to ActRIIA is not shown. The paper was read as abstract only; no other papers or database records.","key_references":[{"PMID":"11952836","why":"Rescue of Lefty inhibition by excess ActRIIA/ActRIIB in frog caps"}],"covers":["LR002878","LR006112"]},"LR001879":{"pair":"LGALS1 -> PTPRC","headline":"Galectin-1 binds CD45 on Jurkat T cells and suppresses its phosphatase activity; supported by papers plus BioGRID/IntAct.","interaction_type":"direct binding","direction_and_effect":"Galectin-1 reduced membrane-associated PTPase activity and immunoprecipitated CD45 activity in Jurkat cells; CD45+ cells showed higher galectin-1-induced phosphatidylserine than CD45- cells, implicating CD45 ligation in apoptosis [PMID:10369126].","molecular_requirements":"CD45 isoforms were detected in the galectin-1-agarose bound fraction [PMID:10369126]. Binds N-acetyllactosamine glycans, so glycosylation is relevant [PMID:10369126].","affinity_potency":[],"species_and_systems":"Human Jurkat T cell membranes and cells; placental galectin-1 [PMID:10369126]. Mouse pair ortholog-inferred. BioGRID lists Affinity Capture-Western and IntAct an enzymatic study [DB:BioGRID][DB:IntAct].","localisation_and_range":"Galectin-1 flagged secreted; PTPRC flagged transmembrane [flag].","caveats":"Affinity chromatography on immobilised galectin-1 does not exclude indirect association; abstract-only read.","key_references":[{"PMID":"10369126","why":"Galectin-1 agarose pulls down CD45; inhibits PTPase activity"}],"covers":["LR001879","LR005221"]},"LR002887":{"pair":"LGALS3 -> MERTK","headline":"Galectin-3 acts as a MERTK ligand promoting Muller glia phagocytosis, with genetic support in mouse retina.","interaction_type":"functional only","direction_and_effect":"Galectin-3 promoted phagocytosis by wild-type but not MERTK-deficient primary Muller glia, and galectin-3/MERTK double-knockout mice showed more Muller cell activation and photoreceptor loss; galectin-3 restrained Muller glia activation [PMID:35711472].","molecular_requirements":"MERTK required for the galectin-3 effect; effects of galectin-3 and protein S were additive at sub-saturating concentrations [PMID:35711472].","affinity_potency":[],"species_and_systems":"Immortalised human MIO-M1 Muller cells, primary mouse Muller glia, and knockout mice including a sodium-iodate injury model [PMID:35711472].","localisation_and_range":"Extracellular galectin-3 acts on Muller glia; galectin-3 flagged secreted, MERTK transmembrane [flag].","caveats":"Direct binding to MERTK not shown in our excerpts; the paper says galectin-3 had been shown able to activate MERTK in earlier work, which is background. Abstract-only read.","key_references":[{"PMID":"35711472","why":"Galectin-3 promotes MERTK-dependent Muller glia phagocytosis"}],"covers":["LR002887","LR006121"]},"LR002896":{"pair":"LGALS3BP -> SIGLEC9","headline":"LGALS3BP was identified by affinity chromatography as a sialic-acid-dependent ligand of SIGLEC9 and inhibits neutrophil activation; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"LGALS3BP is a sialic acid-dependent ligand for human Siglec-9, Siglec-5 and Siglec-10, and inhibited neutrophil activation in a sialic acid- and Siglec-dependent manner (immunoinhibitory) [PMID:25320078].","molecular_requirements":"Sialic acid on LGALS3BP is required; the paper does not say whether other chains are needed [PMID:25320078].","affinity_potency":[],"species_and_systems":"Human tumour cell extracts; neutrophil assay system is not specified in the abstract. The mouse homolog Siglec-E binds murine LGALS3BP with lower affinity [PMID:25320078].","localisation_and_range":"LGALS3BP is a heavily glycosylated secreted molecule, up-regulated in the extracellular matrix of colorectal and prostate cancer [PMID:25320078].","caveats":"Abstract only. The inhibition of neutrophil activation was shown for Siglecs collectively, not necessarily SIGLEC9 specifically. Same paper supports three Siglec partners. BioGRID lists Affinity Capture-Western, Affinity Capture-MS and Reconstituted Complex records [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"25320078","why":"LGALS3BP identified as a sialic acid-dependent ligand for CD33-related Siglecs"}],"covers":["LR002896"]},"LR001888":{"pair":"LGI2 -> ADAM23","headline":"LGI2 co-precipitates with Adam23 from rat brain; one full-text paper, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Both Adam22 and Adam23 antibodies co-precipitated Lgi2 from rat brain [PMID:21829378]. The paper's section title states Lgi2 K518X truncation prevents LGI2 secretion and action on neuronal ADAM receptors [PMID:21829378]. Reactome lists LGI2 binding ADAM22,23 [DB:Reactome].","molecular_requirements":"Reactome lists a complex LGI2:ADAM22,23 at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Rat brain co-IP and cell-surface binding assay; excerpts include Lagotto Romagnolo dogs, so curator's human label does not match [PMID:21829378]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LGI family are neuronally secreted proteins [PMID:21829378]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"A co-IP shows association, not direct binding; effect direction and affinity are not reported in our evidence. Reactome is the only database.","key_references":[{"PMID":"21829378","why":"Lgi2 co-IPs with Adam22/23; truncation blocks secretion"}],"covers":["LR001888","LR005230"]},"LR008494":{"pair":"LINGO1 -> RTN4","headline":"No curated paper supports LINGO1 binding RTN4; only a UniProt functional statement about the Nogo receptor complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this pair. UniProt describes LINGO1 as a functional component of the Nogo receptor signaling complex (RTN4R/NGFR) in RhoA activation [DB:UniProt].","molecular_requirements":"The UniProt text names RTN4R and NGFR as complex partners, not RTN4 itself [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Neither entity is flagged secreted [flag].","caveats":"No confirmed papers: four rows were judged a different entity and two abstract-insufficient. UniProt text concerns the receptor RTN4R, so the pair may be mis-assigned.","key_references":[],"covers":["LR008494"]},"LR001897":{"pair":"LRRC4B -> PTPRF","headline":"NGL-3 (LRRC4B) binds LAR (PTPRF) trans-synaptically to drive bidirectional synapse formation; supported by three papers and Reactome.","interaction_type":"direct binding","direction_and_effect":"NGL-3 and LAR in heterologous cells induced pre- and postsynaptic differentiation in contacting rat hippocampal neurons; NGL-3 knockdown reduced excitatory synapse number and function, and soluble LAR reduced NGL-3-induced presynaptic differentiation [PMID:19252495]. Curators label it agonist [PMID:19252495].","molecular_requirements":"The NGL-3 LRR domain (nine LRRs) binds the first two FNIII domains of LAR, and Gln-96 in the first LRR is critical for LAR binding and presynaptic induction [PMID:20139422]. In a cell aggregation assay, NGL-3 cells adhered strongly to LAR cells [PMID:23345436].","affinity_potency":[],"species_and_systems":"Rat hippocampal neurons and heterologous cells [PMID:19252495]; mouse L-cells for aggregation [PMID:23345436]. Reactome lists the complex [DB:Reactome]. The human pair is not ortholog-inferred; mouse is.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion; LRRC4B is flagged non-secreted [flag].","caveats":"No affinity in our evidence. 23345436 was read via browser and its quote is marked unverifiable pending spot-check; it cites the earlier work as consistent. Two further judged papers were review_only and one abstract_insufficient.","key_references":[{"PMID":"19252495","why":"Discovery of trans-synaptic NGL-3-LAR interaction with functional assays"},{"PMID":"20139422","why":"Maps LRR/FNIII interface and Gln-96"},{"PMID":"23345436","why":"Cell aggregation confirms NGL-3 adhesion to LAR"}],"covers":["LR001897","LR005239"]},"LR007981":{"pair":"MICB -> HCST:KLRK1","headline":"MICB is a membrane-bound activating ligand of NKG2D in UniProt; paper evidence is thin.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes MICB as a widely expressed membrane-bound ligand that stimulates the activating receptor KLRK1/NKG2D on NK, gammadelta T and CD8+ alphabeta T cells [DB:UniProt].","molecular_requirements":"HCST (DAP10) co-subunit is not reported in our evidence for MICB.","affinity_potency":[],"species_and_systems":"Species of experiments not reported for MICB itself; the one confirmed paper worked with mouse NKG2D ligands [PMID:10894171].","localisation_and_range":"MICB is flagged both secreted and transmembrane [flag]; UniProt calls it membrane-bound [DB:UniProt].","caveats":"The only confirmed paper mentions MICB in a sentence citing other work, so no primary MICB evidence is shown. Two other papers were abstract_insufficient and one review_only.","key_references":[{"PMID":"10894171","why":"Mouse NKG2D ligands paper; mentions MICB only as background"}],"covers":["LR007981"]},"LR002959":{"pair":"MMP1 -> LRP1","headline":"MMP-1 binds the endocytic receptor LRP1 by SPR in two 2020 papers; this is a scavenging interaction.","interaction_type":"direct binding","direction_and_effect":"LRP1 binds proMMP-1, active MMP-1 and MMP-1/TIMP-1 complex, and binding was abolished by RAP or EDTA [PMID:32702237]. TIMP-3 raised MMP-1 affinity sevenfold and increased endocytosis, consistent with clearance [PMID:32694578].","molecular_requirements":"MMP-1 binds through its hemopexin domain; lysine residues on MMP-1 and TIMP-1 are essential [PMID:32694578] [PMID:32702237]. TIMP complexes bind with higher affinity [PMID:32694578].","affinity_potency":[{"value":"Kd 34.6 nM","assay":"surface plasmon resonance, free MMP-1","system":"purified LRP-1","cite":"PMID:32694578"},{"value":"Kd 4.96 nM","assay":"SPR, MMP-1/TIMP-3 complex","system":"purified LRP-1","cite":"PMID:32694578"}],"species_and_systems":"Human proteins and cells (HTB94) [PMID:32694578].","localisation_and_range":"MMP-1 flagged secreted [flag]; LRP1 clears extracellular MMP-1 by endocytosis [PMID:32694578].","caveats":"Abstract-only reading; the second paper's abstract is truncated before its Kd values [PMID:32702237]. Scavenger rather than signalling receptor; effect labelled agonist by curators.","key_references":[{"PMID":"32694578","why":"SPR affinities and TIMP-3 bridging"},{"PMID":"32702237","why":"MMP-1 as novel LRP1 ligand, RAP-inhibited"}],"covers":["LR002959"]},"LR004489":{"pair":"MMP9 -> CD44","headline":"CD44 docks MMP-9 at the cell surface; supported by colocalisation, co-IP and functional papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"CD44 provides a cell-surface docking receptor for proteolytically active MMP-9 [PMID:10652271]. CD44 crosslinking raised membrane MMP-9, and CD44 clusters act as an MMP-9 docking site retaining proteolytic activity at the surface [PMID:17912438]. MMP-9 surface localisation on normal keratinocytes was CD44-dependent [PMID:10652271].","molecular_requirements":"Not reported in our evidence beyond CD44 and MMP-9 forming a complex purified by immunoprecipitation [PMID:17912438].","affinity_potency":[],"species_and_systems":"Human MDA-MB-435s breast tumour cells [PMID:17912438]; human experiment species for ligand and receptor in the other paper, with keratinocytes and tumour models [PMID:10652271]. Reactome lists CD44:MMP2, MMP7, MMP9 binding and complex [DB:Reactome]. The human row is ortholog-inferred.","localisation_and_range":"MMP9 is flagged as secreted; CD44 is flagged both secreted and transmembrane [flag]. The papers describe MMP-9 retained on the cell surface.","caveats":"Both papers were read as abstract only. This is docking of a protease, not classical signalling. One further paper is pending and not shown. Human pair is projected from mouse.","key_references":[{"PMID":"17912438","why":"Colocalisation and co-IP of CD44-MMP-9 after crosslinking"},{"PMID":"10652271","why":"CD44 as MMP-9 docking receptor; CD44-dependent surface localisation"}],"covers":["LR001077","LR004489"]},"LR002968":{"pair":"MSTN -> ACVR1B","headline":"Myostatin signals via ActRIIB with ALK4 as one possible type I partner; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Myostatin binds the type II receptor ActRIIB, then partners with ALK4 or ALK5 to phosphorylate Smad2/Smad3 [PMID:14517293].","molecular_requirements":"ACVR1B (ALK4) is a type I chain recruited after ActRIIB; ALK5 can substitute, so ALK4 is not obligate [PMID:14517293].","affinity_potency":[],"species_and_systems":"Cell-based signalling and receptor binding experiments; species labelled human; mouse pair is ortholog-inferred [PMID:14517293].","localisation_and_range":"Myostatin is secreted [flag]; paracrine or endocrine.","caveats":"Abstract only. ALK4 is a downstream partner of the type II receptor, not shown as a direct binder alone.","key_references":[{"PMID":"14517293","why":"Myostatin to ActRIIB then ALK4/ALK5"}],"covers":["LR002968","LR006193"]},"LR006199":{"pair":"NAMPT -> TLR4","headline":"Direct binding of recombinant NAMPT/PBEF to TLR4 by SPR, with TLR4-dependent NF-kB activation and lung injury.","interaction_type":"direct binding","direction_and_effect":"NAMPT/PBEF acts as a TLR4 agonist: TLR4 antibodies or inhibitors reduced rPBEF-induced NF-kB Ser536 phosphorylation, and rPBEF-induced lung inflammation was reduced in TLR4-/- mice [PMID:26272519].","molecular_requirements":"The paper proposes MD-2-independent activation, via a protruding region (S402-N412) resembling LPS; this is predicted, not confirmed by mutation [PMID:26272519].","affinity_potency":[],"species_and_systems":"Human lung endothelial cells, recombinant proteins in SPR, and mice (wild type and TLR4-/-) [PMID:26272519]. In silico modelling used murine NAMPT/PBEF.","localisation_and_range":"NAMPT flagged secreted [flag]; extracellular NAMPT is described as released and acting on lung endothelium [PMID:26272519].","caveats":"SPR was qualitative (no Kd reported). The dossier excerpts do not show a binding assay in cells; activity relies on inhibitors and knockouts. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"26272519","why":"SPR binding and TLR4-dependent NF-kB activation by NAMPT/PBEF"}],"covers":["LR002974","LR006199"]},"LR004498":{"pair":"NCAM1 -> FGFR1","headline":"Direct NCAM-FGFR1 binding shown by SPR and immunoprecipitation across several papers.","interaction_type":"direct binding","direction_and_effect":"CD56/NCAM on NK-92 cells ligated FGFR1 beta on Jurkat T cells and costimulated TCR/CD3-triggered IL-2 production, inhibited 50-75% by CD56 mAbs [PMID:12121226]. Curator labels effect as agonist/stimulatory.","molecular_requirements":"NCAM F3 modules 1 and 2 bound FGFR1 Ig modules 2 and 3 by SPR; individual F3 modules did not bind detectably, so both are needed [PMID:12791257]. A later paper reports the second FGFR Ig module is also involved [PMID:18593816].","affinity_potency":[{"value":"10 uM Kd","assay":"surface plasmon resonance","system":"purified recombinant NCAM F3 modules 1+2 with FGFR modules","cite":"PMID:12791257"}],"species_and_systems":"Human proteins and cells in the SPR and Jurkat/NK-92 work; species unspecified for [PMID:18593816]. Mouse pair is ortholog-inferred.","localisation_and_range":"NCAM is flagged secreted/transmembrane [flag]; the Jurkat/NK-92 result is trans cell-cell contact [PMID:12121226].","caveats":"Two papers were abstract-only. The IL-2 conclusion is hedged by the authors. A 10 uM Kd is low affinity, which the authors argue suffices physiologically [PMID:12791257].","key_references":[{"PMID":"12791257","why":"SPR direct interaction of NCAM F3 modules with FGFR1, Kd 10 uM"},{"PMID":"12121226","why":"CD56 engages FGFR1 and costimulates IL-2 in Jurkat T cells"},{"PMID":"18593816","why":"SPR/NMR: FGFR Ig module 2 also binds NCAM"}],"covers":["LR001087","LR004498"]},"LR002977":{"pair":"NCAM1 -> NCAM1","headline":"Homophilic NCAM-NCAM binding with force spectroscopy and signalling evidence.","interaction_type":"direct binding","direction_and_effect":"NCAM binds in two spatially distinct configurations by force measurements [PMID:15118102]. A homophilic-site peptide (P2) increased intracellular Ca2+ in primary hippocampal neurons through FGFR/PLCgamma and Src-family kinase pathways [PMID:16510522].","molecular_requirements":"The extracellular region has five Ig and two fibronectin domains; Ig-domain deletions mapped the domains for each bond, and a flexible hinge was found [PMID:15118102]. Reactome lists cis-homodimer and trans-homotetramer complexes [DB:Reactome R-HSA-190988, R-HSA-375103].","affinity_potency":[],"species_and_systems":"Both papers abstract-only; species recorded as human in curation fields. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane-bound, so homophilic binding is cis or trans contact (adhesive) [flag].","caveats":"Self-interaction: the ligand and receptor are the same chain, which CCC tools score unusually. The Ca2+ paper used a mimetic peptide, not full NCAM [PMID:16510522].","key_references":[{"PMID":"15118102","why":"Force measurements of NCAM homophilic binding"},{"PMID":"16510522","why":"P2 peptide mimics homophilic NCAM signalling, Ca2+ rise"}],"covers":["LR002977","LR006202"]},"LR002986":{"pair":"NEGR1 -> NEGR1","headline":"NEGR1 homodimerises in trans through its first Ig domain; a self-interaction with structural and cell-aggregation support.","interaction_type":"direct binding","direction_and_effect":"IgLONs, including NEGR1, interact as homo- and heterodimers; NEGR1 oligomerised concentration-dependently by size-exclusion chromatography, and NTRI and NEGR1 homo- and heterodimerize in trans in cell aggregation assays [PMID:30956130]. Signalling direction is not reported.","molecular_requirements":"Dimerisation occurs through the first Ig domain of each monomer and is calcium-independent [PMID:30956130].","affinity_potency":[],"species_and_systems":"Recombinant proteins and cell aggregation assays; species not stated in our excerpts, curator recorded human [PMID:30956130]. Mouse pair is projected.","localisation_and_range":"Cell-surface protein by flag [flag]; trans interaction between cells [PMID:30956130].","caveats":"Abstract-level reading for curator fields. Homodimer, so ligand and receptor are the same molecule; dossier shows one of two confirmed papers. IntAct has a protein array record [DB:IntAct].","key_references":[{"PMID":"30956130","why":"IgLON homo/heterodimer structures and aggregation"}],"covers":["LR002986","LR006211"]},"LR007369":{"pair":"NODAL -> ACVR1B:ACVR2B:TDGF1","headline":"No verified paper; only database records support the complex.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted complexes of NODAL with TDGF1, ACVR2A and ACVR2B [DB:BioGRID]; UniProt states CRIPTO acts as a Nodal coreceptor in cis [DB:UniProt].","molecular_requirements":"Row includes TDGF1 co-receptor, ACVR1B and ACVR2B; individual evidence is not shown.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"The single judged paper was review-only, so no primary experimental support is verified.","key_references":[],"covers":["LR007369"]},"LR002995":{"pair":"NPDC1 -> PILRA","headline":"NPDC1 is a novel PILR-alpha binding partner; binding needs sialylated O-glycans and a conserved Arg; one paper.","interaction_type":"direct binding","direction_and_effect":"NPDC1 was identified as a PILR-alpha binding partner, with PILR-alpha described as an inhibitory receptor [PMID:22396535].","molecular_requirements":"Sialylated O-glycans on ligands are compulsory for PILR-alpha binding, and Arg-133 (mouse) or Arg-126 (human) of PILR-alpha is required [PMID:22396535]. IntAct lists SPR [DB:IntAct, PMID:22396535].","affinity_potency":[],"species_and_systems":"Mouse and human PILR-alpha mutagenesis; experiment system for NPDC1 not detailed in our evidence [PMID:22396535].","localisation_and_range":"NPDC1 is flagged non-secreted [flag]; PILRA is flagged both secreted and transmembrane [flag].","caveats":"Abstract only. Binding depends on ligand glycosylation, so recombinant or non-glycosylated forms may not bind.","key_references":[{"PMID":"22396535","why":"Sialylation-dependent PILR-alpha ligands including NPDC1"}],"covers":["LR002995","LR006219"]},"LR004579":{"pair":"NTN4 -> DCC","headline":"Netrin-4 binds DCC-transfected CHO cells through its N-terminal domain; single abstract-only study.","interaction_type":"direct binding","direction_and_effect":"AP4-tagged netrin-4 bound CHO cells transfected with DCC or UNC5H1, and only the N-terminal LNT domain of netrin-4 bound them [PMID:17174565].","molecular_requirements":"Netrin-4 also binds neurons through its N- and C-terminal domains, which suggests additional unidentified receptors [PMID:17174565].","affinity_potency":[],"species_and_systems":"COS7-produced AP4-netrin-4 fusion, CHO transfectants, cultured primary cortical neurons [PMID:17174565]. IntAct lists a solid phase assay and Reactome lists a NTN4:DCC,UNC5A complex [DB:IntAct][DB:Reactome]. Both species pairs are ortholog-inferred.","localisation_and_range":"Netrin-4 is secreted and DCC is transmembrane [flag].","caveats":"Abstract only, no affinity reported. The Reactome entry rests on the same paper.","key_references":[{"PMID":"17174565","why":"Netrin-4 binds DCC and UNC5H1 transfected cells via the LNT domain"}],"covers":["LR001170","LR004579"]},"LR004588":{"pair":"NXPH3 -> NRXN1","headline":"Neurexophilin-3 binds neurexin LNS2, shown by recombinant binding in mouse and a 2019 study; one more paper is pending.","interaction_type":"direct binding","direction_and_effect":"Neurexophilins 1 and 3 but not 4 bind the second LNS domain in all three alpha-neurexins [PMID:9856994]. The 2019 study tested binding of Nxph1 and Nxph3 to Nrxn1-3 LNS2SS2- and reports reduced binding affinity for both with I401Q mutants [PMID:31566781].","molecular_requirements":"LNS2 domain is required, all splice variants bind in the 1998 study [PMID:9856994]. The I401Q mutation weakens binding [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins and knockout mice [PMID:9856994]; recombinant structure-based assays [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The NXPH3 evidence in [PMID:31566781] is a figure-legend sentence and no affinity numbers are in our excerpts. [PMID:9856994] read as abstract only. One more paper is pending.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001179","LR004588"]},"LR004597":{"pair":"OSM -> OSMR","headline":"OSM signals through OSMR (OSMRbeta) paired with gp130; functional and structural-mapping evidence, no direct binding data.","interaction_type":"functional only","direction_and_effect":"OSMRbeta forms a gp130-OSMRbeta complex activated by OSM but not LIF [PMID:8999038]. The OSM site 3 motif (Phe160/Lys163) is responsible for LIFR and OSMR binding [PMID:10997905]. GtoPdb lists OSM as agonist of OSMR [DB:GtoPdb].","molecular_requirements":"OSMR acts with gp130 as a heterodimer [PMID:8999038]; OSMR on its own is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, abstract-level; mouse pair is ortholog-inferred, not tested.","localisation_and_range":"OSM is flagged secreted [flag]; OSMR carries a receptor flag only [flag].","caveats":"Both papers abstract only; the structure is of OSM alone [PMID:10997905]. No binding affinity. One further paper is still pending and not shown.","key_references":[{"PMID":"8999038","why":"Cloning of OSMRbeta; OSM-specific gp130 complex"},{"PMID":"10997905","why":"OSM site 3 epitope for OSMR"}],"covers":["LR001188","LR004597"]},"LR006298":{"pair":"PCDHGA9 -> PCDHGA9","headline":"Homophilic trans binding of mouse gammaA9 shown by K562 aggregation assays; support is one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Homophilic (self-self) trans interaction, not a classical ligand-to-receptor signal; no agonist or antagonist effect is reported. The paper names gammaA9 as engaging strict trans homophilic specificity and not binding gammaA8 heterophilically [PMID:25171406].","molecular_requirements":"Surface delivery of Pcdh-alpha isoforms requires cis interactions with other Pcdhs via EC6, so the species meeting across the cleft is a multimer rather than a single isoform [PMID:25171406]. Specificity sits in the EC2-EC3 recognition domains [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse proteins in K562 cell aggregation assays [PMID:25171406]; the human pair is ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; acts by cell-cell contact (juxtacrine).","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. Two further papers were judged abstract-insufficient.","key_references":[{"PMID":"25171406","why":"Cell aggregation and biochemistry across clustered Pcdh isoforms; names gammaA9 as homophilic."}],"covers":["LR003075","LR006298"]},"LR007387":{"pair":"PDGFD -> PDGFRA:PDGFRB","headline":"PDGFD -> PDGFRA:PDGFRB is supported only by single-cell inference in one human case report.","interaction_type":"functional only","direction_and_effect":"In single-cell data from one NF1 patient's sural nerve, interactome analysis suggested Schwann cells secrete PDGF ligands activating fibroblasts and mural cells; the paper names PDGFD-PDGFRB and PDGFC-PDGFRA [PMID:42539570].","molecular_requirements":"The paper names PDGFRB for PDGFD, not the heterodimer [PMID:42539570].","affinity_potency":[],"species_and_systems":"Human, one patient biopsy, scRNA-seq computational inference, abstract only [PMID:42539570].","localisation_and_range":"Paracrine secretion by Schwann cells is described [PMID:42539570]; PDGFD flagged secreted [flag].","caveats":"Computational inference only, no perturbation or binding; single case report; abstract read and truncated. It supports PDGFD-PDGFRB, not the heterodimer specifically.","key_references":[{"PMID":"42539570","why":"Single-cell interactome inference in a human nerve biopsy"}],"covers":["LR007387"]},"LR008539":{"pair":"PORCN -> WNT3A","headline":"Cryo-EM structures show human PORCN with a WNT3A peptide, but this is an enzyme-substrate complex, not a signalling ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"PDB holds human PORCN in complex with palmitoleoylated WNT3A peptide and with LGK974 plus a WNT3A peptide [DB:PDB 7URD][DB:PDB 7URE]. UniProt notes WNT3A interacts with PORCN [DB:UniProt].","molecular_requirements":"Structures use a WNT3A peptide, not full-length protein [DB:PDB 7URE].","affinity_potency":[],"species_and_systems":"Human PORCN, electron microscopy structures [DB:PDB 7URD]; no verified papers.","localisation_and_range":"Not reported in our evidence.","caveats":"Database records only; 3 papers were judged different_entity. The relation is acylation of WNT, not WNT acting on PORCN as a receptor.","key_references":[],"covers":["LR008539"]},"LR009286":{"pair":"PTH -> RAMP2","headline":"RAMP2 modulates PTH1R responses to PTH; RAMP2 is a modifier, not a direct PTH receptor.","interaction_type":"functional only","direction_and_effect":"RAMP2 enhanced PTH1R signalling responses to PTH (1-34) and other ligands, while RAMP3 attenuated or abolished them [PMID:39376604].","molecular_requirements":"Requires PTH1R co-expressed with RAMP2; a PTH1R-RAMP2 interaction was assessed by FRET [PMID:39376604].","affinity_potency":[],"species_and_systems":"PTH1R/RAMP co-expressing cells (CHO-K1) [PMID:39376604].","localisation_and_range":"Not reported in our evidence.","caveats":"No PTH-RAMP2 binding shown; effect needs PTH1R. Verified from abstract and full text.","key_references":[{"PMID":"39376604","why":"RAMP2 enhances PTH1R signalling to PTH."}],"covers":["LR009286"]},"LR004669":{"pair":"PTH2 -> PTH1R","headline":"TIP39 binds PTH1R with weak-to-moderate affinity without activating it, acting as an antagonist.","interaction_type":"conflicting","direction_and_effect":"TIP-(1-39) binds PTH1R without cAMP stimulation, and TIP(9-39) inhibits PTH and PTHrP agonists [PMID:11159842]. Another paper says TIP39 does not appreciably activate PTH1R [PMID:10854439]; GtoPdb lists an antagonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"243 +/- 52 nM","assay":"radioreceptor binding competition with 125I-rPTH","system":"LLCPK1 cells stably expressing PTH1R","cite":"PMID:11159842"},{"value":"210 +/- 64 nM","assay":"radioreceptor binding with 125I-PTHrP-(1-36)","system":"LLCPK1 cells stably expressing PTH1R","cite":"PMID:11159842"},{"value":"59 nm","assay":"binding affinity","system":"PTH1R, human","cite":"PMID:10854439"}],"species_and_systems":"Human TIP39 on pig LLCPK1 cells expressing PTH1R [PMID:11159842]; human ligand and receptor in a second study [PMID:10854439].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Affinities differ between papers (59 nM vs 210-243 nM). Both abstract only. GtoPdb lists pIC50 6.6 to 7.2 [DB:GtoPdb]. One row abstract_insufficient. Not an agonist pair despite a Ligand-Receptor class label.","key_references":[{"PMID":"10854439","why":"TIP39 binds PTH1R at 59 nM without activation."},{"PMID":"11159842","why":"TIP39 binds PTH1R weakly, antagonist behaviour."}],"covers":["LR001269","LR004669"]},"LR004678":{"pair":"PTN -> SDC1","headline":"Binding of PTN to syndecan-1 glycosaminoglycan chains by BIAcore; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"PTN bound both heparan sulfate and chondroitin sulfate chains of syndecan-1 and syndecan-4, more strongly to the CS chains of syndecan-4; the core protein of syndecan-1 also contributed to binding [PMID:15226297]. Removing CS chains lowered association and dissociation rates, suggesting a ternary complex [PMID:15226297].","molecular_requirements":"Binding depends on glycosaminoglycan chains (HS and CS), not a protein-only epitope [PMID:15226297]. Whether syndecan-1 alone transduces a PTN signal is not reported in our evidence.","affinity_potency":[],"species_and_systems":"BIAcore with syndecan ectodomains from normal murine mammary gland epithelial cells [PMID:15226297]; the dossier labels species human, which conflicts with the abstract. Both species interactions here are ortholog-inferred.","localisation_and_range":"SDC1 carries a secreted flag and a transmembrane flag [flag]; the ectodomain was used in vitro.","caveats":"Abstract only; no affinity values; binding is glycan-mediated and shared with other heparin-binding growth factors; no receptor activation shown.","key_references":[{"PMID":"15226297","why":"BIAcore comparison of PTN binding to syndecan-1 and -4 chains"}],"covers":["LR001278","LR004678"]},"LR006379":{"pair":"PTPRD -> LRRC4B","headline":"Database-asserted only: Reactome complex of LRRC4B with PTPRF, PTPRS and PTPRD; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction and complex LRRC4B:PTPRF,PTPRS,PTPRD [DB:Reactome]. Direction and effect not reported in our evidence.","molecular_requirements":"The Reactome complex pools three LAR-family receptors, so PTPRD-specific binding is not resolved in our evidence [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; both species pairs ortholog-inferred.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"No papers verified for this pair; judged rows were abstract_insufficient or different_entity. Support comes from a pooled database record only.","key_references":[],"covers":["LR003158","LR006379"]},"LR006388":{"pair":"PTPRG -> CNTN6","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN6 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN6 not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. Curator note says the pair is stored four times for one interaction; the CNTN6 evidence is the family-level statement.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003167","LR006388"]},"LR006397":{"pair":"QRFP -> NPFFR1","headline":"QRFP (26RFa) binds and activates human NPFFR1 in one full-text paper, as part of an RF-amide panel; cross-reactivity, not the cognate pair.","interaction_type":"direct binding","direction_and_effect":"RF-amide peptides including 26RFa bound NPFFR in radioligand competition and activated it in [35S]GTPgammaS and cAMP assays [PMID:23911743]. In mice, effects of the RF-amide peptides were antagonised by RF9, supporting direct NPFF receptor activation [PMID:23911743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.1-10 nM","assay":"radioligand competition on membranes, whole peptide panel (not QRFP alone)","system":"CHO cells expressing human receptor","cite":"PMID:23911743"}],"species_and_systems":"Human receptor in CHO membranes; in vivo pain tests in mice with peptides given i.c.v. [PMID:23911743].","localisation_and_range":"QRFP is flagged secreted [flag]; mouse effects were by central injection.","caveats":"The Ki range covers all peptides, not QRFP specifically. The paper reports GPR103 as selective for its cognate ligand, so NPFF receptors are secondary targets. Mouse pair is projected.","key_references":[{"PMID":"23911743","why":"Systematic RF-amide peptide binding and activation of NPFF1/NPFF2"}],"covers":["LR003177","LR006397"]},"LR004687":{"pair":"RARRES2 -> CMKLR2","headline":"Chemerin binds and activates GPR1 (CMKLR2) with nanomolar affinity; supported by binding, arrestin and Tango assays, GtoPdb and PDB structures.","interaction_type":"direct binding","direction_and_effect":"Chemerin binds GPR1 with low nanomolar affinity but no significant G-protein activation was detected, whereas beta-arrestin recruitment and internalization occurred [PMID:27716822]. GPR1 shows ligand-induced arrestin3 recruitment and internalization, and also constitutive internalization, suggesting dual signaling and scavenging roles [PMID:34241650]. In a Tango assay GPR1 responded to chemerin [PMID:18165312]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The chemerin C-terminus folds into a loop and binds aromatic residues in GPR1 extracellular loops; chemerin-9 competed only at high concentrations (100-300 nM) for chemerin binding, suggesting a stronger C-terminal contribution [PMID:34241650, PMID:27716822].","affinity_potency":[{"value":"0.21 nM","assay":"saturation binding, [125I]-chemerin (0.21 nM refers to GPR1)","system":"CHO-K1 cells expressing human GPR1","cite":"PMID:27716822"},{"value":"240 pM","assay":"Tango assay, recombinant chemerin","system":"GPR1 reporter cells","cite":"PMID:18165312"},{"value":"EC50 = 2.1 nM","assay":"arrestin3 BRET recruitment, ChemS157","system":"GPR1 cells","cite":"PMID:34241650"}],"species_and_systems":"Human receptor and human chemerin in recombinant cell systems; mouse pair is inferred from human evidence.","localisation_and_range":"Chemerin is flagged secreted [flag].","caveats":"One paper (18165312) was read by browser and its quote is unverified (spot-check pending). Two further rows are pending and one is abstract_insufficient; one paper judged a different entity. The signaling mode (arrestin-biased, scavenging) differs from CMKLR1.","key_references":[{"PMID":"27716822","why":"Binding and signaling compared across three chemerin receptors"},{"PMID":"34241650","why":"GPR1 arrestin recruitment, internalization, scavenging role"},{"PMID":"18165312","why":"Tango assay identifies chemerin as GPR1 ligand"}],"covers":["LR001288","LR004687"]},"LR004696":{"pair":"RLN1 -> RXFP1","headline":"Relaxin acts via LGR7 (RXFP1) through cAMP in one abstract-level paper; GtoPdb lists it as full agonist.","interaction_type":"functional only","direction_and_effect":"LGR7 and LGR8 can mediate relaxin action through a cAMP-dependent pathway; soluble LGR7 ligand-binding region delayed parturition in antepartum mice [PMID:11809971]. GtoPdb records a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell cAMP assays and mouse in vivo [PMID:11809971]; the human pair is not ortholog-inferred but the mouse pair is.","localisation_and_range":"RLN1 is flagged secreted and RXFP1 transmembrane [flag].","caveats":"Four papers were abstract_insufficient and one pending; the confirmed paper is functional, with no binding or affinity values in our evidence; the abstract says relaxin without specifying RLN1 [PMID:11809971].","key_references":[{"PMID":"11809971","why":"LGR7 and LGR8 mediate relaxin cAMP signalling"}],"covers":["LR001297","LR004696"]},"LR006829":{"pair":"RLN1 -> RXFP2","headline":"Relaxin acting through LGR8 (RXFP2) rests on one functional paper and a GtoPdb record.","interaction_type":"functional only","direction_and_effect":"LGR7 and LGR8 can mediate relaxin action via a cAMP-dependent pathway [PMID:11809971]. GtoPdb records a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell cAMP assays; in vivo mouse work used soluble LGR7, not RXFP2 [PMID:11809971].","localisation_and_range":"RLN1 is flagged secreted and RXFP2 transmembrane [flag].","caveats":"Five papers abstract_insufficient and one unresolvable; no binding data; the mouse in vivo result concerns LGR7, not this pair; relaxin not specified as RLN1.","key_references":[{"PMID":"11809971","why":"LGR7 and LGR8 mediate relaxin cAMP signalling"}],"covers":["LR006829","LR004697"]},"LR006469":{"pair":"SDC1 -> ADGRA2","headline":"SDC1 guides were enriched in an ADGRA2 binding-probe CRISPRa screen; one screen, no direct binding test.","interaction_type":"functional only","direction_and_effect":"SDC1 and SDC2 guides were enriched in an ADGRA2 ligand selection, consistent with known ADGRA2-glycosaminoglycan interactions; effect direction is not reported in our evidence [PMID:30477585].","molecular_requirements":"Syndecans are heparan sulfate proteoglycans, so the interaction may depend on glycosaminoglycan chains [PMID:30477585]; not tested directly.","affinity_potency":[],"species_and_systems":"Genome-wide CRISPRa in cells selected with a recombinant ADGRA2 probe; a single screen was done per adhesion GPCR bait [PMID:30477585]. Species is not reported in our evidence.","localisation_and_range":"SDC1 is flagged secreted, receptor and transmembrane [flag].","caveats":"Enrichment of guides is indirect and could reflect glycosaminoglycan binding rather than a protein-protein ligand interaction. Not validated by purified-protein binding in our evidence.","key_references":[{"PMID":"30477585","why":"CRISPRa selection enriched SDC1 and SDC2 guides with ADGRA2 probe"}],"covers":["LR003253","LR006469"]},"LR006478":{"pair":"SEMA3A -> CNTN2","headline":"Direct Sema3A-Cntn2 binding was seen in one unbiased ectodomain screen; no other evidence.","interaction_type":"direct binding","direction_and_effect":"A pairwise screen of purified ectodomains detected a direct Sema3A-Cntn2 interaction in the absence of Nrp1, suggesting Sema3A may signal directly through Cntn2 [PMID:26633812]. Effect direction is not reported in our evidence.","molecular_requirements":"Nrp1 was not needed for the binding in the screen; earlier work cited by the authors held that Cntn2 touched Sema3A only indirectly via Nrp1 [PMID:26633812].","affinity_potency":[],"species_and_systems":"Purified ectodomain screen [PMID:26633812]; the curator labelled both partners human, while the paper's context is mouse retina and the human pair is inferred.","localisation_and_range":"Sema3A is secreted [flag]; Cntn2 carries a secreted flag [flag]. Range is not reported in our evidence.","caveats":"Single study, a screen with no affinity or functional test of this pair [PMID:26633812]. No database records.","key_references":[{"PMID":"26633812","why":"Unbiased biochemical screen finding direct Sema3A-Cntn2 binding"}],"covers":["LR003262","LR006478"]},"LR007396":{"pair":"SEMA3A -> NRP1:PLXNA1","headline":"Sema3A signals through an NRP1 and PlexinA1 complex; supported by binding and mouse lymphatic evidence.","interaction_type":"functional only","direction_and_effect":"The NP-1/Plex 1 complex has higher affinity for Sema3A than NP-1 alone, and Sema3A engagement rounds up cells; dominant-negative Plex 1 blocked Sema3A-induced growth cone collapse [PMID:10520994]. Sema3A, Nrp1 and PlexinA1 are all required for lymphatic valve formation in mice [PMID:22723296].","molecular_requirements":"Both chains are needed: Plex 1 alone does not bind Sema3A [PMID:10520994]. Sema3A-AP bound lymphatic valves expressing Nrp1 and Plxna1 [PMID:22723296].","affinity_potency":[],"species_and_systems":"Binding in nonneuronal transfectants and sensory neurons, labelled human [PMID:10520994]; mouse lymphatic collectors in vivo [PMID:22723296].","localisation_and_range":"Sema3A is flagged secreted; the receptor complex is membrane-bound [flag].","caveats":"The in vivo paper's evidence sentence is general background, not this pair result; its abstract states the interaction [PMID:22723296]. No affinity is reported. Database records concern Sema3A binding Nrp-1 bound to PlexinA [DB:Reactome R-HSA-399933] [DB:BioGRID 2563623]. Two review-only rows not shown.","key_references":[{"PMID":"10520994","why":"NP-1 and Plexin 1 form complex with higher Sema3A affinity"},{"PMID":"22723296","why":"Sema3A, Nrp1 and PlexinA1 required for lymphatic valves in mice"}],"covers":["LR007396"]},"LR006487":{"pair":"SEMA3E -> PLXNB3","headline":"Sema3E binds Plexin B3-expressing cells and interacts genetically in zebrafish retinal axon guidance; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Either Sema3E or Sema3D bound to cells expressing Plexin B3 in an AP-tagged ligand binding assay in HEK293 cells [PMID:38628398]. Plexin B3 might function as a receptor for Sema3E in axon guidance [PMID:38628398].","molecular_requirements":"Neuropilin1 could be a co-receptor [PMID:38628398]; binding was stronger with Plexin B3 plus Neuropilin-1a, per the curator's note. Half-dose Plexin B3 plus Sema3E morpholinos gave up to more than 30% ipsilateral misprojections versus less than 5% each alone [PMID:38628398].","affinity_potency":[],"species_and_systems":"HEK293 binding assay and zebrafish embryos [PMID:38628398]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"SEMA3E is annotated secreted and PLXNB3 transmembrane [flag].","caveats":"One paper; no affinity value; the authors say Plexin B3 'might' be the receptor, so in vivo causation is suggestive.","key_references":[{"PMID":"38628398","why":"Plexin B3 binds Sema3E and guides zebrafish retinal axons"}],"covers":["LR003271","LR006487"]},"LR001969":{"pair":"SEMA4A -> PLXNB2","headline":"Sema4A binds Plexin-B2 in COS-7 assays and promotes excitatory synapses via Plexin-B2; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells [PMID:20043131]. Sema4A signals through Plexin-B2 to promote excitatory synapse development [PMID:29981480].","molecular_requirements":"Not reported in our evidence beyond Plexin-B2 being the excitatory-synapse mediator, distinct from Plexin-B1 [PMID:29981480].","affinity_potency":[],"species_and_systems":"COS-7 cells [PMID:20043131]; rodent hippocampus [PMID:29981480]. Curator species fields are unspecified or human.","localisation_and_range":"SEMA4A is flagged secreted and PLXNB2 transmembrane [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"Both papers read as abstracts only; binding is shared across B1, B2, B3.","key_references":[{"PMID":"20043131","why":"Sema4A binds Plexin-B2 in COS-7"},{"PMID":"29981480","why":"Sema4A-Plexin-B2 promotes excitatory synapses"}],"covers":["LR001969","LR005299"]},"LR005299":{"pair":"SEMA4A -> PLXNB2","headline":"Sema4A binds Plexin-B2 in COS-7 assays and promotes excitatory synapses via Plexin-B2; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells [PMID:20043131]. Sema4A signals through Plexin-B2 to promote excitatory synapse development [PMID:29981480].","molecular_requirements":"Not reported in our evidence beyond Plexin-B2 being the excitatory-synapse mediator, distinct from Plexin-B1 [PMID:29981480].","affinity_potency":[],"species_and_systems":"COS-7 cells [PMID:20043131]; rodent hippocampus [PMID:29981480]. Curator species fields are unspecified or human.","localisation_and_range":"SEMA4A is flagged secreted and PLXNB2 transmembrane [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"Both papers read as abstracts only; binding is shared across B1, B2, B3.","key_references":[{"PMID":"20043131","why":"Sema4A binds Plexin-B2 in COS-7"},{"PMID":"29981480","why":"Sema4A-Plexin-B2 promotes excitatory synapses"}],"covers":["LR001969","LR005299"]},"LR004759":{"pair":"SEMA4D -> PLXNB2","headline":"Plexin-B2 is only a candidate Sema4D receptor, from one abstract-level binding report.","interaction_type":"direct binding","direction_and_effect":"Binding experiments indicate plexin-B2 as another receptor candidate for Sema4D, in addition to plexin-B1; Sema4D stimulated axonal outgrowth of embryonic DRG neurones, requiring endogenous NGF and Trk activation [PMID:15330859]. Curators label it agonist.","molecular_requirements":"Not reported in our evidence for plexin-B2 itself; the DRG effect depends on NGF/Trk activity [PMID:15330859].","affinity_potency":[],"species_and_systems":"Embryonic DRG neurones; species recorded as human but not stated in the abstract. Both pairs are ortholog-inferred. IntAct has a fluorescence-activated cell sorting record [DB:IntAct]; UniProt describes a cell surface receptor role for PLXNB1 and PLXNB2 [DB:UniProt].","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag].","caveats":"The wording is hedged ('candidate') and the paper is abstract only. No affinity.","key_references":[{"PMID":"15330859","why":"Binding experiments suggest plexin-B2 as Sema4D receptor candidate"}],"covers":["LR001363","LR004759"]},"LR006496":{"pair":"SEMA5A -> PLXNA1","headline":"Mouse evidence is mixed: one abstract-only osteoclast study supports Sema5a-PlexinA1 binding, while a full-text hippocampal study argues against a functional role.","interaction_type":"conflicting","direction_and_effect":"Sema5a from osteocytes is reported to bind osteoclast Plexin A1 and activate PI3K/AKT/Myc signalling, driving bone resorption [PMID:41250977]. In hippocampal neurons, Sema5A-Fc binding was greatly reduced in Plxna1-/- neurons, but Plxna1-/- mice showed no significant spine-density increase (1.79 \u00b1 0.05 spines/\u00b5m vs WT 1.70 \u00b1 0.04), unlike Plxna2-/- (2.24 \u00b1 0.07) [PMID:25313870].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both studies used mouse cells or animals (osteoclasts; hippocampal neurons and mice). Human and mouse pairs are in the dossier; the human pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged membrane-bound (not secreted), so contact-dependent signalling is likely [flag].","caveats":"The positive paper was read as an abstract only and its assay is functional, not direct binding [PMID:41250977]. The hippocampal paper's abstract names PlexinA2, not PlexinA1, as the Sema5A receptor [PMID:25313870]. Plxna1 mRNA is virtually absent in dentate granule cells in that study [PMID:25313870].","key_references":[{"PMID":"41250977","why":"Osteocyte Sema5a reported to bind osteoclast Plexin A1 (abstract only)"},{"PMID":"25313870","why":"Sema5A-Fc binding reduced in Plxna1-/- neurons; no spine phenotype in Plxna1-/-"}],"covers":["LR003280","LR006496"]},"LR004768":{"pair":"SERPINC1 -> LRP1","headline":"Antithrombin III-thrombin complexes bind LRP1 in purified-protein assays and are internalised; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Antithrombin III-thrombin bound purified LRP, inhibited by RAP, and LRP-expressing fibroblasts internalised and degraded the complexes [PMID:8626456]. Only the sLRP4 homology region bound thrombin-antithrombin III complexes [PMID:14596620].","molecular_requirements":"Complex of ATIII with thrombin is the ligand; native or modified inhibitor alone was unable to bind [PMID:8626456]. Of the three LRP homology regions, only sLRP4 bound it [PMID:14596620].","affinity_potency":[],"species_and_systems":"Human proteins; purified LRP, mouse and HepG2 cells, rat clearance in vivo (RAP inhibited clearance of ATIII-125I-thrombin) [PMID:8626456]; recombinant sLRP fragments from Pichia pastoris [PMID:14596620]. The mouse pair is projected from human (ortholog_inferred).","localisation_and_range":"SERPINC1 is flagged secreted [flag]; cleared by endocytosis in the experiments [PMID:8626456].","caveats":"Both papers read as abstract only; free ATIII is not shown to bind. One further row is pending.","key_references":[{"PMID":"8626456","why":"Binding, uptake and in vivo clearance of ATIII-thrombin via LRP"},{"PMID":"14596620","why":"sLRP4 region specifically binds thrombin-ATIII"}],"covers":["LR001373","LR004768"]},"LR004777":{"pair":"SFTPA1 -> TLR2","headline":"SP-A binds the recombinant TLR2 extracellular domain and inhibits peptidoglycan-induced signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Inhibitory: SP-A reduced sTLR2 binding to peptidoglycan and attenuated PGN-induced NF-kappaB activity in TLR2-transfected HEK293 cells and TNF-alpha secretion by U937 cells and rat alveolar macrophages [PMID:11724772].","molecular_requirements":"Reactome lists binding to a TLR2:TLR1 complex [DB:Reactome]; subunit requirements are not tested in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant soluble TLR2 extracellular domain, HEK293 transfectants, U937 cells and rat alveolar macrophages; mouse pair is ortholog-inferred [PMID:11724772].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; the paper refers to SP-A generally. Peptidoglycan itself is not an SP-A ligand per the abstract.","key_references":[{"PMID":"11724772","why":"Direct SP-A binding to sTLR2 and inhibition of PGN responses"}],"covers":["LR001382","LR004777"]},"LR004786":{"pair":"SHH -> PTCH2","headline":"SHH-PTCH2 binding is shown in one abstract showing similar affinity to PTCH1; direct evidence is thin.","interaction_type":"direct binding","direction_and_effect":"PTCH2 binds all hedgehog family members with similar affinity to PTCH and can form a complex with SMO [PMID:9811851]. UniProt: SHH acts by binding to patched receptor PTCH1 or PTCH2 [DB:UniProt].","molecular_requirements":"No co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PTCH2 gene isolated; biochemical analysis, system not detailed [PMID:9811851]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag].","caveats":"Abstract-only; affinity is not quantified in the dossier. The paper suggests PTCH2 may mediate Dhh activity in vivo [PMID:9811851].","key_references":[{"PMID":"9811851","why":"PTCH2 binds hedgehog proteins with similar affinity"}],"covers":["LR001391","LR004786"]},"LR001978":{"pair":"SIRPA -> CD47","headline":"Well-supported SIRPA-CD47 interaction: one functional adhesion paper plus structures, IntAct, Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"CD47 was identified as the extracellular ligand for human SIRP, and SIRPalpha1/alpha2 extracellular domains supported cell adhesion that an anti-CD47 antibody (CC2C6) inhibited [PMID:10572074]. UniProt describes CD47 as receptor for SIRPA, preventing maturation of immature dendritic cells [DB:UniProt].","molecular_requirements":"SIRPalpha1 and SIRPalpha2 competed for the same cell binding site [PMID:10572074]. Further requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant SIRPalpha-Fc fusion proteins and human cell lines [PMID:10572074]. Mouse row is not ortholog-inferred in the dossier interaction list, but no mouse experiment is shown; the human row is ortholog-inferred.","localisation_and_range":"Both are annotated transmembrane [flag], so contact-dependent signalling.","caveats":"The paper was read as abstract only and shows binding indirectly through adhesion and antibody blocking. Structural records (PDB 2JJS, 2JJT, 4CMM, 7YGG) and IntAct ELISA/solid phase assays support direct binding [DB:PDB 2JJS] [DB:IntAct]. Reactome records the SIRPA:CD47 complex [DB:Reactome].","key_references":[{"PMID":"10572074","why":"CD47 identified as SIRP ligand; adhesion blocked by anti-CD47 mAb"}],"covers":["LR001978","LR005308"]},"LR001987":{"pair":"SLIT3 -> ROBO4","headline":"SLIT3 promotes endothelial motility via Robo4 in mouse; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Slit3 stimulates endothelial proliferation, motility and chemotaxis via interaction with Robo4, and promotes vascular network formation with specific activity comparable with VEGF; Slit3 knockout mice show disrupted angiogenesis [PMID:19741192].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse endothelial cells, ex vivo sprouting and in vivo; mouse knockout [PMID:19741192].","localisation_and_range":"Secreted by endothelial and vascular smooth muscle cells, acting in paracrine and autocrine ways [PMID:19741192].","caveats":"Single abstract-only paper; physical binding not reported in our evidence. No affinity.","key_references":[{"PMID":"19741192","why":"Slit3 angiogenesis via Robo4"}],"covers":["LR001987","LR005316"]},"LR001996":{"pair":"SLPI -> PLSCR1","headline":"SLPI binds phospholipid scramblase 1 directly in several in vitro assays; it competes with CD4 for the PLSCR1 cytoplasmic domain.","interaction_type":"direct binding","direction_and_effect":"SLPI is the ligand and acts as an antagonist: it disrupts the PLSCR1-CD4 association and the authors propose this explains inhibition of HIV-1 infection [PMID:19333378].","molecular_requirements":"The mature SLPI form (residues 26-132) was needed; the full-length form with signal peptide did not interact in yeast two-hybrid. Each WAP motif alone recruited PLSCR1 more weakly than mature SLPI. SLPI binds PLSCR1 residues 155-233 of the cytoplasmic domain, the same region CD4 uses [PMID:19333378].","affinity_potency":[],"species_and_systems":"Human proteins; yeast two-hybrid, ELISA with GST-PLSCR1, pull-downs from transfected cells, Jurkat T cells and primary T lymphocytes [PMID:19333378]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted [flag]. PLSCR1 is a type II membrane protein whose SLPI-binding region is cytoplasmic; the authors state secreted SLPI would need to cross the plasma membrane to bind it [PMID:19333378].","caveats":"The binding site is intracellular, so the route by which secreted SLPI reaches it is unresolved in our evidence. The curator read the paper at abstract level only. A weak pull-down interaction was also seen with elafin [PMID:19333378]. BioGRID lists affinity-capture-Western and two-hybrid records [DB:BioGRID].","key_references":[{"PMID":"19333378","why":"Shows SLPI binds PLSCR1 directly and displaces CD4"}],"covers":["LR001996","LR005325"]},"LR008566":{"pair":"SORBS1 -> INSR","headline":"SORBS1 and the insulin receptor associate by co-IP in databases; SORBS1 is not a ligand, so this is a protein-protein interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states the insulin receptor interacts with SORBS1 but dissociates from it after insulin stimulation [DB:UniProt]. Direction as ligand to receptor is not supported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID records an affinity capture-Western and IntAct a co-immunoprecipitation (physical association) from the same paper, PMID 11374898; species not reported in our evidence [DB:BioGRID][DB:IntAct].","localisation_and_range":"SORBS1 carries no secreted flag in our record and INSR is flagged as a transmembrane receptor [flag]. The association is an intracellular adaptor interaction by inference only.","caveats":"No papers were judged confirmed; the single judged row was 'different_entity'. The support is database records only. SORBS1 is not a secreted ligand, so this does not fit ligand-receptor inference.","key_references":[],"covers":["LR008566"]},"LR004795":{"pair":"SOST -> LRP6","headline":"Secreted sclerostin binds LRP6 (and LRP5) and antagonises canonical Wnt signalling; two abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Sclerostin antagonises canonical Wnt signalling and bound LRP5 as well as LRP6 [PMID:15778503]. SOST binds the LRP5/6 extracellular domain and disrupts Wnt-induced Frizzled-LRP complex formation [PMID:15908424]. Effect: antagonist/inhibitor.","molecular_requirements":"The binding site was mapped on LRP5 (first two YWTD-EGF repeat domains); canonical Wnt did not appear to compete with sclerostin for LRP5 binding [PMID:15778503]. Whether LRP6 uses the same domains is not reported in our evidence. LRP6 is a single-chain co-receptor [flag].","affinity_potency":[],"species_and_systems":"Human A293T and mouse MC3T3 cells [PMID:15778503]; Xenopus embryos and mammalian cells [PMID:15908424]. Mouse pair is ortholog-inferred. Database records: BioGRID Affinity Capture-Western [DB:BioGRID], IntAct pull down and bio-layer interferometry [DB:IntAct], structures [DB:PDB 3SOV] [DB:PDB 6L6R], Reactome SOST:LRP5/6 complex [DB:Reactome].","localisation_and_range":"SOST is flagged secreted and LRP6 as a transmembrane receptor [flag]; acts on cell-surface receptors.","caveats":"Both papers were read as abstracts only. Binding to LRP6 is stated alongside LRP5; LRP6-specific details are limited. No affinity values in our evidence.","key_references":[{"PMID":"15778503","why":"Sclerostin binds LRP5 and LRP6, antagonises Wnt"},{"PMID":"15908424","why":"SOST binds LRP5/6 ectodomain, disrupts Frizzled-LRP complex"}],"covers":["LR001400","LR004795"]},"LR006559":{"pair":"TCN2 -> CD320","headline":"Well-supported: crystal structure and high-affinity binding of holo-transcobalamin to CD320.","interaction_type":"direct binding","direction_and_effect":"CD320 captures transcobalamin (TC) from plasma for cellular vitamin B12 uptake [PMID:27411955]. The crystal structure of human holo-TC with the CD320 extracellular domain shows the interaction chemistry [PMID:27411955]. Reactome lists the TCN2:RCbl:CD320 complex at the plasma membrane [DB:Reactome].","molecular_requirements":"Both CD320 LDLR-A1 and LDLR-A2 interact with the \u03b1 domain of TC; each single domain formed a complex with TC [PMID:27411955]. The complex was 1:1 and was purified with excess cyanocobalamin, i.e. cobalamin-bound TC [PMID:27411955]. Haptocorrin binding is lacking [PMID:27411955].","affinity_potency":[{"value":"KD ~1.5 nM","assay":"solid-phase binding assay","system":"recombinant human TC and CD320","cite":"PMID:27411955"}],"species_and_systems":"Recombinant human proteins [PMID:27411955]; structures PDB 4ZRP and others [DB:PDB 4ZRP]. Mouse pair is projected by orthology.","localisation_and_range":"TCN2 is annotated secreted and CD320 as a transmembrane receptor [flag]; TC is captured from plasma [PMID:27411955].","caveats":"Abstract plus excerpts only; in vivo function not covered by our evidence. IntAct also lists the interaction [DB:IntAct].","key_references":[{"PMID":"27411955","why":"Crystal structure and affinity of TC-CD320"}],"covers":["LR003356","LR006559"]},"LR006568":{"pair":"TGFB1 -> ACVR1","headline":"Functional evidence that ACVR1 is required downstream of TGFB1 for SMAD1/5 phosphorylation; direct ligand binding not shown.","interaction_type":"functional only","direction_and_effect":"TGF-beta-induced SMAD1/5 phosphorylation requires TGFBR1 and ACVR1; TGFBR1 phosphorylates and activates ACVR1, which phosphorylates SMAD1/5 [PMID:29376829].","molecular_requirements":"Receptors involved are deduced to be TGFBR1, a canonical BMP type I receptor (ACVR1 and/or BMPR1A) and TGFBR2 [PMID:29376829]. In vitro, SMAD1 is efficiently phosphorylated by ACVR1 but poorly by TGFBR1 [PMID:29376829].","affinity_potency":[],"species_and_systems":"Human cells in the curated label; NMuMG cells are also mentioned [PMID:29376829]. Mouse pair is ortholog-inferred.","localisation_and_range":"TGFB1 is annotated secreted and not transmembrane [flag].","caveats":"ACVR1 acts as a type I receptor kinase in a TGF-beta receptor complex; TGFB1 binding to ACVR1 itself is not reported in our evidence. Abstract plus excerpts only.","key_references":[{"PMID":"29376829","why":"TGFBR1 activates ACVR1 for SMAD1/5 signalling"}],"covers":["LR003367","LR006568"]},"LR008278":{"pair":"TGFB1 -> ACVR1:TGFBR1","headline":"Functional evidence only: TGF-beta signalling to SMAD1/5 needs both TGFBR1 and ACVR1; no direct ligand binding to this pairing shown.","interaction_type":"functional only","direction_and_effect":"TGFBR1 phosphorylates and activates ACVR1, which phosphorylates SMAD1/5; effect labelled agonist [PMID:29376829]. GtoPdb lists TGFB1-TGFBR1 as agonist [DB:GtoPdb].","molecular_requirements":"Both type I receptor classes (TGFBR1 and ACVR1) are required for TGF-beta-induced SMAD1/5 phosphorylation; TGFBR2 is deduced to be involved as well [PMID:29376829].","affinity_potency":[],"species_and_systems":"Human cells and in vitro kinase assays; NMuMG cells also used [PMID:29376829].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptors act at the cell membrane; Reactome places TGFB1:TGFBR2:TGFBR1 at the plasma membrane [DB:Reactome R-HSA-170840].","caveats":"The paper shows receptor cooperation and kinase transactivation, not binding of TGF-beta to ACVR1. The abstract-level curation was supplemented by full text excerpts. Direct ligand binding databases concern TGFBR1 or TGFBR2 alone [DB:BioGRID].","key_references":[{"PMID":"29376829","why":"TGFBR1 activates ACVR1 to drive SMAD1/5 phosphorylation by TGF-beta"}],"covers":["LR008278"]},"LR006577":{"pair":"TGFBI -> STAB1","headline":"One paper reports TGFBI as a circulating ligand of STAB1 by pulldown and endocytosis; single-paper, abstract-level support.","interaction_type":"direct binding","direction_and_effect":"TGFBi was independently confirmed as a novel circulating ligand of Stab1/2 [PMID:36325910]. Clearance by the stabilins suppresses monocyte activation in this paper's model [PMID:36325910].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand binding used GST-pulldown and endocytosis assays; the atherosclerosis work used mice [PMID:36325910]. Which species the binding assays used is not stated in the abstract.","localisation_and_range":"TGFBI is flagged secreted [flag]; the paper describes circulating plasma ligands cleared by liver sinusoidal endothelial cells [PMID:36325910].","caveats":"Only one paper, read as abstract only; the abstract does not detail the binding result for this specific pair. Stab1 and Stab2 are paralogs, with the same claim made for both.","key_references":[{"PMID":"36325910","why":"Stab1/2 scavenger receptor ligands including TGFBi"}],"covers":["LR003376","LR006577"]},"LR004849":{"pair":"TGM2 -> ADGRG1","headline":"TGM2 (tissue transglutaminase) binds GPR56 (ADGRG1) in a melanoma study and is listed in UniProt; effect reported as tumour-suppressive.","interaction_type":"direct binding","direction_and_effect":"GPR56 binds specifically to TG2; GPR56 overexpression suppresses melanoma tumour growth and metastasis [PMID:16757564]. The curator labels this antagonist-like.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma cell lines [PMID:16757564]. The human pair is ortholog-inferred, as is the mouse pair.","localisation_and_range":"TG2 is a stromal component, and the abstract suggests GPR56 acts via the tumour microenvironment in vivo [PMID:16757564]. TGM2 is flagged secreted [flag].","caveats":"One paper, abstract only. No binding affinity is reported. UniProt cites the same paper and two others for the interaction [DB:UniProt]. The ADGRG1 entity is flagged secreted as well as transmembrane [flag].","key_references":[{"PMID":"16757564","why":"GPR56 binds TG2 and suppresses melanoma growth"}],"covers":["LR001454","LR004849"]},"LR004858":{"pair":"THBS1 -> CD47","headline":"Well-supported direct THBS1-CD47 interaction, with binding and functional evidence from several papers.","interaction_type":"direct binding","direction_and_effect":"THBS1 is described as a receptor ligand for CD47: cells expressing CD47 bind THBS1 and its C-terminal cell-binding domain, and CD47-negative cells do not [PMID:8550562]. Effects are mixed by context: agonist-like platelet activation via the CD47 peptide 4N1K [PMID:9169439], but inhibition of NO-stimulated cGMP signalling in vascular smooth muscle cells [PMID:19004835] and of T cell antigen receptor signalling and proliferation [PMID:11980922]. Reported in GtoPdb as binding [DB:GtoPdb] and in UniProt [DB:UniProt].","molecular_requirements":"The THBS1 C-terminal signature/cell-binding domain carries the CD47 site [PMID:19004835][PMID:8550562]. CD47 associates with alphaVbeta3 [PMID:8550562] and with alphaIIbbeta3 and alpha2beta1 in platelets [PMID:9169439][PMID:10397731]. In T cells CD47 was not required for some THBS1 responses and contributed indirectly to others [PMID:11980922].","affinity_potency":[],"species_and_systems":"Human cells and recombinant domains in most papers; platelet aggregation dependence on CD47 was shown with platelets from CD47-null mice [PMID:10397731]. Human-mouse pair; no ortholog inference flagged.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"Four of the five papers were read as abstracts only. The platelet and T cell results show that effect direction depends on cell type and partner integrin. Some T cell responses to THBS1 used fragments lacking the CD47 site, so CD47 acted indirectly there [PMID:11980922]. No affinity values are reported in our evidence.","key_references":[{"PMID":"8550562","why":"Affinity labelling and antibody blocking identify CD47 as the THBS1 cell-binding-domain receptor"},{"PMID":"19004835","why":"THBS1 signature domain competes with SIRPalpha for CD47 and is more potent than TSP-2/-4"},{"PMID":"11980922","why":"CD47 drives the inhibitory T cell arm of THBS1 signalling (full text)"}],"covers":["LR001463","LR004858"]},"LR004867":{"pair":"THBS1 -> SDC4","headline":"Syndecan-4 is proposed as a receptor for the THBS1 N-terminal domain, mediating pro-angiogenic tubulogenesis; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"An anti-syndecan-4 monoclonal antibody blocks TSP18-induced tubulogenesis, and TSP18 and derived peptides activate PKC-dependent Akt-PKB signalling [PMID:17879962]. Agonist-like pro-angiogenic effect.","molecular_requirements":"The N-terminal fragment (residues 1-174, TSP18) and two sequences, TSP Hep I and II, retain activity and compete with fibronectin Hep II for syndecan-4 binding on endothelial cells [PMID:17879962].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells with recombinant human THBS1 fragments [PMID:17879962].","localisation_and_range":"THBS1 flagged secreted [flag]; fragments used as coated substrates [PMID:17879962].","caveats":"Abstract only; the fragment, not full-length THBS1, was tested; binding was inferred from antibody inhibition and competition with endothelial cell extracts. One other row abstract_insufficient. No database records.","key_references":[{"PMID":"17879962","why":"Syndecan-4 as receptor for THBS1 N-terminal domain"}],"covers":["LR001472","LR004867"]},"LR006586":{"pair":"THBS1 -> VLDLR","headline":"THBS1 is reported as a Reelin-independent ligand of VLDLR and ApoER2 that induces Dab1 phosphorylation; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"THBS-1 binds VLDLR and ApoER2 and induces Dab1 phosphorylation, but unlike Reelin it does not induce Dab1 degradation or Akt phosphorylation and instead stabilises neuronal precursor chains [PMID:18946489]. Agonist label from curation.","molecular_requirements":"ApoER2 is also a receptor for THBS-1 [PMID:18946489]; whether VLDLR alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Subventricular zone and rostral migratory stream explants and THBS-1-deficient mice; curated species human, mouse pair ortholog-inferred [PMID:18946489].","localisation_and_range":"THBS1 is flagged secreted [flag]; present throughout the SVZ and rostral migratory stream [PMID:18946489].","caveats":"Abstract only; no affinity reported. Both species rows are ortholog-inferred, and the experiments appear to use mouse tissue.","key_references":[{"PMID":"18946489","why":"THBS-1 as ligand for ApoER2 and VLDLR"}],"covers":["LR003385","LR006586"]},"LR006595":{"pair":"THY1 -> ITGAV","headline":"THY1 binds alphavbeta3 integrin by SPR and single-molecule force assays; soluble Thy-1 antagonises alphav-driven fibrosis.","interaction_type":"direct binding","direction_and_effect":"Thy-1/alphavbeta3 drives neuron-astrocyte signalling [PMID:29212879][PMID:18346467]. Soluble Thy-1-Fc acted as antagonist: it reversed TGF-beta1-induced myofibroblast differentiation and promoted fibrosis resolution in mice, requiring its integrin-binding RGD motif [PMID:31672942].","molecular_requirements":"Both alphav and beta3 are required for neuron-astrocyte association; wild-type (RLD) but not RLE Thy-1 binds alphavbeta3 by SPR, promoted by divalent cations [PMID:18346467].","affinity_potency":[],"species_and_systems":"Optical tweezers with Thy-1-Fc and nonpurified alphavbeta3-Fc, slip-bond behaviour [PMID:29212879]; DI TNC1 astrocyte line, species not specified in the dossier [PMID:18346467]; bleomycin mouse models and cultured fibroblasts [PMID:31672942].","localisation_and_range":"Membrane-bound neuronal Thy-1 contacting astrocyte integrin (trans); soluble Thy-1-Fc used in the fibrosis study [PMID:18346467][PMID:31672942].","caveats":"All three papers abstract only. The fibrosis paper shows targeting of alphav by Thy-1-Fc, not the beta3 chain specifically. No numeric affinity reported.","key_references":[{"PMID":"18346467","why":"SPR binding of Thy-1 RLD to alphavbeta3"},{"PMID":"29212879","why":"Force spectroscopy, slip-bond"},{"PMID":"31672942","why":"Soluble Thy-1 antagonises alphav in fibrosis"}],"covers":["LR003394","LR006595"]},"LR008197":{"pair":"TIMP1 -> CD63:ITGB1","headline":"TIMP-1 signals through a CD63/integrin beta1 complex in MCF10A cells; co-IP and knockdown evidence from one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"TIMP-1, CD63 and integrin beta1 co-immunoprecipitated and colocalised on the surface of MCF10A cells; TIMP-1 level correlated with active integrin beta1; CD63 knockdown reduced TIMP-1 binding and reversed integrin beta1 activation, survival signalling and apoptosis inhibition [PMID:16917503].","molecular_requirements":"Complex of CD63 and ITGB1 [flag]. CD63 is required for TIMP-1 surface binding and integrin activation per knockdown [PMID:16917503]; UniProt says CD63 interacts with TIMP1 and ITGB1 and recruits TIMP1 to ITGB1 [DB:UniProt]. Whether ITGB1 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human MCF10A breast epithelial cells, 2D and 3D Matrigel [PMID:16917503].","localisation_and_range":"TIMP1 is flagged secreted; complex members flagged as receptors [flag].","caveats":"Single primary paper, abstract only. Binding data are co-IP and colocalisation, not a measured complex affinity. Database records are pairwise TIMP1-CD63 [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"16917503","why":"Co-IP and knockdown linking TIMP-1, CD63 and integrin beta1"}],"covers":["LR008197"]},"LR004876":{"pair":"TIMP3 -> KDR","headline":"TIMP-3 blocks VEGF binding to KDR in vitro, an antagonist action; supported by a full-text paper and UniProt.","interaction_type":"functional only","direction_and_effect":"TIMP3 inhibited VEGF-mediated angiogenesis by blocking VEGF binding to VEGF receptor-2 and reducing downstream signalling, independent of MMP inhibition; the authors conclude it specifically and competitively inhibits VEGF binding to KDR [PMID:12652295]. UniProt says it interacts directly with KDR to prevent VEGFA binding [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Specific cell or species not reported in our evidence for the curated row [PMID:12652295]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 flagged secreted; KDR flagged transmembrane receptor [flag].","caveats":"Curated as functional rather than direct binding; the competitive-inhibition claim is the authors' conclusion. Only one paper is in the dossier. TIMP3 here is an antagonist of VEGF binding, not an activating ligand.","key_references":[{"PMID":"12652295","why":"TIMP3 blocks VEGF binding to KDR"}],"covers":["LR001481","LR004876"]},"LR004885":{"pair":"TNC -> PTPRB","headline":"The FNIII domain of RPTPbeta binds tenascin C in human glial tumor cells; abstract-only, nomenclature caveat.","interaction_type":"direct binding","direction_and_effect":"Affinity purification with the RPTPbeta FNIII domain isolated a 240 kDa protein identified as tenascin C; a soluble FNIII fragment abolished adhesion and spreading of RPTPbeta-expressing astrocytoma cells on TNC [PMID:11313993].","molecular_requirements":"Binding maps to alternatively spliced FNIII repeats A1,2,4 of tenascin C [PMID:11313993].","affinity_potency":[],"species_and_systems":"Human glioblastoma U118MG cells (source of tenascin C), SF763T astrocytoma cells and COS cells [PMID:11313993].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only. Curator notes 'RPTPbeta' is ambiguous between PTPRB and PTPRZ1.","key_references":[{"PMID":"11313993","why":"RPTPbeta FNIII domain binds tenascin C"}],"covers":["LR001490","LR004885"]},"LR004894":{"pair":"TNFSF13 -> TNFRSF17","headline":"APRIL binds BCMA with high affinity; well supported by several binding papers plus an AML functional study.","interaction_type":"direct binding","direction_and_effect":"APRIL binds BCMA and TACI and competes with TALL-I for receptor binding; soluble BCMA and TACI block APRIL-stimulated B-cell proliferation [PMID:10973284]. In AML cells, TNFSF13 drove NF-kappaB-dependent proliferation, and a TNFRSF17 blocking antibody hindered proliferation and NF-kappaB activation in human Mono-Mac-6 cells [PMID:30819903].","molecular_requirements":"BCMA binds APRIL via the canonical TNF fold, while HSPG binds a separate lysine motif; the two bind simultaneously [PMID:15846369]. HSPG binding is reported to help TNFSF13 oligomerise and bind TNFRSF13B or TNFRSF17 [PMID:30819903].","affinity_potency":[{"value":"IC50 = 11 +/- 3 nm","assay":"binding of monomeric BCMA to APRIL","system":"human proteins","cite":"PMID:14764606"}],"species_and_systems":"Human proteins for binding [PMID:14764606][PMID:10973284]; murine MLL-AF9 leukemia cells and mouse knockouts plus human myeloid lines in the AML study [PMID:30819903]; BCMA-Fc blocked antibody production in mice [PMID:10973284].","localisation_and_range":"APRIL flagged secreted, BCMA transmembrane [flag].","caveats":"Binding papers are abstract-only; AML paper has full text. Neither BCMA nor TACI is essential for APRIL's tumor-promoting effects [PMID:15846369]. APRIL is the preferred ligand versus BAFF (BAFF IC50 = 8 +/- 5 microm) [PMID:14764606].","key_references":[{"PMID":"14764606","why":"APRIL-BCMA affinity and specificity residues"},{"PMID":"10973284","why":"APRIL binds BCMA/TACI, competes with TALL-I"},{"PMID":"30819903","why":"Functional BCMA-dependent signalling in AML"}],"covers":["LR001504","LR004894"]},"LR004939":{"pair":"VEGFC -> NRP2","headline":"VEGF-C binds NRP2 through a processing-gated C-terminal motif, with structure and cell data showing a co-receptor role.","interaction_type":"direct binding","direction_and_effect":"Processed VEGF-C C-terminus bound NRP2 b1b2 and a crystal structure shows a cryptic motif released by proteolysis engages the b1 domain [PMID:25752543]. VEGF-C and VEGF-D interact with NP2 [PMID:16816121]; VEGF-A and VEGF-C induce NRP2 interaction with VEGFR-2, enhancing VEGFR-2 phosphorylation and VEGF-C-induced survival and migration [PMID:16621967].","molecular_requirements":"Binding needs C-terminal proteolytic maturation; unprocessed peptide showed no effect [PMID:25752543]. VEGF-C binds NP2 in a heparin-independent manner and NP2 coprecipitates with VEGFR-3, forming part of a signalling complex [PMID:16816121]. NRP2 acts as a co-receptor with VEGFR-2 [PMID:16621967].","affinity_potency":[{"value":"Kd = 199 \u03bcM \u00b1 71 \u03bcM","assay":"saturable binding of processed VEGF-C C-terminal peptide to Nrp2 b1b2","system":"purified peptide and Nrp2 domains","cite":"PMID:25752543"}],"species_and_systems":"Human ligand and receptor throughout; recombinant domains and cultured endothelial cells [PMID:25752543] [PMID:16816121] [PMID:16621967]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]. A secreted splice form s9Nrp2 is described as a decoy inhibitor in the structural paper's notes [PMID:25752543].","caveats":"The 199 \u03bcM Kd is for a short peptide and therefore weak; full-length affinity is not reported. A PDB structure exists [DB:PDB 6TJT]. One pending row not shown. Papers read as abstracts, with full-text excerpts for the structural paper.","key_references":[{"PMID":"25752543","why":"structure of processed VEGF-C bound to Nrp2 b1"},{"PMID":"16816121","why":"VEGF-C binding to NP2 and VEGFR-3 complex"},{"PMID":"16621967","why":"NRP2 co-receptor role for VEGF-C"}],"covers":["LR001550","LR004939"]},"LR006649":{"pair":"VTN -> C1QBP","headline":"Direct binding of the heparin-binding multimeric form of vitronectin to gC1qR (C1QBP), Kd about 20 nM, from one abstract-level human study.","interaction_type":"direct binding","direction_and_effect":"Multimeric vitronectin bound gC1qR in a purified system; binding was inhibited by heparin but not chondroitin sulfate [PMID:8900153]. Signalling effect is not reported in our evidence.","molecular_requirements":"Only the heparin-binding multimeric form of vitronectin bound, not the plasma form. A truncated gC1qR lacking the N-terminal 22 residues hardly bound vitronectin but still bound C1q; C1q and vitronectin do not compete [PMID:8900153].","affinity_potency":[{"value":"Kd 20 nM","assay":"saturable binding, purified system","system":"Raji-cell-isolated and recombinant gC1qR with vitronectin","cite":"PMID:8900153"}],"species_and_systems":"Raji cell membrane-derived and recombinant bacterially expressed gC1qR; recombinant/purified in vitro system [PMID:8900153]. IntAct lists an ELISA record [DB:IntAct P04004-Q07021].","localisation_and_range":"Vitronectin is flagged secreted; C1QBP is a receptor by flag but not transmembrane [flag].","caveats":"Single paper, abstract only. Vitronectin was found complexed with thrombin-antithrombin, which alone did not bind gC1qR [PMID:8900153]. Kd is approximate.","key_references":[{"PMID":"8900153","why":"Direct vitronectin-gC1qR binding with Kd about 20 nM"}],"covers":["LR003448","LR006649"]},"LR004948":{"pair":"VTN -> ITGA8","headline":"Human integrin alpha8beta1 is reported as a vitronectin receptor; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 localised to focal contacts on vitronectin, mediated adhesion of alpha8-transfected 293 cells to vitronectin, and bound vitronectin-Sepharose, from which it was eluted by the RGD peptide GRGDSP [PMID:7559467].","molecular_requirements":"The functional receptor is the alpha8beta1 heterodimer; alpha8 is tested together with beta1, not alone [PMID:7559467]. Binding is RGD-dependent and distinct from alpha5- and alphaV-containing integrins (stated in the abstract).","affinity_potency":[],"species_and_systems":"Human 293 cells transfected with alpha8 cDNA and cell lines plated on matrix; mouse pair is ortholog-inferred [PMID:7559467].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Abstract only, and the stored evidence sentence is truncated. No affinity reported. The curator note says rows stored per subunit should be folded into the ITGA8:ITGB1 complex.","key_references":[{"PMID":"7559467","why":"alpha8beta1 adhesion to and affinity chromatography on vitronectin"}],"covers":["LR001559","LR004948"]},"LR004957":{"pair":"VWF -> GP1BA","headline":"GPIbalpha is the platelet VWF receptor, supported by a co-crystal structure with the VWF A1 domain and many database records.","interaction_type":"direct binding","direction_and_effect":"Structures of the GpIbalpha N-terminal domain and its complex with VWF domain A1 show GpIbalpha wrapping around A1 with two contact areas [PMID:12183630]. An antibody to GPIb alpha blocked VWF binding to platelets, and there was no binding to Bernard-Soulier platelets [PMID:6336654]. Curated effect is stimulatory.","molecular_requirements":"The interaction uses the VWF A1 domain and the GPIbalpha amino-terminal domain [PMID:12183630]. Whether other complex subunits are needed is not reported in our evidence; Reactome lists GPIb:IX:V binding VWF multimer:collagen [DB:Reactome].","affinity_potency":[{"value":"Kd~1.5x10^-8 M","assay":"radiolabelled F(ab')2 antibody binding to GPIb on platelets (antibody, not VWF, affinity)","system":"human platelets","cite":"PMID:6336654"}],"species_and_systems":"Human proteins, crystallography and platelets [PMID:12183630] [PMID:6336654]. Structures are in [DB:PDB 1M10] and [DB:PDB 1SQ0]; BioGRID and IntAct record reconstituted complex, far Western and co-crystal evidence [DB:BioGRID] [DB:IntAct]. Mouse pair is ortholog-inferred.","localisation_and_range":"VWF is flagged secreted; GP1BA is flagged transmembrane and a receptor [flag]. Platelet rolling at vascular damage [PMID:12183630].","caveats":"Both papers are abstract-only. The interaction is transient and shear-dependent per the curators, so a static affinity may mislead. The only affinity here is for an antibody, not VWF.","key_references":[{"PMID":"12183630","why":"co-crystal structure of GpIbalpha with VWF A1"},{"PMID":"6336654","why":"antibody blocks VWF binding to platelet GPIb alpha"}],"covers":["LR001568","LR004957"]},"LR006658":{"pair":"VWF -> SCARA5","headline":"SCARA5 binds and internalises VWF; one abstract-only paper with some full-text support.","interaction_type":"direct binding","direction_and_effect":"VWF and the VWF-FVIII complex bound human recombinant SCARA5 in a dose- and calcium-dependent manner, and SCARA5-expressing HEK293T cells bound and internalised them into early endosomes [PMID:31126000]. SCARA5 deficiency had a modest influence on human VWF half-life in mice.","molecular_requirements":"Calcium is needed for binding [PMID:31126000]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant SCARA5 and HEK293T cells, mouse model, human tissue [PMID:31126000]. Mouse pair is ortholog-inferred.","localisation_and_range":"SCARA5 is a transmembrane type II protein [flag]; it is expressed by kidney podocytes and splenic littoral cells, where VWF colocalises [PMID:31126000].","caveats":"Modest in vivo effect suggests a supplementary role. No affinity reported.","key_references":[{"PMID":"31126000","why":"SCARA5 binds and internalises VWF"}],"covers":["LR003458","LR006658"]},"LR004966":{"pair":"WNT1 -> LRP5","headline":"WNT1 binds the LRP5 co-receptor in human-construct experiments; one verified paper.","interaction_type":"direct binding","direction_and_effect":"LRP-5 can bind Wnt-1, like LRP-6; LRP-5 alone did not change LEF-1 reporter activity but enhanced the effect of Wnt-1 [PMID:11336703].","molecular_requirements":"LRP-5 is described as a Wnt coreceptor acting with Frizzled; a Frizzled requirement was not tested in the excerpts [PMID:11336703].","affinity_potency":[],"species_and_systems":"Human LRP-5 constructs in fibroblast cells, co-culture with Wnt-1 transfected cells, full text [PMID:11336703]. The mouse pair is projected from human.","localisation_and_range":"Wnt-1 acted on LRP-5 as a secreted protein in a paracrine coculture [PMID:11336703]; WNT1 is flagged as secreted [flag].","caveats":"Seven other papers were abstract_insufficient. The binding sentence is brief and the paper's focus is Axin binding to the intracellular domain.","key_references":[{"PMID":"11336703","why":"LRP-5 binds Wnt-1; synergy with Wnt"}],"covers":["LR001577","LR004966"]},"LR010996":{"pair":"WNT10B -> FZD3:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR010996"]},"LR006667":{"pair":"WNT10B -> FZD5","headline":"Functional synergy in Xenopus embryos suggests WNT10B signals through mouse Fzd5; abstract only, no binding data.","interaction_type":"functional only","direction_and_effect":"Mouse Fzd5 specifically synergized with Wnt2, Wnt5a and Wnt10b in ectopic axis induction assays in Xenopus embryos; the authors call Wnt5a and Wnt10b likely physiological ligands because they co-localized with Fzd5 in the yolk sac [PMID:11092808].","molecular_requirements":"Not reported in our evidence; LRP co-receptor requirement is not tested in the abstract.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor expressed in Xenopus embryos, plus Fzd5 knockout mice [PMID:11092808]. The pair is human with ortholog-inferred entries for human and mouse.","localisation_and_range":"Ligand flagged secreted [flag]; co-localisation in yolk sac is reported by the authors, hedged [PMID:11092808].","caveats":"Heterologous synergy assay, not binding. The physiological-ligand claim is hedged and based on co-localisation. Abstract only.","key_references":[{"PMID":"11092808","why":"Fzd5 synergizes with Wnt10b in Xenopus axis induction; Fzd5 knockout phenotype"}],"covers":["LR003467","LR006667"]},"LR007486":{"pair":"WNT11 -> FZD1:LRP6","headline":"WNT11 to a FZD1:LRP6 complex is database-asserted only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a generic WNT:FZD complex at the plasma membrane [DB:Reactome]; no experiment on the FZD1:LRP6 combination is available.","molecular_requirements":"The receptor is annotated as a FZD1 plus LRP6 complex [flag]; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted; LRP6 is flagged transmembrane [flag].","caveats":"One review-only and five abstract_insufficient rows; nothing verified. The Reactome entry does not distinguish this pairing from other WNT:FZD complexes [DB:Reactome].","key_references":[],"covers":["LR007486"]},"LR006676":{"pair":"WNT11 -> ROR2","headline":"WNT11 interacts with ROR2 by co-IP in human breast cancer cells; support is one paper.","interaction_type":"direct binding","direction_and_effect":"V5-WNT11 co-immunoprecipitated ROR2 in ROR2-overexpressing MCF-7 cells; the paper calls WNT11 a novel ligand for human ROR2, with agonist direction annotated [PMID:34911552].","molecular_requirements":"Curator notes say signalling acts via the ROR2 cysteine-rich domain; N-terminal deletion constructs were tested, but their co-IP result is not shown in the excerpts [PMID:34911552].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines (MCF-7, BT-474, MDA-MB-231) [PMID:34911552].","localisation_and_range":"Wnt11 is flagged secreted and ROR2 transmembrane [flag].","caveats":"Co-IP was in ROR2-overexpressing cells, and ROR2 overexpression itself induced WNT11; WNT5A is described as the established ROR2 ligand [PMID:34911552]. No affinity.","key_references":[{"PMID":"34911552","why":"WNT11 as novel ROR2 ligand: co-IP, breast cancer cells"}],"covers":["LR003476","LR006676"]},"LR006685":{"pair":"WNT3 -> FZD2","headline":"WNT3 signals through FZD2 in human HEK293T cells, shown by knockout plus rescue; mouse pair is projected from human.","interaction_type":"functional only","direction_and_effect":"Agonist: FZD1, FZD2 and FZD7 are required for Wnt3/3a-induced beta-catenin signalling, and re-expressing FZD2 or FZD7 rescues the TCF4/Wnt reporter and active beta-catenin levels [PMID:28733458].","molecular_requirements":"FZD2 alone rescues in the triple-mutant background; FZD1 and FZD7 are redundant paralogs, and co-receptor requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in HEK293T cells with multiplex CRISPR FZD knockouts [PMID:28733458]. The mouse interaction is ortholog-inferred, not tested.","localisation_and_range":"WNT3 carries a secreted annotation flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Functional rescue, not physical binding; paralog redundancy means FZD2 specificity is not isolated. Only one paper.","key_references":[{"PMID":"28733458","why":"Loss-of-function plus rescue of Wnt3 signalling by FZD2/FZD7"}],"covers":["LR003485","LR006685"]},"LR004984":{"pair":"WNT3 -> FZD7","headline":"WNT3 binds FZD7 by co-immunoprecipitation in two studies and activates beta-catenin signalling through it; the best-supported pair here.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt3 activates Wnt/beta-catenin through FZD7; FZD7 knockdown by siRNA abolished beta-catenin activation in Wnt3-overexpressing HCC cells, and co-immunoprecipitation showed a specific Wnt3-FZD7 interaction [PMID:18313787]. FZD7 binds Wnt3 and Wnt2b in intestinal stem cells; Fzd7 loss causes stem cell loss in vivo [PMID:25892522]. FZD2 or FZD7 re-expression rescues Wnt3 signalling in FZD-mutant HEK293T [PMID:28733458].","molecular_requirements":"FZD7 alone suffices for rescue of Wnt3 signalling in FZD1,2,7 mutant cells [PMID:28733458]; LRP involvement is not tested in these excerpts.","affinity_potency":[],"species_and_systems":"Human HCC cells [PMID:18313787]; epitope-tagged FZD7 and WNT3 co-immunoprecipitated in HEK293T cells, with Fzd7 knockout mice and organoids used in the same study [PMID:25892522]; human HEK293T CRISPR cells [PMID:28733458]. Mouse pair is ortholog-inferred. IntAct lists co-immunoprecipitation and pull-down records [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Co-immunoprecipitation uses overexpressed or tagged proteins; no affinity reported. Paralogs FZD1/FZD2 are redundant [PMID:28733458]. One of the intestinal paper's own sentences cites earlier work for FZD7 as a WNT3 receptor, which is background.","key_references":[{"PMID":"18313787","why":"Wnt3-FZD7 co-IP and FZD7 knockdown in HCC cells"},{"PMID":"25892522","why":"Fzd7 binds Wnt3, required for intestinal stem cells"},{"PMID":"28733458","why":"Knockout plus rescue of Wnt3 signalling"}],"covers":["LR001595","LR004984"]},"LR008089":{"pair":"WNT3 -> FZD7:LRP6","headline":"WNT3-FZD7 is supported by two abstract-level studies; LRP6 as a complex partner is not tested in our evidence.","interaction_type":"functional only","direction_and_effect":"Wnt3 binding to FZD7 decreases when both Wnt3 N-glycosylation sites (Asn90 and Asn301) are mutated, with reduced Wnt/beta-catenin proteins [PMID:38994173]. Fzd7 is reported as the Wnt3 receptor in Wnt3-regulated Foxp2 mRNA translation in neocortex; Fzd7 is required for Wnt3-induced Foxp2 translation [PMID:33525513].","molecular_requirements":"FZD7 is the evidenced subunit; LRP6 is not mentioned in the evidence shown. Glycosylation of Wnt3 at Asn90/Asn301 affects FZD7 binding [PMID:38994173].","affinity_potency":[],"species_and_systems":"HCC cells (species not stated in the dossier) [PMID:38994173]; developing neocortex neurons, species not stated in the dossier [PMID:33525513]. Both read as abstracts only. IntAct holds FZD7-related co-IP and pull-down records [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Both papers are abstract-only and tested FZD7, not the complex; the curated assay_class direct_binding for the glycosylation paper rests on confocal co-localisation.","key_references":[{"PMID":"38994173","why":"Wnt3 glycosylation sites affect FZD7 binding in HCC cells"},{"PMID":"33525513","why":"Fzd7 as Wnt3 receptor for Foxp2 translation"}],"covers":["LR008089"]},"LR004975":{"pair":"WNT3A -> FZD2","headline":"Well supported: binding and functional evidence across four abstract-level papers for WNT3A acting through FZD2.","interaction_type":"direct binding","direction_and_effect":"WNT3A activates canonical signalling through FZD2: it activated the beta-catenin pathway in FZD2-expressing 32D cells [PMID:25605717], and Fz2 was required for Wnt3a-dependent beta-catenin accumulation [PMID:19910923]. Wnt5a competed with Wnt3a for Fz2 binding and inhibited the beta-catenin pathway [PMID:19910923].","molecular_requirements":"Ror2 enhanced Wnt3a canonical signalling in H441 cells in a manner dependent on cooperation with Fzd2 [PMID:18215320]. Other co-receptor needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding competition in vitro and in intact cells, species unspecified [PMID:19910923]; bio-layer interferometry and 32D cell assays [PMID:25605717]; multiplex FZD1/FZD2/FZD7 mutant HEK293T rescue [PMID:28733458]; H441 lung carcinoma cells [PMID:18215320]. BioGRID lists Affinity Capture-Western and IntAct a bio-layer interferometry record [DB:BioGRID] [DB:IntAct].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"All four papers shown were read as abstracts (the CRISPR paper has excerpts on FZD genes generally). Seven papers are confirmed but only four are shown. No affinity value is given in our abstracts.","key_references":[{"PMID":"25605717","why":"WNT-3A activates canonical signalling through FZD2; binding mapped"},{"PMID":"19910923","why":"Wnt5a competes with Wnt3a at Fz2"},{"PMID":"28733458","why":"CRISPR FZD rescue map"}],"covers":["LR001586","LR004975"]},"LR007639":{"pair":"WNT3A -> FZD8:RYK","headline":"Cryo-EM evidence concerns Wnt3a with Fzd8 and LRP6, not RYK; the RYK part of this pair is unsupported.","interaction_type":"direct binding","direction_and_effect":"Cryo-EM structures show Wnt3a/Fzd8/LRP6 extracellular complexes in a 2:4:2 stoichiometry; each Wnt3a monomer binds two Fzd8 receptors and one LRP6 co-receptor [PMID:42202788].","molecular_requirements":"Wnt3a induces Fzd-CRD tetramerization; mutations at the Wnt3a-Wnt3a interface abolished Fzd-LRP clustering and signaling [PMID:42202788]. RYK is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in the abstract; curation records human ligand and receptor [PMID:42202788].","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"The only paper was read as abstract only and does not name RYK; it supports the Fzd8:LRP6 combination, so this pair is supported only through FZD8. IntAct records concern other partners [DB:IntAct].","key_references":[{"PMID":"42202788","why":"Cryo-EM of Wnt3a/Fzd8/LRP6 complexes"}],"covers":["LR007639"]},"LR006694":{"pair":"WNT3A -> LGR5","headline":"LGR5 joins a Wnt3a plus R-spondin1 induced complex with LRP6 and Fzd5; direct Wnt3a-LGR5 binding is not shown.","interaction_type":"functional only","direction_and_effect":"After costimulation with R-spondin1 and Wnt3a, LGR5 forms a supercomplex with LRP6 and Fzd5 that is internalised and degraded; LGR5 becomes part of the Wnt complex at the membrane and enhances signalling [PMID:22473993].","molecular_requirements":"Needs R-spondin1 as well as Wnt3a; LRP6 and Fzd5 are in the complex. A C-terminal tail deletion mutant still interacts with LRP6 [PMID:22473993].","affinity_potency":[],"species_and_systems":"Cell-based signalling and internalisation assays; human proteins [PMID:22473993]. Mouse version projected from human.","localisation_and_range":"LGR5 is flagged transmembrane [flag]; membrane-level co-assembly [PMID:22473993].","caveats":"Abstract only. The evidence describes complex co-assembly, not direct binding of Wnt3a to LGR5; the R-spondin ligand drives LGR5 function.","key_references":[{"PMID":"22473993","why":"LGR5 forms a supercomplex with LRP6/Fzd5 on Wnt3a + R-spondin1"}],"covers":["LR003494","LR006694"]},"LR003499":{"pair":"WNT4 -> FZD5","headline":"WNT4 binds FZD5 in purified protein and co-IP assays but does not activate canonical beta-catenin signalling through it.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 directly binds the FZD5 cysteine-rich domain, but in 32D cells WNT-4 did not activate the WNT-beta-catenin pathway through it; effects on DVL2 vs DVL3 phosphorylation suggest non-canonical output [PMID:25605717].","molecular_requirements":"The CRD of the Frizzled is sufficient for binding in the assay [PMID:25605717].","affinity_potency":[],"species_and_systems":"Bio-layer interferometry and 32D cells, human labelled [PMID:25605717]. Mouse version listed directly; human is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; affinity values are in a table not shown in our evidence. Curator effect label 'agonist' conflicts with the non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"WNT-FZD CRD binding kinetics and signalling"}],"covers":["LR003499","LR006699"]},"LR004993":{"pair":"WNT5A -> FZD5","headline":"Wnt5a binds the FZD5 CRD and acts through FZD5 in several systems; well supported, with agonist activity.","interaction_type":"direct binding","direction_and_effect":"hFz5 was identified as a Wnt-5A receptor: Wnt-5A induced axis duplication in Xenopus embryos in the presence of hFz5 [PMID:9054360]. FZD5 silencing reduced WNT5A binding to endometrial stem-like cells and decreased TCF/LEF activity and active beta-catenin [PMID:35295855]. Fzd5 synergized with Wnt5a in Xenopus axis induction [PMID:11092808].","molecular_requirements":"The FZD5 amino-terminal ectodomain antagonized Wnt-5A/hFz5 signalling [PMID:9054360]. LRP5 is expressed in the same cells but its role is not reported for this pair here [PMID:35295855].","affinity_potency":[{"value":"KD = 5\u201322 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD5 CRD-Fc","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins for BLI [PMID:25605717]; Xenopus embryos with human or mouse reagents [PMID:9054360][PMID:11092808]; human endometrial cells [PMID:35295855].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Three of four papers were read as abstract only; the BLI quote is from a browser read and unverified [PMID:25605717]. The Xenopus work is functional synergy rather than binding [PMID:11092808]. WNT5A is often non-canonical, yet FZD5 mediated beta-catenin activity in endometrial cells [PMID:35295855].","key_references":[{"PMID":"25605717","why":"BLI KD of WNT-5A for FZD5 CRD"},{"PMID":"9054360","why":"hFz5 identified as a Wnt-5A receptor in Xenopus"},{"PMID":"35295855","why":"FZD5 silencing reduces WNT5A binding and signalling"}],"covers":["LR001604","LR004993"]},"LR008098":{"pair":"WNT8B -> FZD8:LRP6","headline":"WNT8B activates FZD8 signalling in a reporter-cell rescue map; one functional paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT8B induced canonical (TCF/Wnt-reporter) signalling via FZD8, i.e. ligand-to-receptor agonism in a functional readout [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD8 plus LRP6; the paper's statement names only the Frizzled, and a requirement for LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008098"]},"LR008179":{"pair":"WNT9A -> FZD8:LRP5","headline":"WNT9A-FZD8 is supported by a single prostate-cancer abstract; binding is stated but not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Castration enhanced FZD8 binding to Wnt9A and mediated cellular plasticity by activating the non-canonical Wnt (FZD8/FYN/STAT3) pathway [PMID:37771187].","molecular_requirements":"Co-receptor LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Prostate cancer cells (species not stated in the abstract) [PMID:37771187].","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Abstract only; the binding assay is not described. The effect is non-canonical signalling after YY1-driven FZD8 transcription, so the evidence is context-specific. A second judged row was abstract_insufficient.","key_references":[{"PMID":"37771187","why":"Reports enhanced FZD8-Wnt9A binding and FZD8/FYN/STAT3 signalling in prostate cancer cells."}],"covers":["LR008179"]},"LR006748":{"pair":"YBX1 -> NOTCH3","headline":"Single abstract-read paper reports direct, Notch3-selective binding of soluble YBX1 with activation; Reactome also lists the complex.","interaction_type":"direct binding","direction_and_effect":"Soluble Yb-1 (YBX1) interacted specifically with Notch3 but not Notch1 in ligand-binding and signalling assays, and transduced signal to the intracellular domain through the negative regulatory region, consistent with an activating (agonist) effect [PMID:30321499].","molecular_requirements":"Notch3 EGF-like repeats 17-24 were identified as the binding site; modelling predicted the interface as repeats 20-23, different from those used by canonical DSL ligands [PMID:30321499]. Reactome lists NOTCH3 binding YBX1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; the abstract does not state the cell system. A mouse pair is listed but projected from human evidence (ortholog-inferred).","localisation_and_range":"YBX1 is flagged secreted and NOTCH3 transmembrane [flag]; the paper calls it a soluble non-canonical ligand [PMID:30321499].","caveats":"Only one paper, read as abstract only, with no affinity reported. YBX1 is an unconventional secreted ligand; the mouse pair has no experiments of its own.","key_references":[{"PMID":"30321499","why":"Soluble Yb-1 binds Notch3 EGF repeats 17-24, not Notch1"}],"covers":["LR003548","LR006748"]}};